-- ----------------------------
-- Table structure for texts
-- ----------------------------
DROP TABLE IF EXISTS "texts";
CREATE TABLE "texts" (
  "id" text,
  "name" text,
  "desc" text,
  "str1" text,
  "str2" text,
  "str3" text,
  "str4" text,
  "str5" text,
  "str6" text,
  "str7" text,
  "str8" text,
  "str9" text,
  "str10" text,
  "str11" text,
  "str12" text,
  "str13" text,
  "str14" text,
  "str15" text,
  "str16" text,
  "isok" integer,
  PRIMARY KEY ("id")
);

-- ----------------------------
-- Records of texts
-- ----------------------------
INSERT INTO "texts" VALUES ('HCG90001', '珠泪哀歌族·塞壬人鱼', '这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。这张卡从手卡特殊召唤，从自己手卡选1只怪兽送去墓地。那之后，从自己卡组上面把3张卡送去墓地。
②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90002', '大薰风骑士 翠玉', '4星怪兽×2
①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。
●以自己墓地3只怪兽为对象才能发动。那3只怪兽加入卡组洗切。那之后，自己从卡组抽1张。
●以效果怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90003', '白银之城的召使 阿里安娜', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「白银之城的召使 阿里安娜」以外的1张「拉比林斯迷宫」卡加入手卡。
②：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。自己从卡组抽1张。那之后，以下效果可以适用。
●从手卡把1只恶魔族怪兽特殊召唤或把1张魔法·陷阱卡盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90004', '复仇的女战士 罗丝', '①：这张卡给与对方战斗伤害的场合发动。给与对方300伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90005', '白银之城的拉比林斯', '这个卡名的②③的效果1回合各能使用1次。
①：对方不能对应自己的通常陷阱卡的发动把怪兽的效果发动。
②：以自己墓地1张通常陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在自己场上没有恶魔族怪兽存在的场合不能发动。
③：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。对方的手卡·场上1张卡破坏（从手卡是随机选）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90006', '熔岩炎火山的侍女', '①：这张卡被送去墓地时，自己墓地有「熔岩炎火山的侍女」以外的「熔岩」怪兽存在的场合才能发动。从卡组把1只「熔岩」怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90007', '蔷薇占术师', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：把这张卡解放才能发动。自己从卡组抽1张。
②：把墓地的这张卡除外，以自己墓地1只植物族怪兽为对象才能发动。那只怪兽加入手卡。这个效果把原本等级是7星以上的植物族怪兽加入手卡的场合，可以再从卡组把1只植物族怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90008', '赐炎之咎姬', '效果怪兽2只以上
这个卡名的②③的效果1回合各能使用1次。
①：只要这张卡在怪兽区域存在，自己不是炎属性怪兽不能特殊召唤。
②：自己主要阶段才能发动。从自己墓地把1只炎属性怪兽特殊召唤。
③：这张卡在墓地存在的状态，对方场上有怪兽特殊召唤的场合，以自己场上1只炎属性怪兽和对方场上1只怪兽为对象才能发动。那些怪兽破坏，这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90009', '王座侵略者', '反转：选择对方场上存在的1只怪兽，那只怪兽和这张卡的控制权交换。这个效果在战斗阶段不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG900010', '陷溺追蜂族！', '这个卡名的效果1回合只能使用1次。
①：自己·对方的结束阶段，把手卡·场上的这张卡送去墓地才能发动。把没有使用的对方的魔法与陷阱区域数量的卡从自己卡组上面翻开。可以从那之中选1张陷阱卡在自己场上盖放。剩下的卡用喜欢的顺序回到卡组下面。这个效果盖放的卡在下次的结束阶段送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90011', '电子化天使-韦驮天-', '「机械天使的仪式」降临。
①：这张卡仪式召唤成功的场合才能发动。从自己的卡组·墓地选1张仪式魔法卡加入手卡。
②：这张卡被解放的场合才能发动。自己场上的全部仪式怪兽的攻击力·守备力上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90012', 'G·B·猎人', '只要这张卡在场上表侧表示存在，场上存在的卡不能回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90013', '召命之神弓-阿波罗萨', '衍生物以外的卡名不同的怪兽2只以上
这张卡的③的效果在同一连锁上只能发动1次。
①：「召命之神弓-阿波罗萨」在自己场上只能有1只表侧表示存在。
②：这张卡的原本攻击力变成作为这张卡的连接素材的怪兽数量×800。
③：对方把怪兽的效果发动时才能发动。这张卡的攻击力下降800，那个发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90014', '华丽蔷薇', '调整＋调整以外的怪兽1只以上
1回合1次，可以把自己墓地存在的1只植物族怪兽从游戏中除外，对方场上表侧表示存在的1只怪兽的攻击力直到这个回合的结束阶段时变成一半数值。此外，这张卡攻击的那次战斗阶段中，可以把自己墓地存在的1只植物族怪兽从游戏中除外，这张卡的攻击力直到结束阶段时变成一半数值，只有1次再攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90015', '珠泪哀歌族型俱舍怒威族', '这个卡名的①②③的效果1回合各能使用1次。
①：自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤，从自己的手卡·墓地选1张「俱舍怒威族」卡或者「珠泪哀歌族」卡除外。
②：这张卡召唤·特殊召唤成功的场合才能发动。从自己或者对方的卡组上面把3张卡送去墓地。
③：这张卡被效果送去墓地的场合才能发动。从自己卡组上面把2张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90016', '拉比林斯迷宫欢迎', '这个卡名的①②的效果1回合各能使用1次。
①：从卡组把1只「拉比林斯迷宫」怪兽特殊召唤。这张卡的发动后，直到下个回合的结束时自己不是恶魔族怪兽不能从卡组·额外卡组特殊召唤。
②：这张卡在墓地存在的状态，自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。这张卡在自己场上盖放。这个效果在这张卡送去墓地的回合不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90017', '荒野的女战士', '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的战士族·地属性怪兽攻击表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90018', '心理咨询师 莉莉', '这张卡被同调怪兽的同调召唤使用送去墓地的场合，可以支付500基本分让这张卡为同调素材的同调怪兽的攻击力直到这个回合的结束阶段时上升1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90019', '珠之御巫 狐理', '这个卡名的③的效果1回合只能使用1次。
①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。
②：只要自己场上有装备卡存在，自己场上的「御巫」卡不会成为对方的效果的对象。
③：这张卡有装备卡被装备的场合才能发动。从卡组把1张「御巫」陷阱卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90020', '异次元的女战士', '①：这张卡和对方怪兽进行战斗的伤害计算后才能发动。那些进行战斗的各自怪兽除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90021', '熔岩炎湖畔的淑女', '自己墓地有名字带有「熔岩」的怪兽3种类以上存在的场合，把自己墓地存在的这张卡和1只名字带有「熔岩」的怪兽从游戏中除外才能发动。选择对方场上盖放的1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90022', '暗影之暗灵使 达克', '包含暗属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只暗属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的暗属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90023', '天使之泪', '①：选自己1张手卡加入对方手卡。那之后，自己回复2000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90024', '魔救之奇迹-巨龙晶石', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以选最多有那之中的岩石族怪兽数量的对方场上的卡回到持有者手卡。翻开的卡用喜欢的顺序回到卡组最下面。
②：自己墓地有水属性怪兽存在，对方把魔法·陷阱卡的效果发动时才能发动。那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90025', '薰风的神官 穆斯托', '可以选择自己墓地存在的1只名字带有「薰风」的怪兽回到卡组，选择场上表侧表示存在的1只怪兽把那个效果直到结束阶段时无效。这个效果1回合只能发动1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90026', '照耀之光灵使 莱娜', '包含光属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只光属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的光属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90027', '王座守护者', '国王离开时，保卫王座不受外敌攻击的王妃。守备力高。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90028', '电子化冰刀手', '「电子化明星」＋「利刃滑冰者」
这张卡的融合召唤不用上记的卡不能进行。
①：对方场上的怪兽数量让这张卡得到以下效果。
●1只：这张卡不会被战斗破坏。
●2只：这张卡的攻击力变成2倍。
●3只：对方发动的卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90029', '由魔界到现世的死亡导游', '①：这张卡召唤成功时才能发动。从手卡·卡组把1只恶魔族·3星怪兽特殊召唤。这个效果特殊召唤的怪兽效果无效化，不能作为同调素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90030', '魔救之分析者', '这个卡名的①②的效果1回合各能使用1次。
①：只有对方场上才有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只调整以外的4星以下的岩石族怪兽特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90031', '电子化明星', '这张卡直接攻击对方玩家的场合，伤害步骤内攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90032', '电子界魔女', '电子界族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡所连接区有怪兽特殊召唤的场合，从自己墓地把1张魔法卡除外才能发动。从卡组把1只电子界族仪式怪兽和1张「电脑网仪式」加入手卡。
②：这张卡的①的效果发动的回合的自己主要阶段，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90033', '椿姬 提泰妮娅', '①：场上的卡为对象的魔法·陷阱·怪兽的效果发动时，把自己场上1只表侧表示的植物族怪兽解放才能发动。那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90034', '超级量子战士 蓝光层', '「超级量子战士 蓝光层」的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功时才能发动。从卡组把「超级量子战士 蓝光层」以外的1张「超级量子」卡加入手卡。
②：这张卡被送去墓地的场合，以自己墓地最多3张「超级量子」卡为对象才能发动。那些卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90035', '神力女武神', '勇敢的光之天使。出于那强烈的正义感，明知必败也决不逃避与邪恶的战斗。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90036', '女剑士 迦南', '像蝴蝶飞舞像蜜蜂蜇人，双手持剑与盾的女战士。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90037', '破灭之美神 露茵', '「世界不灭」降临。
①：这张卡的卡名只要在手卡·场上存在当作「破灭之女神 露茵」使用。
②：只要仪式召唤的这张卡在怪兽区域存在，自己场上的仪式怪兽不会被效果破坏。
③：只使用仪式怪兽作仪式召唤的这张卡在同1次的战斗阶段中可以作2次攻击。
④：这张卡战斗破坏对方怪兽的场合才能发动。给与对方那只怪兽的原本攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90038', '光界王战 玛多尔女王', '这个卡名的②的效果1回合只能使用1次。
①：「光界王战 玛多尔女王」在自己场上只能有1只表侧表示存在。
②：这张卡召唤·特殊召唤成功的场合才能发动。「光界王战 玛多尔女王」以外的，1张「王战」卡或者1只植物族怪兽从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90039', '芳香法师-月桂叶', '这个卡名的①②③的效果1回合各能使用1次。
①：自己基本分比对方多的场合才能发动。这张卡从手卡特殊召唤。
②：自己基本分回复的场合，以场上1只植物族怪兽为对象发动。这个回合，那只怪兽当作调整使用。
③：这张卡被送去墓地的场合才能发动。自己回复500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90040', '冰之女王', '这张卡不能作从墓地的特殊召唤。自己场上表侧表示存在的这张卡被破坏送去墓地时，自己墓地的魔法师族怪兽是3只以上的场合，可以从自己墓地选择1张魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90041', '灵兽使的长老', '自己对「灵兽使的长老」1回合只能有1次特殊召唤。
①：这张卡召唤时适用。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「灵兽」怪兽召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90042', '灰流丽', '这个卡名的效果1回合只能使用1次。
①：包含以下其中任意种效果的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个效果无效。
●从卡组把卡加入手卡的效果
●从卡组把怪兽特殊召唤的效果
●从卡组把卡送去墓地的效果', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90043', '熔岩炎树海的妖女', '这张卡从场上送去墓地时，自己场上表侧表示存在的名字带有「熔岩」的怪兽的攻击力直到结束阶段时上升自己墓地存在的名字带有「熔岩」的怪兽数量×200的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90044', '御巫神乐', '「御巫」仪式怪兽的降临必需。这个卡名的卡在1回合只能发动1张。
①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「御巫」仪式怪兽仪式召唤。那之后，以下效果可以适用。
●选最多有自己墓地的装备魔法卡种类数量的对方场上的卡破坏，给与对方破坏数量×1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90045', '御巫的祓舞', '「御巫」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。
①：装备怪兽不会被效果破坏。
②：对方场上有怪兽特殊召唤的场合，以自己以及对方场上的怪兽各1只为对象才能发动。那些怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90046', '芳香炽天使-欧白芷', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方回合，把这张卡从手卡丢弃，以自己墓地1只「芳香」怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力的数值。
②：这张卡在墓地存在，自己基本分比对方多，自己场上有「芳香」怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90047', '斩首的美女', '在那美丽容貌的背后，却是个用刀子使许多人身首异处的女子。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90048', '黑蔷薇之魔女', '这张卡不能特殊召唤。
①：自己场上没有其他卡存在，这张卡召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是怪兽以外的场合，那张卡送去墓地，这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90049', '剑之御巫 波礼', '这个卡名的②的效果1回合只能使用1次。
①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。
②：这张卡有装备卡被装备的场合才能发动。从卡组把1张「御巫」装备魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90050', '沉默魔导剑士', '①：这张卡召唤成功时才能发动。从卡组把1只「沉默剑士 LV3」或者「沉默魔术师 LV4」加入手卡。
②：只在这张卡在场上表侧表示存在才有1次，只以自己场上的怪兽1只为对象的魔法卡发动时才能发动。那个发动无效。
③：场上的这张卡被战斗或者对方的效果破坏的场合，以自己墓地1只光属性「LV」怪兽为对象才能发动。那只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90051', '怀抱圣剑的王后 桂妮薇儿', '「怀抱圣剑的王后 桂妮薇儿」的①的效果1回合只能使用1次。
①：以自己场上1只「圣骑士」怪兽为对象才能发动。手卡·墓地的这张卡当作攻击力上升300的装备卡使用给那只自己怪兽装备。
②：得到装备怪兽的属性的以下效果。
●光：装备怪兽被效果破坏的场合，可以作为代替把这张卡破坏。
●暗：装备怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。那之后这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90052', '慧炎星-扈三雀', '「炎星」怪兽2只
这个卡名的②的效果1回合只能使用1次。
①：只要这张卡所连接区有「炎星」怪兽存在，对方不能选择这张卡作为攻击对象。
②：这张卡的攻击宣言时把自己场上1张表侧表示的「炎舞」魔法·陷阱卡送去墓地，以对方场上1只怪兽为对象才能发动。直到结束阶段，那只对方怪兽在这张卡所连接区放置得到控制权。这个效果得到控制权的怪兽不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90053', '芳香炽天使-茉莉', '植物族怪兽2只
这个卡名的②的效果1回合只能使用1次。
①：自己基本分比对方多的场合，这张卡以及这张卡所连接区的植物族怪兽不会被战斗破坏。
②：把这张卡所连接区1只自己怪兽解放才能发动。从卡组把1只植物族怪兽守备表示特殊召唤。
③：1回合1次，自己基本分回复的场合发动。从卡组把1只植物族怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90054', '森罗的舞蹈娘 先锋葡萄', '植物族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡连接召唤成功的场合才能发动。从自己卡组上面把最多3张卡翻开。那之中有植物族怪兽的场合，可以选那之内的最多2只特殊召唤。剩下的卡送去墓地。这个效果特殊召唤的怪兽不能作为连接素材。
②：以自己墓地1只植物族怪兽为对象才能发动。这张卡所连接区的怪兽的等级直到回合结束时变成和作为对象的怪兽相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90055', '轨迹之魔术师', '包含灵摆怪兽的效果怪兽2只
这个卡名的②的效果1回合只能使用1次。
①：这张卡在额外怪兽区域连接召唤的场合，支付1200基本分才能发动。从卡组把1只灵摆怪兽加入手卡。这个回合自己只要灵摆召唤不成功，不能把怪兽的效果发动，自己的灵摆区域的卡的效果无效化。
②：这张卡所连接区有原本等级不同的怪兽2只同时灵摆召唤的场合，以场上2张卡为对象才能发动。那些卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90056', '冥界的丽人 伊索德', '这张卡不用这张卡的①的方法不能特殊召唤。这个卡名的②的效果1回合只能使用1次。
①：自己场上有「冥界骑士 崔斯坦」存在的场合，这张卡可以从手卡特殊召唤。
②：以自己场上最多2只不死族怪兽为对象，宣言5～8的任意等级才能发动。那些怪兽直到回合结束时变成宣言的等级。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90057', '蔷薇之魔女', '植物族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90058', '圣夜骑士团·瑞尔', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤成功时才能发动。从卡组把1张「圣夜骑士」魔法·陷阱卡加入手卡。
②：把墓地的这张卡除外，以「圣夜骑士团·瑞尔」以外的自己墓地1只「圣夜骑士」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90059', '增殖的G', '这个卡名的效果1回合只能使用1次。
①：自己·对方回合，把这张卡从手卡送去墓地才能发动。这个回合中，以下效果适用。
●每次对方把怪兽特殊召唤，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90060', '精灵兽使 蕾拉', '自己对「精灵兽使 蕾拉」1回合只能有1次特殊召唤，那些作为①②③的效果1回合各能使用1次。
①：把这张卡从手卡丢弃才能发动。进行手卡1只「灵兽」怪兽的召唤。
②：自己场上的「灵兽」卡被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。
③：这张卡被除外的场合才能发动。从卡组把「精灵兽使 蕾拉」以外的1只「灵兽」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90061', '魅惑的女王 LV5', '用「魅惑的女王 LV3」的效果特殊召唤的场合，1回合只有1次在自己的主要阶段时可以选择对方场上的1只5星以下的怪兽，当作装备卡使用装备在这张卡上（这个效果可以装备的装备卡最多1张）。这张卡被战斗破坏的场合，装备的怪兽代替破坏。自己回合的准备阶段时，可以把因这个效果装备有装备卡的这张卡送去墓地，从手卡·卡组特殊召唤1只「魅惑的女王 LV7」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90062', '阿瓦隆的魔女 摩根', '这个卡名的效果1回合只能使用1次。
①：自己场上有「圣骑士」怪兽以及「圣剑」装备魔法卡存在，对方把魔法·陷阱·怪兽的效果发动时，把这张卡从手卡送去墓地才能发动。选自己场上1张「圣剑」装备魔法卡破坏，那个发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90063', '刚炼装勇士·银金公主', '灵摆怪兽2只
这个卡名的③的效果1回合只能使用1次。
①：这张卡连接召唤的场合才能发动。从卡组把1只灵摆怪兽表侧加入额外卡组。
②：1回合1次，以自己场上1张其他的表侧表示卡为对象才能发动。那张卡破坏。那之后，从自己的额外卡组（表侧）把1只灵摆怪兽加入手卡。
③：自己的灵摆区域的卡从场上离开的场合发动。自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90064', '流星龙', '同调怪兽调整＋「星尘龙」
①：1回合1次，可以发动。从自己卡组上面翻开5张并回到卡组。这个回合这张卡可以作出最多有所翻开之中的调整数量的攻击。
②：1回合1次，要让场上的卡破坏的效果的发动时才能发动。那个效果无效并破坏。
③：1回合1次，对方的攻击宣言时以攻击怪兽为对象才能发动。场上的这张卡除外，那次攻击无效。
④：这个③的效果除外的回合的结束阶段发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90065', '禁忌的圣杯', '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力上升400，效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90066', '圣菓使 考维曲天使', '←1 【灵摆】 1→
这个卡名的灵摆效果1回合只能使用1次。
①：另一边的自己的灵摆区域没有卡存在的场合才能发动。从自己的额外卡组选1只表侧表示的灵摆怪兽在自己的灵摆区域放置。
【怪兽效果】
灵摆怪兽×2
①：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90067', '禁忌的圣枪', '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力下降800，不受这张卡以外的魔法·陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90068', '永远的淑女 贝阿特丽切', '6星怪兽×2
这张卡也能把手卡1只「彼岸」怪兽送去墓地，在自己场上的「但丁」怪兽上面重叠来超量召唤。这个方法特殊召唤的回合，这张卡的①的效果不能发动。
①：自己·对方回合1次，把这张卡1个超量素材取除才能发动。从卡组选1张卡送去墓地。
②：这张卡被对方破坏送去墓地的场合才能发动。从额外卡组把1只「彼岸」怪兽无视召唤条件特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90069', '不幸的少女', '以表侧攻击表示存在的这张卡不会被战斗破坏。只要这张卡以表侧攻击表示存在于场上，与这张卡进行过战斗的怪兽不能再攻击及改变表示形式。（伤害计算适用）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90070', '七音服的优雅装', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。
●从卡组选1只「七音服」灵摆怪兽在自己的灵摆区域放置。
●从手卡选1只「七音服」灵摆怪兽表侧表示加入额外卡组。那之后，从卡组选灵摆刻度是奇数和偶数的「七音服」灵摆怪兽各1只在自己的灵摆区域放置。
●从自己的灵摆区域把灵摆刻度是奇数和偶数的卡各1张表侧表示加入持有者的额外卡组，自己从卡组抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90071', '薰风的贤者 温达尔', '这张卡战斗破坏怪兽送去墓地时，可以把自己墓地存在的1只3星以下的名字带有「薰风」的怪兽表侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90072', '拉之七音服·安琪莉娅', '←3 【灵摆】 3→
①：在自己的「七音服」灵摆怪兽的灵摆召唤成功时对方不能把怪兽的效果·魔法·陷阱卡发动。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：自己主要阶段才能发动。自己场上1只「七音服」灵摆怪兽解放，比那只怪兽灵摆刻度高2或者低2的「拉之七音服·安琪莉娅」以外的1只「七音服」灵摆怪兽从卡组特殊召唤。
②：自己的灵摆区域有奇数的灵摆刻度存在，自己的「七音服」灵摆怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡的效果不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90073', '米之七音服·埃莉蒂娅', '←6 【灵摆】 6→
①：自己的「七音服」灵摆怪兽的灵摆召唤不会被无效化。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡。
②：只要自己的灵摆区域有偶数的灵摆刻度存在，自己的「七音服」灵摆怪兽的战斗发生的对自己的战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90074', '珠泪哀歌族·卡雷多哈特', '「珠泪哀歌族·雷诺哈特」＋水族怪兽×2
这张卡不能作为融合素材。这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合或者这张卡在场上存在的状态有水族怪兽被效果送去自己墓地的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者卡组。
②：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤，从卡组把1张「珠泪哀歌族」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90075', '雪暴公主', '这张卡可以把1只魔法师族怪兽解放表侧攻击表示上级召唤。这张卡召唤成功的回合，对方不能把魔法·陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90076', '红莲蔷薇之魔女', '这个卡名的①②的效果1回合各能使用1次。
①：把这张卡解放才能发动。从卡组把1只「黑蔷薇之魔女」加入手卡，从卡组选1只3星以下的植物族怪兽在卡组最上面放置。那之后，可以从手卡把1只「黑蔷薇之魔女」召唤。
②：把墓地的这张卡除外才能发动。从自己墓地的怪兽或者除外的自己怪兽之中选1只「黑蔷薇龙」或者「红莲蔷薇龙」回到额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90077', '蔷薇少女', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：自己场上的表侧表示的植物族怪兽被送去墓地的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡在墓地存在，场上有植物族怪兽存在的场合才能发动。这张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90078', 'S：P小夜', '效果怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡用融合·同调·超量·连接怪兽的其中任意种为素材作连接召唤的场合，以自己或对方的场上·墓地1张卡为对象才能发动。那张卡除外。这个回合，自己怪兽不能直接攻击。
②：对方的效果发动时，以包含自己场上的怪兽的场上2只表侧表示怪兽为对象才能发动。那2只怪兽直到结束阶段除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90079', '对手见冤家', '这个卡名的卡在1回合只能发动1张。
①：自己·对方的战斗阶段才能发动。把1只怪兽召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90080', '大薰风的球风', '调整＋调整以外的「薰风」怪兽1只以上
①：这张卡同调召唤成功时，以自己墓地1张「薰风」卡为对象才能发动。那张卡加入手卡。
②：这张卡不会被战斗破坏。
③：只要这张卡在怪兽区域存在，自己的「薰风」怪兽的战斗发生的对自己的战斗伤害由对方代受。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90081', '七音服的调和', '①：可以从以下效果选择1个发动。「七音服的调和」的以下效果1回合各能选择1次。
●从自己的额外卡组把1只表侧表示的「七音服」灵摆怪兽加入手卡。
●选自己的灵摆区域1张「七音服」卡。这个回合，那个灵摆刻度上升那张卡的等级数值。
●自己场上的「七音服」灵摆怪兽卡的灵摆刻度是奇数3种类以上或者偶数3种类以上的场合，选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90082', '混沌之魔女', '这个卡名的①②的效果1回合只能有1次使用其中任意1个，发动的回合，自己不是光·暗属性的同调怪兽不能从额外卡组特殊召唤。
①：把这张卡解放才能发动。在自己场上把2只「黑兽衍生物」（恶魔族·暗·2星·攻1000/守500）特殊召唤。
②：这张卡从手卡·墓地除外的场合才能发动。在自己场上把2只「白兽衍生物」（天使族·调整·光·2星·攻500/守1000）特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90083', '苍翠之风灵使 薇茵', '包含风属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只风属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的风属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90084', '混沌之女神', '光属性调整＋调整以外的暗属性怪兽2只以上
①：1回合1次，从手卡把1只光属性怪兽送去墓地，以自己墓地1只5星以上的暗属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽不能作为同调素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90085', '织翼者', '六翼天使操纵着人的自由和希望。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90086', '圣魔术师', '①：这张卡反转的场合，以自己墓地1张魔法卡为对象发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90087', '地狱女帝恶魔', '这张卡以外的场上表侧表示存在的恶魔族·暗属性怪兽1只被破坏的场合，可以作为代替把自己墓地存在的1只恶魔族·暗属性怪兽从游戏中除外。此外，场上存在的这张卡被破坏送去墓地时，可以选择「地狱女帝恶魔」以外的自己墓地存在的1只恶魔族·暗属性·6星以上的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90088', '增援', '①：从卡组把1只4星以下的战士族怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90089', '精灵神后 树精', '这张卡不能通常召唤。自己·对方的墓地的怪兽属性是6种类以上的场合才能特殊召唤。
①：这张卡的攻击力·守备力上升自己·对方的墓地的怪兽的属性种类×500。
②：对方把怪兽特殊召唤之际，把自己墓地3只怪兽除外才能发动。那次特殊召唤无效，那些怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90090', '威光魔人', '这张卡不能特殊召唤。只要这张卡在场上表侧表示存在，双方不能把效果怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90091', '壹世坏涡旋的反响', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：从自己的卡组·墓地选1只「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」特殊召唤。那之后，选种族或者属性和这个效果特殊召唤的怪兽相同的自己场上1只怪兽送去墓地。
②：这张卡被效果送去墓地的场合，以除外的1张自己的「珠泪哀歌族」陷阱卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90092', '森罗的姬芽宫', '1星怪兽×2
「森罗的姬芽宫」的①②的效果1回合各能使用1次。
①：把这张卡1个超量素材取除才能发动。自己卡组最上面的卡翻开。翻开的卡是魔法·陷阱卡的场合，那张卡加入手卡。不是的场合，那张卡送去墓地。
②：从手卡以及这张卡以外的自己场上的表侧表示怪兽之中把1只植物族怪兽送去墓地，以自己墓地1只「森罗」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90093', '守护者·艾托斯', '①：自己墓地没有怪兽存在的场合，这张卡可以从手卡特殊召唤。
②：把这张卡装备的自己场上1张装备魔法卡送去墓地，以对方墓地最多3只怪兽为对象才能发动。那些怪兽除外。这张卡的攻击力直到回合结束时上升这个效果除外的怪兽数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90094', '俱利伽罗天童', '这张卡不能通常召唤。把这个回合有在对方的怪兽区域把效果发动过的自己·对方场上的表侧表示怪兽全部解放的场合才能特殊召唤。这个卡名的②的效果1回合只能使用1次。
①：这张卡的攻击力上升因为这张卡特殊召唤而解放的怪兽数量×1500。
②：自己结束阶段，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90095', '围绕圣剑的王姬 安洁莉卡', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把1张有「焰圣骑士帝-查理」的卡名记述的卡或者「象牙角笛」加入手卡。
②：场上的这张卡成为攻击·效果的对象时才能发动。从卡组把1只战士族·炎属性怪兽送去墓地，这张卡直到结束阶段除外。那之后，可以从卡组·额外卡组把1只「罗兰」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90096', '薰风的疾风 莉兹', '让1张手卡回到卡组最下面，选择对方场上存在的1只怪兽和自己场上表侧表示存在的1只名字带有「薰风」的怪兽发动。选择的怪兽的控制权交换。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90097', '珠泪哀歌族·小美人鱼', '这个卡名的①②的效果1回合各能使用1次。
①：对方把场上的怪兽的效果发动时才能发动。这张卡从手卡特殊召唤，从自己卡组上面把3张卡送去墓地。
②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90098', '地灵使 奥丝', '①：这张卡反转的场合，以对方场上1只地属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90099', '大钢琴之七音服·缪塞西娅', '灵摆怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从手卡把1只灵摆怪兽表侧表示加入额外卡组，把持有若那个灵摆刻度是奇数则为偶数的、是偶数则为奇数的灵摆刻度的1只表侧表示的灵摆怪兽从自己的额外卡组加入手卡。
②：自己对「七音服」怪兽的灵摆召唤成功时，以那之内的1只为对象才能发动。和那只怪兽的灵摆刻度数值相同等级的1只「七音服」灵摆怪兽从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG900100', '黑魔术少女', '①：这张卡的攻击力上升双方墓地的「黑魔术师」「黑混沌之魔术师」数量×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90101', '芳香炽天使-迷迭香', '调整＋调整以外的怪兽1只以上
①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己场上的植物族怪兽的攻击力·守备力上升500。
②：1回合1次，自己基本分回复的场合，以对方场上1张表侧表示卡为对象发动。那张卡的效果直到回合结束时无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90102', '女神诗蔻蒂的托宣', '这个卡名的卡在1回合只能发动1张。
①：作为这张卡的发动时的效果处理，自己场上的怪兽只有「女武神」怪兽的场合，可以从卡组把1张「女神薇儿丹蒂的引导」加入手卡。
②：1回合1次，自己主要阶段才能发动。从对方卡组上面把3张卡确认，用喜欢的顺序回到卡组上面。这个效果的发动后，直到回合结束时自己不是天使族怪兽不能召唤·特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90103', '音女', '擅长操纵声音的少女，能使音符变成镰刀攻击敌人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90104', '暗黑界的龙神王 格拉法', '「暗黑界的龙神 格拉法」＋暗属性怪兽
这个卡名的①的效果1回合只能使用1次。
①：对方把怪兽的效果·通常魔法·通常陷阱卡发动时才能发动。那个效果变成「对方选自身1张手卡丢弃」。
②：融合召唤的这张卡因对方从场上离开的场合才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只「暗黑界的龙神 格拉法」特殊召唤。那之后，有手卡的玩家选自身1张手卡丢弃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90105', '电子化天使-荼吉尼-', '「机械天使的仪式」降临。
①：这张卡仪式召唤成功的场合才能发动。对方必须把自身场上1只怪兽送去墓地。
②：只要这张卡在怪兽区域存在，自己的仪式怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。
③：自己结束阶段以自己墓地1只仪式怪兽或者1张「机械天使的仪式」为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90106', '芳香法师-马郁兰', '这个卡名的①③的效果1回合各能使用1次。
①：自己的植物族怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。那之后，自己回复500基本分。
②：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己的植物族怪兽的战斗发生的对自己的战斗伤害变成0。
③：自己基本分回复的场合，以最多有自己场上的「芳香」怪兽数量的对方墓地的卡为对象发动。那些卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90107', '极星天 女武神', '①：这张卡召唤成功时，对方场上有怪兽存在，自己场上没有这张卡以外的卡存在的场合，从手卡把2只「极星」怪兽除外才能发动。在自己场上把2只「英灵衍生物」（战士族·地·4星·攻/守1000）守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90108', '灵兽使 文', '自己对「灵兽使 文」1回合只能有1次特殊召唤。
①：这张卡召唤的场合，以自己的除外状态的1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90109', '沉默魔术师', '这张卡不能通常召唤。把自己场上1只魔法师族怪兽解放的场合才能特殊召唤。
①：这张卡的攻击力上升自己手卡数量×500。
②：1回合1次，魔法卡发动时才能发动。那个发动无效。
③：场上的这张卡被战斗或者对方的效果破坏的场合才能发动。从手卡·卡组把「沉默魔术师」以外的1只「沉默魔术师」怪兽无视召唤条件特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90110', '电子化芭蕾练习裙', '①：这张卡可以从自己的手卡·场上把1只战士族或者天使族怪兽解放从手卡特殊召唤。
②：这张卡为仪式召唤而被解放的场合，以自己墓地1张仪式魔法卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90111', '御巫之契', '这个卡名的卡在1回合只能发动1张。
①：从手卡·卡组把1只「御巫」怪兽特殊召唤。那之后，可以从自己的手卡·墓地选1张那只怪兽可以装备的装备魔法卡给那只怪兽装备。这个效果特殊召唤的怪兽从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90112', '蔷薇妖精', '这张卡被魔法·陷阱·效果怪兽的效果从自己卡组加入手卡的场合，这张卡可以在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90113', '传承的大御巫', '这个卡名的①②的效果1回合各能使用1次。
①：从手卡把1只「御巫」怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在对方结束阶段回到持有者手卡。
②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把「传承的大御巫」以外的1张「御巫」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90114', '影六武众-初芽', '这个卡名的①的效果1回合只能使用1次。
①：从自己墓地以及自己场上的表侧表示怪兽之中把2只「六武众」怪兽除外，以「影六武众-初芽」以外的自己墓地1只「六武众」怪兽为对象才能发动。那只怪兽特殊召唤。
②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90115', '念力通灵保健师', '调整＋调整以外的怪兽1只以上
把自己墓地存在的1只念动力族怪兽从游戏中除外发动。自己回复1200基本分。这个效果1回合只能使用1次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90116', '地狱荆棘', '调整＋调整以外的植物族怪兽1只以上
只要这张卡在场上表侧表示存在，双方必须为从手卡把植物族怪兽以外的怪兽召唤·特殊召唤支付每1只1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90117', '神圣魔皇后 塞勒涅', '包含魔法师族怪兽的怪兽2只以上
①：这张卡连接召唤成功的场合发动。双方的场上·墓地的魔法卡数量的魔力指示物给这张卡放置。
②：只要场上有「恩底弥翁」卡存在，对方不能选择这张卡作为攻击对象。
③：1回合1次，自己·对方的主要阶段，把自己场上3个魔力指示物取除才能发动。从自己的手卡·墓地选1只魔法师族怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90118', '引导的圣女 奎姆', '这个卡名在规则上也当作「教导」卡、「死狱乡」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。把1只「阿不思的落胤」或者1张有那个卡名记述的卡从卡组送去墓地。
②：自己·对方的卡从额外卡组离开的场合，以除「引导的圣女 奎姆」外的自己墓地1只「阿不思的落胤」或者1只有那个卡名记述的怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90119', '破灭之女神 露茵', '「世界末日」降临。
①：这张卡的攻击破坏对方怪兽时才能发动。这张卡只再1次可以继续攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90120', '新式魔厨的鱼料理天使', '←8 【灵摆】 8→
这个卡名的灵摆效果1回合只能使用1次。
①：自己场上有仪式怪兽存在的场合，以场上1只怪兽为对象才能发动。这张卡特殊召唤。那之后，作为对象的怪兽的表示形式变更。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：这张卡召唤·特殊召唤的场合，可以从以下效果选择1个发动。
●把1只1星仪式怪兽或者1张「食谱」卡从卡组加入手卡。
●从自己墓地把「食谱」卡任意数量除外，把持有和那个数量相同等级的1只「新式魔厨」仪式怪兽从手卡特殊召唤。
②：场上的这张卡被解放以表侧加入额外卡组的场合才能发动。这张卡在自己的灵摆区域放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90121', '虚无魔人', '这张卡不能特殊召唤。
①：只要这张卡在怪兽区域存在，双方不能把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90122', '圣灵兽骑 雷鹰', '「灵兽使」怪兽＋「精灵兽」怪兽
把自己场上的上记的卡除外的场合才能特殊召唤。
①：1回合1次，以自己的除外状态的2张「灵兽」卡为对象才能发动。那些卡回到墓地，从卡组把1张「灵兽」卡加入手卡。
②：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。', '回收除外的卡并检索', '回到额外卡组并特殊召唤除外的怪兽', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90123', '魔救之追求者', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「魔救之追求者」以外的「魔救」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只调整以外的4星以下的岩石族怪兽特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90124', '凶导的白圣骸', '「凶导的葬列」降临。这个卡名的③的效果1回合只能使用1次。
①：这张卡仪式召唤成功的场合，以场上2只表侧表示怪兽为对象才能发动。那之内1只的攻击力上升另1只的攻击力数值。
②：8星以上的自己的「教导」怪兽不会被战斗破坏。
③：从对方的额外卡组有怪兽特殊召唤的场合才能发动。把对方的额外卡组确认，选那之内的1只怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90125', '灼热之火灵使 希塔', '包含炎属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只炎属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的炎属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90126', 'No.83 银河女王', '1星怪兽×3
①：1回合1次，把这张卡1个超量素材取除才能发动。自己场上的全部怪兽直到对方回合结束时不会被战斗破坏，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90127', '混沌之战士 混沌战士', '卡名不同的怪兽3只
①：这张卡是已用7星以上的怪兽为素材作连接召唤的场合，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。
②：这张卡战斗破坏对方怪兽时，可以从以下效果选择1个发动。
●这张卡的攻击力上升1500。
●这张卡在下次的自己回合的战斗阶段中可以作2次攻击。
●场上1张卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90128', '电子化芭蕾裙', '对方场上存在的全部怪兽的攻击力都比这张卡的攻击力高的场合，这张卡可以直接攻击对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90129', '魔天使 蔷薇之巫师', '这张卡可以让「魔天使 蔷薇之巫师」以外的自己场上表侧表示存在的1只植物族怪兽回到手卡，从手卡特殊召唤。这个方法特殊召唤的这张卡从场上离开的场合从游戏中除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90130', '破灭之天使 露茵', '「世界不灭」降临。
①：这张卡的卡名只要在手卡·场上存在当作「破灭之女神 露茵」使用。
②：这张卡仪式召唤成功的场合发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。
③：这张卡被送去墓地的场合，以自己场上1只仪式怪兽为对象才能发动。只要那只怪兽在自己场上表侧表示存在，在自己的仪式怪兽的攻击宣言时对方不能把卡的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90131', '魅惑的女王 LV7', '用「魅惑的女王 LV5」的效果特殊召唤的场合，1回合只有1次在自己主要阶段时可以选择对方场上的1只怪兽，当作装备卡使用装备在这张卡上（这个效果可以装备的装备卡最多1张）。这张卡被战斗破坏的场合，装备的怪兽代替破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90132', '缓存猫娃L2', '这个卡名的效果1回合只能使用1次。
①：这张卡在手卡存在的场合，以自己场上1只3星以上的怪兽为对象才能发动。那只怪兽的等级下降2星，这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90133', '不幸的美少女', '这张卡被战斗破坏送去墓地，当时那个回合的战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90134', '蔷薇之圣弓手', '自己场上有植物族怪兽存在，对方把陷阱卡发动时，把这张卡从手卡送去墓地才能发动。那个发动无效并破坏。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90135', '朔夜时雨', '这个卡名的效果1回合只能使用1次。
①：对方把怪兽表侧表示特殊召唤的场合，把这张卡从手卡丢弃，以那1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效化，这个回合中作为对象的表侧表示怪兽从场上离开的场合，那个控制者受到作为对象的怪兽的原本攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90136', '转晶之矿物协调者', '效果怪兽2只
这个卡名的②的效果1回合只能使用1次。
①：连接状态的这张卡以及这张卡所连接区的怪兽不会被对方的效果破坏。
②：这张卡所连接区有怪兽2只存在的场合才能发动。那2只怪兽的控制权交换。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90137', '魔界斗士 屠龙之剑', '调整＋调整以外的怪兽1只以上
这张卡被卡的效果破坏送去墓地时，可以从自己墓地选择这张卡以外的1只4星以下的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90138', '由魔界到现世的巴士', '这张卡被送去墓地时，选择「由魔界到现世的巴士」以外的自己或者对方的墓地1只怪兽回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90139', '御巫神隐', '这个卡名的①②的效果1回合各能使用1次。
①：以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽给自己场上1只「御巫」怪兽当作装备魔法卡使用来装备。场上有仪式怪兽卡存在的场合，可以再给与对方为自己场上的装备魔法卡数量×500伤害。
②：把墓地的这张卡除外才能发动。自己的手卡·除外状态的1只「御巫」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90140', '花园蔷薇少女', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1张「黑色花园」加入手卡。
②：把墓地的这张卡除外，以自己墓地1只「蔷薇龙」怪兽或龙族同调怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90141', '圆唤师 仙女', '这个卡名的①的方法的特殊召唤1回合只能有1次。
①：自己或者对方的墓地有昆虫族·植物族怪兽的其中任意种存在的场合，这张卡可以从手卡特殊召唤。
②：把自己场上的这张卡作为昆虫族·植物族同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90142', '心眼之女神', '这张卡可以代替融合怪兽素材的其中1只来融合。这个时候，其他的融合素材必须是指定的融合素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90143', '混沌女武神', '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。
①：从自己墓地把1只光属性或者暗属性的怪兽除外才能发动。这张卡从手卡特殊召唤。
②：这张卡被除外的场合才能发动。从卡组把1只光属性或者暗属性的怪兽送去墓地。这个回合，自己不能把这个效果送去墓地的卡以及那些同名卡的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90144', '发之七音服·凡西娅', '←5 【灵摆】 5→
①：自己的「七音服」灵摆怪兽的灵摆召唤不会被无效化。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：自己主要阶段才能发动。从卡组选「发之七音服·凡西娅」以外的1只「七音服」灵摆怪兽表侧表示加入额外卡组。
②：自己的灵摆区域有奇数的灵摆刻度存在，自己的「七音服」灵摆怪兽被战斗破坏的场合，可以作为代替把这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90145', 'No.29 招财猫人偶', '2星怪兽×2
这个卡名的②的效果1回合只能使用1次。
①：1回合1次，把这张卡1个超量素材取除，以对方墓地1只怪兽为对象才能发动。那只怪兽在对方场上特殊召唤。
②：这张卡已在怪兽区域存在的状态，对方场上有怪兽特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。从自己的手卡·卡组·墓地选种族或者属性和那只怪兽相同的1只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90146', '薰风的巫女 薇茵妲', '这张卡被对方怪兽的攻击破坏送去墓地时，可以从自己卡组把1只名字带有「薰风」的调整特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90147', '禁忌的圣典', '①：双方怪兽进行战斗的伤害计算时才能发动。直到伤害步骤结束时，这张卡以外的场上的卡的效果无效化，那次战斗的伤害计算用原本的攻击力·守备力进行。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90148', '镜之御巫 迩迩', '这个卡名的②的效果1回合只能使用1次。
①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。
②：这张卡有装备卡装备的场合，对方回合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90149', '多之七音服·丘蒂娅', '←8 【灵摆】 8→
①：自己的「七音服」灵摆怪兽的灵摆召唤不会被无效化。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「多之七音服·丘蒂娅」以外的1只「七音服」灵摆怪兽加入手卡。
②：只要自己的灵摆区域有偶数的灵摆刻度存在，自己场上的「七音服」灵摆怪兽的攻击力上升自身的灵摆刻度×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90150', '女神的圣剑-鹰灵', '①：装备怪兽的攻击力上升500。
②：这张卡从场上送去墓地时，以自己场上1只「守护者·艾托斯」为对象才能发动。那只怪兽的攻击力上升除外中的怪兽数量×500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90151', '死王 巫妖大君', '这张卡上级召唤的场合，解放的怪兽必须是暗属性怪兽。
①：这张卡被效果解放送去墓地的场合发动。墓地的这张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90152', '七音服的交响曲', '这个卡名的卡在1回合只能发动1张。
①：自己的额外卡组的表侧表示的「七音服」灵摆怪兽种类的以下效果适用。
●3种类以上：这个回合，自己场上的「七音服」灵摆怪兽的攻击力上升自身的灵摆刻度×300。
●5种类以上：可以选对方场上1张卡破坏。自己的灵摆区域有奇数的灵摆刻度存在的场合，再让自己从卡组抽1张。
●7种类以上：可以从额外卡组把1只「大钢琴之七音服」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90153', '海神的依代', '这个卡名的①②的效果1回合各能使用1次。
①：以自己墓地1只水属性怪兽为对象才能发动。从以下效果选1个适用。这个回合，自己不是水属性怪兽不能特殊召唤。
●直到结束阶段，这张卡变成和作为对象的怪兽相同等级，当作同名卡使用。
●场上有「海」存在的场合，作为对象的怪兽守备表示特殊召唤。
②：把墓地的这张卡除外，以自己墓地1张「海」为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90154', '古怪恶魔', '←7 【灵摆】 7→
这个卡名的灵摆效果1回合只能使用1次。
①：以这张卡以外的场上1张魔法·陷阱卡为对象才能发动。那张卡和这张卡破坏。
【怪兽效果】
这个卡名的怪兽效果1回合只能使用1次。
①：把这张卡解放，以场上1只怪兽为对象才能发动。那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90155', 'No.21 冰结之正义女郎', '6星怪兽×2
这张卡也能从自己场上的5阶超量怪兽把1个超量素材取除，在那只超量怪兽上面重叠来超量召唤。
①：这张卡的攻击力上升这张卡的超量素材数量×1000。
②：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的守备表示怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90156', '御巫舞踊-迷惑鸟', '这个卡名的②③的效果1回合各能使用1次。
①：装备怪兽不会被效果破坏。
②：自己的「御巫」怪兽进行战斗的伤害步骤结束时，以场上1张卡为对象才能发动。那张卡回到持有者手卡。
③：这张卡在墓地存在的场合，以自己墓地1只「御巫」怪兽为对象才能发动。那只怪兽特殊召唤，这张卡给那只怪兽装备。这个效果特殊召唤的怪兽从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90157', '蔷薇之公主', '这个卡名的①的方法的特殊召唤1回合只能有1次。
①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡当作调整使用。
②：把这张卡从手卡丢弃才能发动。从卡组把1张「白蔷薇回廊」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90158', '芳香法师-迷迭香', '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己的植物族怪兽攻击的场合，直到伤害步骤结束时对方不能把怪兽的效果发动。
②：1回合1次，自己基本分回复的场合，以场上1只表侧表示怪兽为对象发动。那只怪兽的表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90159', '幽鬼兔', '这个卡名的效果1回合只能使用1次。
①：场上的怪兽的效果发动时或者场上的已是表侧表示存在的魔法·陷阱卡的效果发动时，把手卡·场上的这张卡送去墓地才能发动。场上的那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90160', '飞溅闪屏法师', '电子界族怪兽2只
这个卡名的效果1回合只能使用1次。
①：以自己墓地1只电子界族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90161', '教导的圣女 艾克莉西娅', '这个卡名的①②的效果1回合各能使用1次。
①：从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「教导的圣女 艾克莉西娅」以外的1张「教导」卡加入手卡。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。
③：这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90162', '念力终结处刑者', '调整＋调整以外的怪兽1只以上
①：自己基本分是对方基本分以下的场合，同调召唤的这张卡不受对方发动的效果影响。
②：1回合1次，支付1000基本分，以自己场上1只怪兽和对方场上1张卡为对象才能发动。那些卡除外。
③：自己·对方的战斗阶段开始时才能发动。这张卡的攻击力上升双方基本分差的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90163', '儚无水木', '这个卡名的效果1回合只能使用1次。
①：自己·对方回合，把这张卡从手卡丢弃才能发动。这个回合中，以下效果适用。
●每次对方在主要阶段以及战斗阶段把效果怪兽特殊召唤，自己回复那些怪兽的攻击力数值的基本分。这个效果没让自己基本分回复的场合，结束阶段让自己基本分变成一半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90164', '救世之美神 诺斯维姆科', '「救世的仪式」降临。这张卡仪式召唤成功时，选择最多有这张卡的仪式召唤使用的怪兽数量的这张卡以外的场上表侧表示存在的卡发动。只要选择的卡在场上表侧表示存在，这张卡不会被卡的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90165', '极星天 凡娜迪丝', '这张卡可以作为「极星」调整的代替而成为同调素材。把这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是「极星」怪兽。
①：1回合1次，把持有和这张卡的等级不同等级的1只「极星」怪兽从卡组送去墓地才能发动。这张卡的等级直到回合结束时变成和送去墓地的怪兽相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90166', '浮幽樱', '这个卡名的效果1回合只能使用1次。
①：对方场上的怪兽数量比自己场上的怪兽多的场合，把这张卡从手卡丢弃才能发动。选自己的额外卡组1张卡给双方确认。那之后，把对方的额外卡组确认，有选的卡的同名卡的场合，那些对方的同名卡全部除外。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90167', '备份秘书', '这个卡名的①的方法的特殊召唤1回合只能有1次。
①：自己场上有电子界族怪兽存在的场合，这张卡可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90168', '女神薇儿丹蒂的引导', '这个卡名的卡在1回合只能发动1张。
①：作为这张卡的发动时的效果处理，自己场上的怪兽只有「女武神」怪兽的场合，可以从卡组把1张「女神乌尔德的裁断」加入手卡。
②：1回合1次，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，对方把那张卡在自身场上盖放。不是的场合或者不能盖放的场合，对方把那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90169', '电子界贤者', '「电脑网仪式」降临。这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从自己的场上·墓地把融合怪兽卡决定的包含电子界族怪兽的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。
②：这张卡作为同调素材送去墓地的场合，以自己墓地1只电子界族怪兽或者1张仪式魔法卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90170', '精灵兽使 薇茵妲', '自己对「精灵兽使 薇茵妲」1回合只能有1次特殊召唤。
①：这张卡被对方破坏的场合才能发动。从卡组·额外卡组把1只「灵兽」怪兽无视召唤条件特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90171', 'I：P伪装舞会莱娜', '连接怪兽以外的怪兽2只
这个卡名的①的效果1回合只能使用1次。
①：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行连接召唤。
②：这张卡为连接素材的连接怪兽不会被对方的效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90172', '诡计恶魔', '这个卡名的效果1回合只能使用1次。
①：这张卡被效果送去墓地的场合或者被战斗破坏送去墓地的场合才能发动。从卡组把「诡计恶魔」以外的1张「恶魔」卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90173', 'No.23 冥界的灵骑士 兰斯洛特', '8星怪兽×2
①：持有超量素材的这张卡可以直接攻击。
②：这张卡给与对方战斗伤害时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。
③：1回合1次，这张卡以外的怪兽的效果·魔法·陷阱卡发动时，把这张卡1个超量素材取除发动。那个发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90174', '巨神封印之矢', '这个卡名的①②的效果1回合各能使用1次。
①：以从额外卡组特殊召唤的对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，那个效果无效。
②：这张卡在墓地存在的状态，对方从额外卡组把怪兽特殊召唤的场合才能发动。这张卡在自己场上盖放。这个效果在这张卡送去墓地的回合不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90175', '任性的女神', '①：1回合1次，自己主要阶段才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，这张卡的攻击力直到回合结束时变成2倍。猜错的场合，这张卡的攻击力直到回合结束时变成一半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90176', '双生精灵', '相互配合发动攻击的双胞胎妖精姐妹。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90177', '教导的骑士 弗勒德莉丝', '这个卡名的①②的效果1回合各能使用1次。
①：从额外卡组特殊召唤的怪兽在场上存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。自己场上有其他的「教导」怪兽存在的场合，可以再选场上1只表侧表示怪兽那个效果直到回合结束时无效。
②：自己的「教导」怪兽的攻击宣言时才能发动。自己场上的全部「教导」怪兽的攻击力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90178', '梦见之妮穆蕾莉娅', '←8 【灵摆】 8→
①：1回合1次，自己主要阶段才能发动。从自己的卡组·墓地选1张「妮穆蕾莉娅」永续魔法卡在自己场上表侧表示放置，这张卡表侧表示加入额外卡组。这个效果发动的回合，自己不能把「梦见之妮穆蕾莉娅」特殊召唤。
【怪兽效果】
这张卡不能通常召唤。这张卡在额外卡组表侧表示存在，自己的额外卡组只有「梦见之妮穆蕾莉娅」存在的场合才能特殊召唤。自己对「梦见之妮穆蕾莉娅」1回合只能有1次特殊召唤。
①：这张卡特殊召唤成功的场合才能发动。里侧表示除外的自己的卡每有3张，选对方的场上·墓地最多1张卡里侧表示除外。那之后，选这个效果除外的卡数量的里侧表示除外的自己的卡回到卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90179', '薰风的神裔 皮莉佳', '这个卡名的效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功时，以自己墓地1只风属性调整为对象才能发动。那只风属性怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90180', '幽世之血樱', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡在手卡存在的场合，从自己以及对方的墓地各以1张魔法·陷阱卡为对象才能发动。那些卡除外，这张卡特殊召唤。
②：把这张卡解放，以自己或者对方的墓地1只融合·同调·超量·连接怪兽为对象才能发动。那只怪兽除外，从自己墓地选和那只怪兽种类（融合·同调·超量·连接）不同的1只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90181', '魔界特派员 死亡主播', '效果怪兽2只
这个卡名的②的效果1回合只能使用1次。这张卡在连接召唤的回合不能作为连接素材。
①：自己场上的怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1只恶魔族怪兽解放。
②：以「魔界特派员 死亡主播」以外的自己墓地1只恶魔族怪兽为对象才能发动。选自己1张手卡丢弃，作为对象的怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90182', '扫兴书呆魔术师', '魔法师族4星怪兽×2
这张卡也能在自己主要阶段2在自己场上的3阶以下的超量怪兽上面重叠来超量召唤。
①：这张卡的攻击力上升这张卡的超量素材数量×200。
②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。
③：这张卡进行战斗的伤害计算后发动。这张卡1个超量素材取除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90183', '黑魔女 迪亚贝尔斯塔尔', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②③的效果1回合各能使用1次。
①：这张卡可以把自己的手卡·场上1张卡送去墓地，从手卡特殊召唤。
②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「罪宝」魔法·陷阱卡在自己场上盖放。
③：这张卡在对方回合从手卡·场上送去墓地的场合才能发动。从自己的手卡·场上把1张卡送去墓地，这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90184', '薰风的希望 神威', '反转：从自己卡组把1只名字带有「薰风」的调整特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90185', '沉默魔术师 LV8', '这张卡不能通常召唤。「沉默魔术师 LV4」的效果才能特殊召唤。
①：这张卡不受对方的魔法卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90186', '辉煌的逆转之女神', '①：自己场上没有卡存在，自己手卡只有这1张卡的场合，对方怪兽的攻击宣言时把这张卡从手卡丢弃才能发动。对方场上的卡全部破坏。那之后，自己可以从卡组把1只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90187', '虚无之统括者', '这张卡不能特殊召唤。
①：只要这张卡在怪兽区域存在，对方不能把怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90188', '璎珞帝华-帝王贝母', '调整＋调整以外的怪兽1只以上
这个卡名的②的效果1回合只能使用1次。
①：这张卡的攻击力上升这张卡以外的自己场上的植物族怪兽数量×400。
②：自己主要阶段才能发动。从自己的手卡·墓地选「璎珞帝华-帝王贝母」以外的1只5星以上的植物族怪兽守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90189', '清冽之水灵使 艾莉娅', '包含水属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只水属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的水属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90190', '白银之城的执事 阿里亚斯', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，把手卡·场上的这张卡送去墓地才能发动。从手卡把1只「拉比林斯迷宫」怪兽特殊召唤或把1张通常陷阱卡盖放。这个效果盖放的卡在盖放的回合也能发动。
②：对方连锁「白银之城的执事 阿里亚斯」以外的自己的「拉比林斯迷宫」卡或通常陷阱卡的效果的发动把效果发动时才能把这个效果在墓地发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90191', '屋敷童', '这个卡名的效果1回合只能使用1次。
①：包含以下其中任意种效果的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个发动无效。
●从墓地把卡加入手卡·卡组·额外卡组的效果
●从墓地把怪兽特殊召唤的效果
●从墓地把卡除外的效果', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90192', '沉默魔术师 LV4', '①：只要这张卡在怪兽区域存在，每次对方抽卡，给这张卡放置1个魔力指示物（最多5个）。
②：这张卡的攻击力上升这张卡的魔力指示物数量×500。
③：这张卡有第5个魔力指示物被放置的下次的自己回合的准备阶段，把有5个魔力指示物放置的这张卡送去墓地才能发动。从手卡·卡组把1只「沉默魔术师 LV8」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90193', '珠泪哀歌族·雷诺哈特', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「珠泪哀歌族·雷诺哈特」以外的1只「珠泪哀歌族」怪兽送去墓地。
②：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤，从自己手卡选1张「珠泪哀歌族」卡送去墓地。这个效果特殊召唤的这张卡从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90194', '珠泪哀歌族·梅洛人鱼', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从自己卡组上面把3张卡送去墓地。
②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90195', '壹世坏奏响的哀唱', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」存在的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效。那之后，选自己场上1只怪兽送去墓地。
②：这张卡被效果送去墓地的场合才能发动。从卡组把1只「珠泪哀歌族」怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90196', '灵兽的相绊', '①：把自己场上2只表侧表示的「灵兽」怪兽除外才能发动。从额外卡组把1只「灵兽」怪兽无视召唤条件特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90197', '白银之城的召使 阿里亚娜', '这个卡名的①②的效果1回合各能使用1次。
①：从手卡以及自己场上盖放的卡之中把1张通常陷阱卡送去墓地才能发动。从卡组把「白银之城的召使 阿里亚娜」以外的1只4星以下的恶魔族怪兽守备表示特殊召唤。
②：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。自己从卡组抽1张。那之后，以下效果可以适用。
●从手卡把1只恶魔族怪兽特殊召唤或把1张魔法·陷阱卡盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90198', '荒日女之御巫', '「御巫神乐」降临
这个卡名的①的效果1回合只能使用1次。
①：这张卡在手卡·墓地存在，自己墓地有其他的「御巫」卡存在的场合，以场上1只表侧表示怪兽为对象才能发动。这张卡当作装备魔法卡使用给那只怪兽装备。
②：这张卡装备中的场合，自己·对方的结束阶段才能发动。这张卡和装备怪兽回到手卡。
③：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90199', '花园蔷薇花神', '调整＋调整以外的怪兽1只以上
这个卡名的①的效果1回合只能使用1次。
①：以场上1张场地魔法卡为对象才能发动。那张卡破坏。那之后，在那个控制者场上把1只「蔷薇衍生物」（植物族·暗·2星·攻/守800）攻击表示特殊召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。
②：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材作同调召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90200', '火灵媒师 希塔', '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：从手卡把这张卡和1只炎属性怪兽丢弃才能发动。比这张卡以外的丢弃的怪兽攻击力高的1只炎属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把炎属性以外的怪兽的效果发动。
②：自己的炎属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90201', '电子化天使-弁天-', '「机械天使的仪式」降临。
①：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本守备力数值的伤害。
②：这张卡被解放的场合才能发动。从卡组把1只天使族·光属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90202', '御巫神较', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「御巫」怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。从卡组选1张那只怪兽可以装备的装备魔法卡给那只怪兽装备。
②：这张卡在墓地存在的状态，装备魔法卡被送去自己墓地的场合，把这张卡除外，以自己墓地1张装备魔法卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90203', '电子化天使-美朱濡-', '「机械天使的仪式」降临。
①：这张卡仪式召唤成功的场合才能发动。从额外卡组特殊召唤的对方场上的怪兽全部破坏，给与对方破坏的怪兽数量×1000伤害。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。
②：1回合1次，要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时，让自己墓地1只仪式怪兽回到卡组才能发动。那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90204', '于贝尔', '①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。
②：攻击表示的这张卡被选择作为攻击对象的场合，那次伤害计算前发动。给与对方攻击怪兽的攻击力数值的伤害。
③：自己结束阶段发动。自己场上1只其他怪兽解放或这张卡破坏。
④：这个③的效果以外让这张卡被破坏时才能发动。从自己的手卡·卡组·墓地把1只「于贝尔-被憎恶的骑士」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90205', '姬葵 玛丽娜', '只要这张卡在场上表侧表示存在，这张卡以外的自己场上的植物族怪兽1只被战斗或者卡的效果破坏送去墓地的场合，可以选择对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90206', '注射天使 莉莉', '①：这张卡进行战斗的那次伤害计算时1次，支付2000基本分才能发动。这张卡的攻击力只在伤害计算时上升3000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90207', '芳香炽天使-甜马郁兰', '调整＋调整以外的怪兽1只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡同调召唤的场合才能发动。从卡组把「湿润之风」「干渴之风」「恩惠之风」的其中1张加入手卡。
②：只要自己基本分比对方多并有这张卡在怪兽区域存在，对方不能把自己场上的植物族怪兽作为效果的对象。
③：自己基本分回复的场合，以对方场上1张卡为对象发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90208', '御巫的诱轮舞', '可以给对方场上的怪兽装备。这个卡名的卡在1回合只能发动1张。
①：「御巫的诱轮舞」在自己场上只能有1张表侧表示存在。
②：只要自己场上有「御巫」怪兽存在，得到装备怪兽的控制权。
③：装备怪兽只要在自己场上存在，不能把效果发动。
④：这张卡从场上离开时装备怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90209', '樱姬 塔利亚', '①：这张卡的攻击力上升自己场上的植物族怪兽数量×100。
②：只要这张卡在怪兽区域存在，这张卡以外的场上的植物族怪兽不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90210', '魔术女武神', '①：只要这张卡在怪兽区域存在，对方不能把其他的魔法师族怪兽作为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90211', '多之七音服·库莉娅', '←1 【灵摆】 1→
①：在自己的「七音服」灵摆怪兽的灵摆召唤成功时对方不能把怪兽的效果·魔法·陷阱卡发动。
【怪兽效果】
这个卡名的②③的怪兽效果1回合各能使用1次。
①：这张卡可以把自己场上2只灵摆怪兽解放从手卡特殊召唤。
②：以对方场上1张表侧表示的卡为对象才能发动。那张卡的效果直到对方回合结束时无效。自己的灵摆区域有奇数的灵摆刻度存在的场合，这个效果的对象可以变成2张。
③：持有自己的灵摆区域的最高灵摆刻度×300以下的攻击力的场上的怪兽的效果发动时才能发动。那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90212', '“罪宝狩猎之恶魔”', '这个卡名的①②的效果1回合各能使用1次。
①：从自己的卡组·墓地把1只「迪亚贝尔斯塔尔」怪兽加入手卡。
②：自己主要阶段把墓地的这张卡除外，以「“罪宝狩猎之恶魔”」以外的自己的墓地·除外状态的1张「罪宝」魔法·陷阱卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90213', '大日女之御巫', '「御巫神乐」降临。这个卡名的①③的效果1回合各能使用1次。
①：把手卡的这张卡给对方观看才能发动。从卡组把「大日女之御巫」以外的1张「御巫」卡加入手卡。那之后，选自己1张手卡丢弃。
②：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。
③：自己·对方回合，以自己墓地1张装备魔法卡为对象才能发动。那张卡给可以装备的场上1只怪兽装备。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90214', '迷宫城的白银姬', '这个卡名的①③的效果1回合各能使用1次。
①：「迷宫城的白银姬」以外的「拉比林斯迷宫」卡的效果或者通常陷阱卡发动的自己·对方回合才能发动。这张卡从手卡守备表示特殊召唤。
②：只要自己场上有盖放的卡存在，这张卡不会成为对方的效果的对象，不会被对方的效果破坏。
③：通常陷阱卡发动时才能发动。从卡组选和那张卡卡名不同的1张通常陷阱卡在自己场上盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90215', '对薰风的祈祷', '选择自己墓地存在的2只名字带有「薰风」的怪兽，加入卡组洗切。那之后，选择自己墓地存在的1只名字带有「薰风」的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90216', '暗黑女武神', '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。
●只要这张卡表侧表示存在，只有1次可以给这张卡放置1个魔力指示物。这张卡放置的魔力指示物每有1个，这张卡的攻击力上升300。可以把那1个魔力指示物取除，场上1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90217', '珠泪哀歌族·鲁莎卡人鱼', '「珠泪哀歌族·水仙女人鱼」＋「珠泪哀歌族」怪兽
这个卡名的②③的效果1回合各能使用1次。
①：这张卡以外的自己的水族怪兽不会被战斗破坏。
②：包含把怪兽特殊召唤效果的效果由对方发动时才能发动。那个发动无效并破坏。那之后，从手卡以及自己场上的表侧表示的卡之中选1张「珠泪哀歌族」卡送去墓地。
③：融合召唤的这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90218', '守护天灵 洛加埃斯', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上的天使族怪兽的效果发动的场合才能发动。这张卡从手卡特殊召唤。
②：以对方场上1张表侧表示卡和自己场上1只攻击表示怪兽为对象才能发动。那张对方的卡除外，那只自己怪兽变成守备表示。
③：场上的这张卡被战斗·效果破坏的场合，以场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90219', '大钢琴之七音服·库莉娅', '包含灵摆怪兽的怪兽2只以上
①：这张卡的攻击力上升自己的额外卡组的表侧表示的灵摆怪兽数量×100。
②：这张卡所连接区的灵摆怪兽发动的效果不会被无效化。
③：1回合1次，对方把效果发动时才能发动。自己的灵摆区域1张灵摆刻度是奇数的「七音服」卡在作为这张卡所连接区的自己场上特殊召唤，那个发动无效。那之后，可以从卡组把1只灵摆刻度是偶数的「七音服」灵摆怪兽表侧表示加入额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90220', '鲜花女男爵', '调整＋调整以外的怪兽1只以上
这个卡名的②的效果1回合只能使用1次。
①：1回合1次，以场上1张卡为对象才能发动。那张卡破坏。
②：只在这张卡在场上表侧表示存在才有1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。
③：双方的准备阶段，以自己墓地1只9星以下的怪兽为对象才能发动。这张卡回到持有者的额外卡组，作为对象的怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90221', '宇宙智者', '这张卡不能通常召唤。从手卡以及自己场上的表侧表示怪兽之中把效果怪兽以外的1只怪兽送去墓地的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。
①：这张卡的攻击力上升因为这张卡特殊召唤而送去墓地的怪兽的等级×200。
②：把自己场上1只效果怪兽解放才能发动。从手卡·卡组把1只通常怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90222', '魔救之探索者', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「魔救之探索者」以外的岩石族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：自己主要阶段才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只调整以外的4星以下的岩石族怪兽特殊召唤。剩下的卡用喜欢的顺序回到卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90223', '新锐的女战士', '这个卡名的①②的效果1回合各能使用1次。
①：自己的其他的战士族怪兽和对方的表侧表示怪兽进行战斗的攻击宣言时，把手卡·场上的这张卡送去墓地才能发动。那只对方怪兽的攻击力直到回合结束时下降那自身原本攻击力数值。
②：把墓地的这张卡除外，以自己墓地1只战士族·地属性怪兽为对象才能发动。那只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90224', '妖精传姬-辉夜', '①：这张卡召唤成功时才能发动。从卡组把1只攻击力1850的魔法师族怪兽加入手卡。
②：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。对方可以把1张那只怪兽的同名卡从自身的卡组·额外卡组送去墓地让这个效果无效。没送去墓地的场合，这张卡和作为对象的怪兽回到持有者手卡。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90225', '灵兽使 蕾拉', '自己对「灵兽使 蕾拉」1回合只能有1次特殊召唤。
①：这张卡召唤的场合，以自己墓地1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90226', '光神 忒堤斯', '①：自己抽卡时，那卡是天使族怪兽的场合，把那张卡给对方观看才能发动。这张卡在场上表侧表示存在的场合，自己从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90227', '魅惑的女王 LV3', '1回合只有1次在自己的主要阶段时可以选择对方场上的1只3星以下的怪兽，当作装备卡使用装备在这张卡上（这个效果可以装备的装备卡最多1张）。这张卡被战斗破坏的场合，装备的怪兽代替破坏。自己回合的准备阶段时，可以把因这个效果装备有装备卡的这张卡送去墓地，从手卡·卡组特殊召唤1只「魅惑的女王 LV5」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90228', '红姬 知流姬', '只要这张卡在场上表侧表示存在，对方不能选择其他的植物族怪兽作为攻击对象。此外，这张卡被对方送去墓地的场合，可以从卡组把「红姬 知流姬」以外的1只植物族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90229', '神圣生命防护罩', '丢弃1张手卡。这张卡发动的回合，对方造成的伤害全部为0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90230', '新式魔厨的生煎布提斯', '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合才能发动。自己从卡组抽1张。
②：场上的怪兽成为攻击·效果的对象时才能发动。自己场上1只「新式魔厨」怪兽和自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只4·5星的「新式魔厨」仪式怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90231', '原罪宝-蛇眼', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：把这张卡以外的自己场上1张表侧表示卡送去墓地才能发动。从手卡·卡组把1只炎属性·1星怪兽特殊召唤。
②：把墓地的这张卡除外，以自己墓地1只「蛇眼」怪兽或「迪亚贝尔斯塔尔」怪兽为对象才能发动。从卡组把1只炎属性·1星怪兽加入手卡。那之后，作为对象的怪兽回到卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90232', '力天使 女武神', '这个卡名的效果1回合只能使用1次。
①：自己把怪兽的效果·魔法·陷阱卡的发动无效的场合发动。从卡组把1只天使族·光属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90233', '蔷薇恋人', '这个卡名的效果1回合只能使用1次。
①：把墓地的这张卡除外才能发动。从手卡把1只植物族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不受对方的陷阱卡的效果影响。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90234', 'No.87 雪月花美神 月下美人', '8星怪兽×3
①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。这个效果在对方回合也能发动。
●以对方场上盖放的1张魔法·陷阱卡为对象才能发动。只要这张卡在怪兽区域存在，那张卡不能发动。
●以场上1只植物族怪兽为对象才能发动。那只植物族怪兽变成里侧守备表示。
●以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90235', '炎之女暗杀者', '反转：自己的卡组最上面的3张卡在游戏中除外。对方受到800分的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90236', '极星天 古尔薇格', '5星以下的「极星」怪兽1只
这个卡名的①的效果1回合只能使用1次。
①：这张卡连接召唤成功的场合才能发动。选自己的手卡·场上最多3张卡除外，把那个数量的「极星」怪兽从卡组守备表示特殊召唤。这个效果发动过的回合，自己不能通常召唤，不是「极神」怪兽不能特殊召唤。
②：只要这张卡所连接区有「极神」怪兽存在，对方不能把那只怪兽作为效果的对象，不能选择这张卡作为攻击对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90237', '天霆号 阿宙斯', '12星怪兽×2
「天霆号 阿宙斯」在超量怪兽进行过战斗的回合有1次也能在自己场上的超量怪兽上面重叠来超量召唤。
①：自己·对方回合，把这张卡2个超量素材取除才能发动。场上的其他卡全部送去墓地。
②：1回合1次，自己场上的其他卡被战斗或者对方的效果破坏的场合才能发动。从手卡·卡组·额外卡组选1张卡作为这张卡的超量素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90238', '暗蔷薇之妖精', '这个卡名的①②的效果1回合各能使用1次。
①：调整特殊召唤的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡在墓地存在的场合，把自己的手卡·场上1张卡送去墓地才能发动。这张卡回到卡组最上面或者最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90239', '龙魔人 龙骑士女王', '4星怪兽×2
只要这张卡在场上表侧表示存在，「龙魔人 龙骑士女王」以外的自己的龙族怪兽不会被战斗破坏。此外，1回合1次，可以把这张卡1个超量素材取除，选择自己墓地1只5星以上的龙族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合那只怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90240', '薰风的静寂 卡姆', '1回合1次，可以让自己墓地存在的2只名字带有「薰风」的怪兽回到卡组，从自己卡组抽1张卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90241', '梭之七音服·格蕾西娅', '←4 【灵摆】 4→
①：在自己的「七音服」灵摆怪兽的灵摆召唤成功时对方不能把怪兽的效果·魔法·陷阱卡发动。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「七音服」魔法·陷阱卡加入手卡。
②：自己的灵摆区域有偶数的灵摆刻度存在，自己的「七音服」灵摆怪兽攻击的场合，对方直到伤害步骤结束时怪兽的效果不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90242', '电子化天使-伊舍那-', '「机械天使的仪式」降临。
①：这张卡仪式召唤成功的场合才能发动。对方必须把自身场上1张魔法·陷阱卡送去墓地。
②：这张卡的攻击破坏对方怪兽送去墓地时才能发动。这张卡只再1次可以继续向对方怪兽攻击。
③：1回合1次，自己场上的「电子化天使」仪式怪兽为对象的对方的效果发动时才能发动。选自己墓地1只仪式怪兽回到卡组，选对方场上1张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90243', '女神乌尔德的裁断', '①：自己场上的「女武神」怪兽不会成为对方的效果的对象，不会被对方的效果破坏。
②：1回合1次，宣言1个卡名，以对方场上盖放的1张卡为对象才能发动。那张盖放的卡给双方确认，宣言的卡的场合，那张卡除外。不是的场合，选自己场上1张卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90244', 'No.76 谐调光师 渐变天乐斗士', '7星怪兽×2
这个卡名的③的效果1回合只能使用1次。
①：这张卡的属性也当作这张卡作为超量素材中的怪兽的各自属性使用。
②：这张卡不会被和持有和这张卡相同属性的怪兽的战斗破坏，不会被持有和这张卡相同属性的对方怪兽发动的效果破坏。
③：以对方墓地1只怪兽为对象才能发动。这张卡1个超量素材取除，把作为对象的怪兽在这张卡下面重叠作为超量素材。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90245', '七音服的正装', '这个卡名的卡在1回合只能发动1张。
①：自己的灵摆区域有「七音服」卡存在，对方把怪兽的效果·魔法·陷阱卡发动时才能发动。从自己的额外卡组让1只表侧表示的灵摆怪兽回到卡组。那之后，以下效果适用。
●自己场上的灵摆怪兽不受那个对方的效果影响。
●自己的灵摆区域的卡不会被那个对方的效果破坏。
●自己的灵摆区域的卡不能用那个对方的效果除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90246', '时间女神的恶作剧', '这张卡不能连锁发动，不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。
①：自己场上的怪兽只有「女武神」怪兽的场合，自己战斗阶段结束时才能发动。这张卡送去墓地。把回合跳到下次的自己回合的战斗阶段开始时。直到那个回合的结束时自己不能把「时间女神的恶作剧」发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90247', '来之七音服·德莉米娅', '←7 【灵摆】 7→
①：自己的「七音服」灵摆怪兽的灵摆召唤不会被无效化。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：自己的灵摆区域有「七音服」卡存在的场合才能发动。这张卡从手卡特殊召唤。
②：自己的灵摆区域有奇数的灵摆刻度存在，自己场上的「七音服」灵摆怪兽卡被对方的效果破坏的场合，可以作为那1张破坏的卡的代替而把这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90248', '拉比林斯迷宫欢迎欢迎大欢迎', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：从自己的手卡·卡组·墓地选1只「拉比林斯迷宫」怪兽特殊召唤。那之后，选自己场上1只怪兽回到持有者手卡。
②：把墓地的这张卡除外，以自己场上1只恶魔族怪兽为对象才能发动。那张卡回到持有者手卡。自己场上有8星以上的恶魔族怪兽存在的场合，也能作为代替以对方场上1张卡为对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90249', '珠泪哀歌族·水仙女人鱼', '「珠泪哀歌族」怪兽＋水族怪兽
这个卡名的①②③的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合才能发动。从卡组选1张「珠泪哀歌族」卡加入手卡或送去墓地。
②：以自己场上1只怪兽为对象才能发动。从自己的手卡·墓地选1只「珠泪哀歌族」怪兽特殊召唤，作为对象的怪兽送去墓地。
③：这张卡被效果送去墓地的场合才能发动。从自己卡组上面把5张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90250', '宣告者的神巫', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组·额外卡组把1只天使族怪兽送去墓地。这张卡的等级直到回合结束时上升那只怪兽的等级数值。
②：这张卡被解放的场合才能发动。从手卡·卡组把「宣告者的神巫」以外的1只2星以下的天使族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90251', '结晶少女', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。这个回合的结束阶段，从卡组把1只5星以上的水属性怪兽加入手卡。
②：这张卡在墓地存在，自己场上有5星以上的水属性怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90252', '小丑与锁鸟', '①：自己·对方回合，对方在抽卡阶段以外从卡组把卡加入手卡的场合，把这张卡从手卡送去墓地才能发动。这个回合，双方不能从卡组把卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90253', '洗脑解除', '只要这张卡在场上存在，自己与对方场上存在的所有怪兽的控制权回归原本持有者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90254', '神影依·米德拉什', '「影依」怪兽＋暗属性怪兽
这张卡用融合召唤才能从额外卡组特殊召唤。
①：场上的这张卡不会被对方的效果破坏。
②：只要这张卡在怪兽区域存在，那个期间双方1回合只能有1次把怪兽特殊召唤。
③：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90255', '赫之圣女 卡尔特西娅', '这个卡名的①②③的效果1回合各能使用1次。
①：自己的场上或墓地有「阿不思的落胤」存在的场合才能发动。这张卡从手卡特殊召唤。
②：自己·对方的主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只8星以上的融合怪兽融合召唤。
③：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90256', '蔷薇之圣骑士', '「蔷薇之圣骑士」的②的效果1回合只能使用1次。
①：这张卡战斗破坏对方怪兽送去墓地时，把这张卡解放才能发动。从手卡·卡组把1只植物族怪兽守备表示特殊召唤。
②：把这张卡从手卡送去墓地才能发动。从卡组把1只7星以上的植物族怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90257', '凛天使 蔷薇之女王', '这张卡可以把1只植物族怪兽解放表侧攻击表示上级召唤。自己的准备阶段时只有1次，场上表侧表示存在的1只攻击力最低的怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90258', '芳香法师-茉莉', '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把「芳香法师-茉莉」以外的1只植物族怪兽召唤。
②：1回合1次，自己基本分回复的场合发动。自己从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90259', '禁忌的圣衣', '①：以场上1只表侧表示怪兽为对象才能发动。直到回合结束时那只怪兽攻击力下降600，不会成为效果的对象，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90260', '利刃滑冰者', '冰上的舞姬、华丽的战士。以必杀技-阿克塞尔切裂，华丽地攻击敌人的怪兽。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90261', '效果遮蒙者', '①：对方主要阶段，把这张卡从手卡送去墓地，以对方场上1只效果怪兽为对象才能发动。那只对方怪兽的效果直到回合结束时无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90262', '崔嵬之地灵使 奥丝', '包含地属性怪兽的怪兽2只
这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：以对方墓地1只地属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。
②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的地属性怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90263', '混沌猎人', '①：对方对怪兽的特殊召唤成功时，把这张卡以外的1张手卡丢弃才能发动。这张卡从手卡特殊召唤。
②：只要这张卡在怪兽区域存在，对方不能把卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90264', '闭锁世界的冥神', '效果怪兽4只以上
这张卡连接召唤的场合，对方场上1只怪兽也能作为连接素材。
①：这张卡连接召唤的场合才能发动。对方场上的全部表侧表示怪兽的效果无效化。
②：连接召唤的这张卡不受除以这张卡为对象的效果以外的对方发动的效果影响。
③：1回合1次，包含从墓地把怪兽特殊召唤效果的魔法·陷阱·怪兽的效果由对方发动时才能发动。那个发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90265', '魔界的警逻课 死亡警察', '怪兽2只
①：卡名不同的暗属性怪兽2只为素材作连接召唤的这张卡得到以下效果。
●把自己场上1只怪兽解放，以场上1张表侧表示的卡为对象才能发动。给那张卡放置1个警逻指示物。这个卡名的这个效果1回合只能使用1次。有警逻指示物放置的卡被战斗·效果破坏的场合，作为代替把那张卡1个警逻指示物取除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90266', '女武神骑士', '①：只要这张卡在怪兽区域存在，对方不能选择「女武神骑士」以外的战士族怪兽作为攻击对象。
②：这张卡被战斗破坏送去墓地时，从自己墓地把1只战士族怪兽和这张卡除外，以自己墓地1只5星以上的战士族怪兽为对象才能发动。那只战士族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90267', '电子化天使-那沙帝弥-', '「机械天使的仪式」降临。
①：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力一半的数值。
②：自己的仪式怪兽被选择作为攻击对象时才能发动。那次攻击无效。
③：这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只「电子化天使」怪兽除外，以对方场上1只怪兽为对象才能发动。这张卡从墓地特殊召唤，得到作为对象的怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90268', '漫游的素瓷人偶－爱丽丝', '这张卡不会被战斗破坏。 这张卡成为攻击对象时，对方受到500点伤害，伤害步骤结束时这张卡的控制权转移给对方玩家。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90269', '网球小爱神', '这个卡名的②的效果1回合只能有1次。
①：这张卡只要在怪兽区域存在，不受除持有这张卡的等级以下的等级的怪兽以外的全部怪兽发动的效果影响。
②：把自己墓地最多3张卡除外才能发动。直到回合结束时，这张卡的等级上升除外数量的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90270', '排球小爱神', '这个卡名的①②的效果1回合各能使用1次。
①：从自己卡组上面把最多3张卡送去墓地才能发动。这张卡的等级直到回合结束时上升因为这个效果发动而送去墓地的卡数量的数值。
②：场上的这张卡被对方破坏送去墓地的场合发动。自己回复1500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90271', '垒球小爱神', '调整＋调整以外的怪兽1只以上
这个卡名的③的效果1回合只能使用1次。
①：这张卡同调召唤成功的场合发动。这张卡的等级上升或者下降那只作为同调素材的调整的等级数值。
②：这张卡的攻击力上升自身的等级×400。
③：同调召唤的这张卡作为同调素材送去墓地的场合发动。给与对方那只同调召唤的怪兽的等级×100伤害，可以从卡组把1只8星以下而守备力600的怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90272', '高球小爱神', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上的怪兽只有守备力600的怪兽的场合才能发动。这张卡从手卡特殊召唤。
②：丢弃1张手卡，以自己场上1只天使族·光属性怪兽和场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的等级直到回合结束时变成和另1只怪兽的等级相同。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90273', '篮球小爱神', '①：这张卡不会被和除持有比这张卡高的等级的怪兽以外的怪兽的战斗破坏。
②：自己准备阶段才能发动。这张卡的等级上升1星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90274', '重力控制者', '连接怪兽以外的额外怪兽区域的怪兽1只
这张卡在连接召唤的回合不能作为连接素材。
①：额外怪兽区域的这张卡不会被和主要怪兽区域的怪兽的战斗破坏。
②：这张卡和额外怪兽区域的对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽和这张卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90275', '维修区骑士·阿莉', '效果怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡所连接区的怪兽把效果发动时，以对方场上1只效果怪兽为对象才能发动。那只怪兽直到回合结束时攻击力变成0，效果无效化。
②：这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90276', '支索帆水手·航海迷迭香', '这个卡名的①②的效果1回合各能使用1次。
①：以自己场上1只表侧表示怪兽为对象才能发动。选那只怪兽以外的自己场上1只植物族怪兽送去墓地，作为对象的怪兽在这个回合只有1次不会被战斗·效果破坏。这个效果在对方回合也能发动。
②：这张卡被效果送去墓地的场合才能发动。从卡组·额外卡组把1只5星以下的植物族怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90277', '光之法理灵媒', '①：对方战斗阶段开始时，以对方场上的攻击表示怪兽任意数量为对象才能发动。只要这张卡在自己的怪兽区域存在，这个回合，作为对象的怪兽可以攻击的场合，必须向这张卡作出攻击。
②：1回合1次，这张卡和对方的攻击表示怪兽进行战斗的攻击宣言时才能发动。那次攻击无效，给与对方那只对方怪兽的原本攻击力一半数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90278', '斩番', '①：卡的效果10次以上发动的回合才能把这张卡发动。发动后变成效果怪兽（电子界族·暗·10星·攻/守3000）在怪兽区域特殊召唤（也当作陷阱卡使用）。这个效果特殊召唤的这张卡在自己结束阶段在自己的魔法与陷阱区域盖放。
②：1回合1次，这张卡在怪兽区域存在，对方把卡的效果发动时才能发动。对方场上的卡全部破坏。那之后，这张卡在自己的魔法与陷阱区域盖放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90279', '异怪之妖精 艾尔佛彼娅', '1回合1次，把手卡1只风属性怪兽给对方观看才能发动。直到下次的对方的主要阶段1结束时，双方玩家不能把比给人观看的怪兽等级高的怪兽的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90280', '净化施效者', '①：这张卡作为同调素材送去墓地的场合发动。自己从卡组抽1张。
②：这张卡为同调素材的同调怪兽不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90281', '红恋之丽杰-布拉达曼特', '这个卡名在规则上也当作「焰圣骑士」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：把这张卡从手卡丢弃，以自己场上1只战士族怪兽为对象才能发动。从卡组选1张那只怪兽可以装备的装备魔法卡给那只怪兽装备。
②：没有装备卡装备的这张卡被和对方怪兽的战斗破坏送去墓地时才能发动。这张卡特殊召唤，那只对方场上的怪兽当作装备卡使用给这张卡装备。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90282', '神树之圣像骑士', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。
②：自己场上的「圣像骑士」怪兽被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90283', '银冠女王 涅瑞娅', '6星怪兽×3。
这张卡不能作XYZ召唤以外的特殊召唤。有原本种族是植物族怪兽的XYZ素材的状态，由于这张卡的直接攻击把对方基本分变成0的场合，这张卡的控制者得到比赛胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90284', '天空之女神 朱诺', '←1 【灵摆】 1→
①：1回合1次，把自己场上3只表侧表示的天使族灵摆怪兽除外，以自己场上1只灵摆怪兽为对象才能发动。这个回合那只怪兽直接攻击让对方基本分变成0的场合，自己比赛胜利。 
【怪兽描述】
这张卡通常召唤的场合，必须把3只天使族怪兽解放作召唤。这张卡不用灵摆召唤不能特殊召唤。自己场上没有这张卡以外的怪兽存在，这张卡直接攻击让对方基本分变成0的场合，这张卡的控制者比赛胜利。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90285', '鹰身女王', '①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。
②：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「鹰身女妖的狩猎场」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90286', '鹰身女妖的宠物龙', '①：这张卡的攻击力·守备力上升场上的「鹰身女郎」数量×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90287', '黑魔术少女', '①：这张卡的攻击力上升双方墓地的「黑魔术师」「黑混沌之魔术师」数量×300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90288', '恶魔之吻', '①：装备怪兽的攻击力上升700。
②：这张卡从场上送去墓地时，支付500基本分才能发动。这张卡回到卡组最上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90289', '古代妖精龙', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从手卡把1只4星以下的怪兽特殊召唤。这个效果发动的回合，自己不能进行战斗阶段。
②：自己主要阶段才能发动。场地区域的卡全部破坏，自己回复1000基本分。那之后，可以把和破坏的卡卡名不同的1张场地魔法卡从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90290', '冰结界之龙 光枪龙', '调整＋调整以外的怪兽1只以上
这个卡名的效果1回合只能使用1次。
①：把手卡任意数量丢弃去墓地，以丢弃数量的对方场上的卡为对象才能发动。那些卡回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90291', '嵌合要塞龙', '「电子龙」＋机械族怪兽1只以上
把自己·对方场上的上记的卡送去墓地的场合才能从额外卡组特殊召唤。这张卡不能作为融合素材。
①：这张卡的原本攻击力变成作为这张卡的融合素材的怪兽数量×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90292', '蒲公英狮', '①：这张卡被送去墓地的场合发动。在自己场上把2只「绵毛衍生物」（植物族·风·1星·攻/守0）守备表示特殊召唤。这衍生物在特殊召唤的回合不能为上级召唤而解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90293', '绵毛衍生物', '由「蒲公英狮」的效果特殊召唤。这个衍生物特殊召唤的回合不能用于上级召唤的解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90294', '元素英雄 绝对零度侠', '名字带有「英雄」的怪兽＋水属性怪兽
这张卡不能作融合召唤以外的特殊召唤。这张卡的攻击力上升场上表侧表示存在的「元素英雄 绝对零度侠」以外的水属性怪兽数量×500的数值。这张卡从场上离开时，对方场上存在的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90295', '元素英雄 大地侠', '「元素英雄」怪兽＋地属性怪兽
这张卡不用融合召唤不能特殊召唤。
①：这张卡融合召唤成功的场合，以对方场上1只表侧表示怪兽为对象发动。直到回合结束时，那只怪兽的攻击力变成一半，这张卡的攻击力上升那个数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90296', '元素英雄 大龙卷侠', '「元素英雄」怪兽＋风属性怪兽
这张卡不用融合召唤不能特殊召唤。
①：这张卡融合召唤成功的场合发动。对方场上的全部怪兽的攻击力·守备力变成一半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90297', '元素英雄 新宇侠', '从新宇宙来的新元素英雄。凭借与新空间侠接触融合，发挥未知的力量！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90298', '元素英雄 海洋侠', '①：1回合1次，自己准备阶段以自己的场上·墓地1只「英雄」怪兽为对象才能发动。那只自己的「英雄」怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90299', '元素英雄 闪光侠', '名字带有「元素英雄」的怪兽＋光属性怪兽
这张卡不用融合召唤不能特殊召唤。这张卡的攻击力上升从游戏中除外的自己的名字带有「元素英雄」的怪兽数量×300的数值。这张卡从场上送去墓地时，可以选择从游戏中除外的最多2只自己的名字带有「元素英雄」的怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90300', '五神龙', '龙族怪兽×5
这张卡不用融合召唤不能特殊召唤。
①：这张卡不会被和暗·地·水·炎·风属性怪兽的战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90301', '冰结界之龙 天枪龙', '调整＋调整以外的水属性怪兽1只以上
①：1回合1次，把最多2张手卡丢弃去墓地，以丢弃数量的对方场上的卡为对象才能发动。那些卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90302', '冰结界之龙 三叉龙', '调整＋调整以外的怪兽2只以上
①：这张卡同调召唤时才能发动。可以把对方的手卡·场上·墓地的卡各最多1张除外（从手卡是随机选）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90303', '真红眼暗钢龙', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
①：这张卡可以把自己场上1只表侧表示的龙族怪兽除外，从手卡特殊召唤。
②：自己主要阶段才能发动。从自己的手卡·墓地把「真红眼暗钢龙」以外的1只龙族怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90304', '扰乱·绿', '使用一切手段捣乱的扰乱三人组中的一员。据说集齐了三人就会发生什么。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90305', '扰乱·黄', '使用一切手段捣乱的扰乱三人组中的一员。据说集齐了三人就会发生什么。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90306', '扰乱·黑', '使用一切手段捣乱的扰乱三人组中的一员。据说集齐了三人就会发生什么。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90307', '黑蔷薇龙', '调整＋调整以外的怪兽1只以上
①：这张卡同调召唤时才能发动。场上的卡全部破坏。
②：1回合1次，从自己墓地把1只植物族怪兽除外，以对方场上1只守备表示怪兽为对象才能发动。那只对方的守备表示怪兽变成表侧攻击表示，那个攻击力直到回合结束时变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90308', '水月之冰长石巫', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为③的效果1回合只能使用1次。
①：自己的魔法与陷阱区域有表侧表示卡存在的场合，这张卡可以从手卡特殊召唤。
②：这张卡的攻击力·守备力上升场上的表侧表示的魔法·陷阱卡数量×600。
③：把自己的魔法与陷阱区域2张表侧表示卡送去墓地才能发动。从卡组把1只4星以下的怪兽送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90309', '艾乐隆', '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①③的效果1回合只能有1次使用其中任意1个。
①：自己·对方的主要阶段，以自己场上1只「闪刀姬」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作装备魔法卡使用给那只怪兽装备。
②：有这张卡装备的「闪刀姬」怪兽的攻击力上升400。
③：场上的这张卡被破坏的场合才能发动。从卡组把1张「闪刀」魔法卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90310', '天照大神', '这张卡不能召唤·特殊召唤。
①：里侧表示的这只怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡变成表侧守备表示才能发动。自己从卡组抽1张。
②：这张卡反转的场合发动。这张卡以外的场上的卡全部除外。
③：这张卡反转的回合的结束阶段发动。这张卡回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90311', '妖精龙 古代妖', '调整＋调整以外的怪兽1只以上
自己回合有场地魔法卡发动的场合，从卡组抽1张卡。「妖精龙 古代妖」的这个效果1回合只能使用1次。此外，1回合1次，场地魔法卡表侧表示存在的场合，可以选择场上表侧攻击表示存在的1只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90312', '天使之声', '←3 【灵摆】 3→
①：只要另一边的自己的灵摆区域有恶魔族怪兽卡存在，每次自己基本分回复，给这张卡放置1个响鸣指示物。
②：1回合1次，对方怪兽的攻击宣言时才能发动。进行1只「异响鸣」连接怪兽的连接召唤。
【怪兽效果】
这个卡名的①②的怪兽效果1回合各能使用1次。
①：这张卡在手卡存在的场合，从手卡丢弃1张其他卡才能发动。从卡组选1只「恶魔之声」，这张卡和那张卡在自己的灵摆区域放置。
②：这张卡召唤·特殊召唤的回合的自己主要阶段，从自己墓地把1张「异响鸣」通常魔法·通常陷阱卡除外才能发动。那张魔法·陷阱卡发动时的回复基本分的选项的效果适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90313', '水之合唱', '①：场上有同名怪兽存在的场上的怪兽的攻击力·守备力上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90314', '天位准骑士', '卡名不同的战士族怪兽3只
①：1回合1次，以场上的这张卡或者这张卡所连接区的怪兽为对象的怪兽的效果·魔法·陷阱卡发动时，把和那张卡相同种类（怪兽·魔法·陷阱）的1张手卡丢弃才能发动。那个发动无效。
②：连接召唤的这张卡被战斗破坏送去墓地时才能发动。从卡组把1只战士族·4星的通常怪兽特殊召唤，从卡组把1只战士族·4星怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90315', '天位骑士', '「王后骑士」＋「卫兵骑士」＋「国王骑士」
这张卡的融合召唤不用上记的卡不能进行。
①：1回合1次，场上的这张卡为对象的怪兽的效果·魔法·陷阱卡发动时，把和那张卡相同种类（怪兽·魔法·陷阱）的1张手卡丢弃才能发动。那个效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90316', '天位金骑士', '①：这张卡在手卡·墓地存在的场合，从手卡以及自己场上的表侧表示怪兽之中把「王后骑士」「卫兵骑士」「国王骑士」各1只送去墓地才能发动。这张卡特殊召唤。
②：这张卡的攻击力上升双方手卡数量×500。
③：丢弃1张手卡才能发动。和丢弃的卡相同种类（怪兽·魔法·陷阱）的对方场上的表侧表示的卡全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90317', '荒狂之奥丝', '可以把自己场上除这张卡以外的1只地属性怪兽做祭品，从手卡特殊召唤1只地属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「荒狂之奥丝」从自己场上离开的场合破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90318', '黑翼龙', '调整＋调整以外的怪兽1只以上
①：自己受到效果伤害的场合，作为代替给这张卡放置1个黑羽指示物。
②：这张卡的攻击力下降这张卡的黑羽指示物数量×700。
③：1回合1次，把这张卡的黑羽指示物全部取除，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力下降取除的黑羽指示物数量×700，给与对方下降数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90319', '盛燃之希塔', '可以把自己场上除这张卡以外的1只炎属性怪兽做祭品，从手卡特殊召唤1只炎属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「盛燃之希塔」从自己场上离开的场合破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90320', '龙骑士 阿特莉', '这个卡名的①③的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合，若「徽记」卡和「百夫长骑士」卡各在自己墓地存在则能发动。自己抽1张。这个回合，自己不能把「龙骑士 阿特莉」特殊召唤。
②：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。
③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90321', '骑士皇 奥克西拉', '调整＋调整以外的怪兽1只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把1张「百夫长骑士」卡加入手卡。
②：只要这张卡在怪兽区域存在，自己的魔法与陷阱区域的表侧表示卡不会被效果破坏。
③：自己·对方的结束阶段才能发动。同调怪兽以外的自己的墓地·除外状态的1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90322', '骑士的牵绊', '这个卡名的①②的效果1回合各能使用1次。
①：从自己的手卡·墓地把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。
②：这张卡在墓地存在的状态，自己场上有「百夫长骑士」同调怪兽特殊召唤的场合，把这张卡除外，以自己墓地1只「百夫长骑士」怪兽为对象才能发动。那只怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90323', '影骑士 奇美莉娅', '这个卡名的①②的效果1回合各能使用1次。
①：连锁2以后对方把怪兽的效果发动时才能发动。那个效果变成「对方把自身的场上（表侧表示）·墓地1只「百夫长骑士」怪兽当作永续陷阱卡使用在自身的魔法与陷阱区域表侧表示放置」。这个回合，自己不能把「影骑士 奇美莉娅」特殊召唤。
②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。', '效果变化', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90324', '重骑兵 真理6', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡在手卡·墓地存在的场合，对方回合，以「重骑兵 真理6」以外的自己场上1只「百夫长骑士」怪兽为对象才能发动。那只怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置，这张卡特殊召唤。这个回合，自己不能把「重骑兵 真理6」特殊召唤。
②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90325', '骑士皇 雷加蒂娅', '调整＋调整以外的怪兽1只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。自己抽1张。那之后，可以把对方场上1只攻击力最高的怪兽破坏。
②：攻击力2000以下的自己怪兽不会被战斗破坏。
③：自己·对方的结束阶段才能发动。从自己的手卡·墓地把同调怪兽以外的1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。', '', '', '是否把对方攻击力最高的怪兽破坏？', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90326', '骑士皇爆诞', '这个卡名的卡在1回合只能发动1张。
①：怪兽的效果·魔法·陷阱卡发动时，把自己的魔法与陷阱区域1张表侧表示的怪兽卡送去墓地才能发动。那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90327', '赎罪之徽记', '这个卡名的卡在1回合只能发动1张。
①：把自己的魔法与陷阱区域1张表侧表示的「百夫长骑士」怪兽卡除外，以对方场上1张卡为对象才能发动。那张卡除外。
②：盖放的这张卡被对方的所发动的效果所破坏的场合或者所除外的场合才能发动。自己的手卡·卡组·墓地·除外状态的2只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置（同名卡最多1张）。', '表侧表示放置', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90328', '誓言之徽记', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。
●从卡组把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。这个回合，这个效果放置的卡或者原本卡名和那张卡相同的卡在自己场上表侧表示存在期间，自己不是「百夫长骑士」怪兽不能从额外卡组特殊召唤。
●从卡组把1张「百夫长骑士」魔法·陷阱卡在自己场上盖放。', '把怪兽表侧表示放置', '把魔法·陷阱卡盖放', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90329', '奇迹之魔导剑士', '包含灵摆怪兽的效果怪兽2只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡连接召唤的场合才能发动。从自己的额外卡组把1只表侧的灵摆怪兽加入手卡。
②：这张卡的攻击力上升自己场上的灵摆怪兽卡数量×100。
③：自己·对方的主要阶段才能发动。把持有用自己的灵摆区域2张卡的灵摆刻度可以灵摆召唤的等级的1只灵摆怪兽从自己的手卡·墓地守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90330', '伊奘波', '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，可以丢弃1张手卡把自己墓地存在的1只灵魂怪兽加入手卡。', '回到手牌', '把自己墓地存在的1只灵魂怪兽加入手卡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90331', '机巧小町 二二四', '这张卡可以攻击的场合必须作出攻击。场上表侧表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变更。只要这张卡在场上表侧表示存在，自己的主要阶段时只有1次，自己在通常召唤外加上可以把1只名字带有「机巧」的怪兽召唤。', '表示形式变更', '使用「机巧小町 二二四」的效果召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90332', '直播☆双子 姬丝基勒·霜精', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
①：自己场上有「璃拉」怪兽存在的场合，这张卡可以从手卡特殊召唤。
②：对方用卡的效果从卡组把卡加入手卡的场合，若自己场上有「邪恶★双子」怪兽存在，把墓地的这张卡除外才能发动。自己抽1张。', '', '除外并抽卡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90333', '直播☆双子 姬丝基勒', '这个卡名的①的效果1回合只能使用1次。
①：这张卡召唤·特殊召唤的场合，若自己场上没有其他怪兽存在则能发动。从手卡·卡组把1只「璃拉」怪兽特殊召唤。
②：只要这张卡在怪兽区域存在，每次对方怪兽攻击宣言，自己回复500基本分。', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90334', '直播☆双子 璃拉·糖果', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
①：自己场上有「姬丝基勒」怪兽存在的场合，这张卡可以从手卡特殊召唤。
②：「邪恶★双子」怪兽的战斗让自己或对方受到战斗伤害时，把墓地的这张卡除外，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降那次战斗伤害的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90335', '直播☆双子 璃拉', '这个卡名的①的效果1回合只能使用1次。
①：这张卡召唤·特殊召唤的场合，若自己场上没有其他怪兽存在则能发动。从手卡·卡组把1只「姬丝基勒」怪兽特殊召唤。
②：只要这张卡在怪兽区域存在，对方若不支付500基本分则不能攻击宣言。', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90336', '月光少女', '月亮加护的魔导士。神秘的魔法能使人看到幻觉。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90337', '威风妖怪·龙', '←5 【灵摆】 5→
这个卡名的灵摆效果1回合只能使用1次。
①：另一边的自己的灵摆区域有「威风妖怪」卡或「龙剑士」卡存在的场合才能发动。从卡组把1张「威风妖怪」卡加入手卡。那之后，可以把自己的灵摆区域1张卡破坏。
【怪兽效果】
4星怪兽×2
4星可以灵摆召唤的场合在额外卡组的表侧的这张卡可以灵摆召唤。这个卡名的①的怪兽效果1回合可以使用最多2次。
①：这张卡在怪兽区域存在的状态，怪兽被解放的场合，把这张卡1个超量素材取除才能发动。从卡组把1只6星以下的魔法师族·风属性怪兽特殊召唤。
②：怪兽区域的这张卡被战斗·效果破坏的场合或者被解放的场合才能发动。这张卡在自己的灵摆区域放置。', '卡组检索', '从卡组特殊召唤', '在灵摆区域放置', '是否把自己的灵摆区域1张卡破坏？', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90338', '双穹之骑士 阿斯特拉姆', '从额外卡组特殊召唤的怪兽2只以上
①：只要连接召唤的这张卡在怪兽区域存在，这张卡不会成为对方的效果的对象，对方不能选择其他怪兽作为攻击对象。
②：这张卡和特殊召唤的怪兽进行战斗的伤害计算时才能发动1次。这张卡的攻击力只在那次伤害计算时上升那只对方怪兽的攻击力数值。
③：连接召唤的这张卡被对方送去墓地的场合才能发动。选场上1张卡回到持有者卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90339', '起立吧百夫长骑士！', '这个卡名的②③的效果1回合各能使用1次。
①：只要自己场上有「百夫长骑士」怪兽卡存在，这张卡不会被对方的效果破坏。
②：这张卡发动的回合的自己主要阶段，把1张手卡送去墓地才能发动。从卡组把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。
③：怪兽特殊召唤的场合才能发动。用包含「百夫长骑士」怪兽的自己场上的怪兽为素材进行同调召唤。', '', '同调召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90340', '风灵使 薇茵', '①：这张卡反转的场合，以对方场上1只风属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '获得对方场上1只风属性怪兽的控制权', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90341', '闪刀姬-露世', '这个卡名的①②的效果1回合各能使用1次。
①：「闪刀姬-露世」以外的「闪刀姬」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡在墓地存在的状态，额外怪兽区域的对方怪兽被战斗破坏的场合或者因自己的卡的效果从场上离开的场合才能发动。这张卡特殊召唤。那之后，可以把对方场上1只表侧表示怪兽的效果直到回合结束时无效。', '这张卡从手卡特殊召唤', '这张卡从墓地特殊召唤', '是否选对方怪兽效果无效？', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90342', '闪刀姬-零衣', '这个卡名的①②的效果1回合各能使用1次。
①：把这张卡解放才能发动。从额外卡组把1只「闪刀姬」怪兽在额外怪兽区域特殊召唤。这个效果在对方回合也能发动。
②：这张卡在墓地存在的状态，自己场上的表侧表示的「闪刀姬」连接怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90343', '闪刀姬-燎里', '炎属性以外的「闪刀姬」怪兽1只
自己对「闪刀姬-燎里」1回合只能有1次特殊召唤。
①：这张卡特殊召唤成功的场合，以自己墓地1张「闪刀」魔法卡为对象才能发动。那张卡加入手卡。
②：这张卡的攻击力上升自己墓地的魔法卡数量×100。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90344', '灵魂鸟影-姬孔雀', '「灵魂的降神」降临
这个卡名的②的效果1回合只能使用1次。
①：这张卡的卡名只要在手卡·场上存在当作「灵魂鸟神-姬孔雀」使用。
②：这张卡仪式召唤的场合才能发动。效果文本有「灵魂怪兽」记述的1张魔法·陷阱卡从卡组加入手卡。
③：这张卡被除外的下个回合的准备阶段发动。除外状态的这张卡特殊召唤。
④：这张卡特殊召唤的回合的结束阶段发动。这张卡回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90345', '凭依装着-奥丝', '①：这张卡可以把自己场上的表侧表示的1只「地灵使 奥丝」和1只地属性怪兽送去墓地，从手卡·卡组特殊召唤。
②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90346', '凭依装着-希塔', '①：这张卡可以把自己场上的表侧表示的1只「火灵使 希塔」和1只炎属性怪兽送去墓地，从手卡·卡组特殊召唤。
②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90347', '凭依装着-薇茵', '①：这张卡可以把自己场上的表侧表示的1只「风灵使 薇茵」和1只风属性怪兽送去墓地，从手卡·卡组特殊召唤。
②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90348', '花札卫-月花见-', '调整＋调整以外的怪兽2只
①：1回合1次，自己主要阶段才能发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在这个回合可以直接攻击。这个效果发动的场合，下次的自己回合的抽卡阶段跳过。
②：把场上的这张卡作为同调素材的场合，可以把包含这张卡的全部同调素材怪兽当作2星怪兽使用。', '抽卡', '是否特殊召唤？', '是否把全部同调素材怪兽当作2星怪兽使用？', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90349', '黑蝎-荆棘的美奈', '①：这张卡给与对方战斗伤害时，可以从以下效果选择1个发动。
●从卡组把1张「黑蝎」卡加入手卡。
●以自己墓地1张「黑蝎」卡为对象才能发动。那张卡加入手卡。', '选择一个效果发动', '卡组检索', '墓地回收', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90350', '水灵使 艾莉娅', '①：这张卡反转的场合，以对方场上1只水属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '获得对方场上1只水属性怪兽的控制权', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90351', '邪恶★双子 姬丝基勒', '包含「姬丝基勒」怪兽的怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合，若自己场上有「璃拉」怪兽存在则能发动。自己抽1张。
②：自己·对方的主要阶段，自己场上没有「璃拉」怪兽存在的场合才能发动。从自己墓地把1只「璃拉」怪兽特殊召唤。这个回合，自己不是恶魔族怪兽不能从额外卡组特殊召唤。', '抽卡', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90352', '邪恶★双子 璃拉', '包含「璃拉」怪兽的怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合，若自己场上有「姬丝基勒」怪兽存在，以场上1张卡为对象才能发动。那张卡破坏。
②：自己·对方的主要阶段，自己场上没有「姬丝基勒」怪兽存在的场合才能发动。从自己墓地把1只「姬丝基勒」怪兽特殊召唤。这个回合，自己不是恶魔族怪兽不能从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90353', '凭依装着-艾莉娅', '①：这张卡可以把自己场上的表侧表示的1只「水灵使 艾莉娅」和1只水属性怪兽送去墓地，从手卡·卡组特殊召唤。
②：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90354', '我我我妹妹', '这个卡名的②的效果1回合只能使用1次。
①：这张卡召唤成功时才能发动。从卡组把1张「我我我」魔法·陷阱卡加入手卡。
②：以这张卡以外的自己场上1只「我我我」怪兽为对象才能发动。那只怪兽和这张卡直到回合结束时变成那2只的等级合计的等级。', '检索', '等级变化', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90355', '天使的施舍', '从卡组抽3张卡，之后从手卡选2张丢弃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90356', '火灵使 希塔', '①：这张卡反转的场合，以对方场上1只炎属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '获得对方场上1只炎属性怪兽的控制权', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90357', '光灵使 莱娜', '①：这张卡反转的场合，以对方场上1只光属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '获得对方场上1只光属性怪兽的控制权', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90358', '龙宫之姬', '这张卡不能特殊召唤。召唤·反转回合的结束阶段时回到主人的手卡。这张卡召唤·反转时，可以选择对方场上的1只表侧表示的怪兽改变表示形式。', '返回手牌', '改变表示形式', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90359', '星尘龙', '调整＋调整以外的怪兽1只以上
①：要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。
②：这张卡的①的效果适用的回合的结束阶段才能发动。为那个效果发动而解放的这张卡从墓地特殊召唤。', '破坏场上卡的效果发动无效并破坏', '回合结束时特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90360', '淘气仙星乐队·吉她斯薇特', '「淘气仙星」连接怪兽＋「淘气仙星」怪兽
①：和这张卡连接状态的自己的「淘气仙星」连接怪兽的效果给与对方的伤害变成2倍。
②：每次「淘气仙星」怪兽的效果让对方受到伤害发动。这张卡的攻击力上升那次伤害的数值。
③：这张卡攻击的回合的结束阶段发动。这张卡的②的效果上升的数值回到0。那之后，可以从自己墓地选1只「淘气仙星」怪兽加入手卡。', '上升攻击力', '攻击力恢复', '是否从自己墓地选1只「淘气仙星」怪兽加入手卡？', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90361', '淘气仙星·霍莉安琪儿', '「淘气仙星」怪兽2只
①：只要这张卡在怪兽区域存在，每次这张卡所连接区有「淘气仙星」怪兽召唤·特殊召唤，给与对方200伤害。
②：这张卡所连接区的「淘气仙星」怪兽不会被战斗·效果破坏。
③：每次「淘气仙星」怪兽的效果让对方受到伤害发动。这张卡的攻击力直到回合结束时上升那次伤害的数值。', '上升攻击力', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90362', '淘气仙星·曼珠诗华', '①：自己·对方回合，把手卡的这张卡给对方观看，以「淘气仙星·曼珠诗华」以外的自己场上1只「淘气仙星」怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽回到手卡。
②：只要这张卡在怪兽区域存在，每次对方手卡有卡加入，给与对方加入的卡数量×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90363', '淘气仙星衍生物', '由「淘气仙星音乐节」或「淘气仙星的现场演唱舞台」的效果特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90364', '月读命', '这张卡不能特殊召唤。
①：这张卡召唤·反转的场合，以场上1只表侧表示怪兽为对象发动。那只怪兽变成里侧守备表示。
②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。', '回到手牌', '改变表示形式', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90365', '创神之异响鸣', '这个卡名的②③的效果1回合各能使用1次。
①：只要自己场上有响鸣指示物6个以上存在，自己场上的「异响鸣」连接怪兽的攻击力上升1200。
②：对方把怪兽特殊召唤的场合才能发动。进行1只「异响鸣」连接怪兽的连接召唤。
③：这张卡从手卡·场上送去墓地的场合才能发动。给可以放置响鸣指示物的自己的灵摆区域1张卡放置响鸣指示物到变成3个。', '连接召唤', '放置指示物', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90366', '淘气仙星·科尔奇卡', '连接怪兽以外的「淘气仙星」怪兽1只
自己对「淘气仙星·科尔奇卡」1回合只能有1次特殊召唤，那个效果1回合只能使用1次。
①：这张卡在墓地存在的状态，自己的「淘气仙星」怪兽的战斗让怪兽被破坏时，把这张卡除外，以那1只破坏的怪兽为对象才能发动。给与对方那只怪兽的攻击力数值的伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90367', '异响鸣之神奏-星光天魔', '包含「异响鸣」连接怪兽的怪兽2只
①：只要自己场上有响鸣指示物6个以上存在，场上的这张卡不受「异响鸣」卡以外的卡的效果影响。
②：这张卡在同1次的战斗阶段中在通常攻击外加上可以作出最多有自己场上的4星「异响鸣」怪兽数量的攻击。
③：1回合1次，对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。那之后，自己场上3个响鸣指示物取除。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90368', '淘气仙星·胡蒂', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「淘气仙星」融合·连接怪兽的其中任意种存在的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合才能发动。从卡组把1张「淘气仙星融合」或「淘气仙星扩散融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90369', '异响鸣之神异-风暴恶魔', '效果怪兽1只
这张卡的连接召唤若非自己的灵摆区域的恶魔族怪兽卡的响鸣指示物是3个以上的场合则不能进行，自己对「异响鸣之神异-风暴恶魔」1回合只能有1次特殊召唤。
①：自己场上的卡被战斗·效果破坏的场合，可以作为代替把自己的灵摆区域3个响鸣指示物取除。
②：对方回合1次，以自己的墓地·除外状态的1张「异响鸣」通常魔法·通常陷阱卡为对象才能发动。那张魔法·陷阱卡发动时的效果适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90370', '我我我少女', '①：以自己场上1只「我我我魔术师」为对象才能发动。这张卡的等级变成和那只怪兽相同。
②：只用包含这张卡的「我我我」怪兽为素材作超量召唤的怪兽得到以下效果。
●这次超量召唤成功时，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽的攻击力变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90371', '淘气仙星·戴薇尔菲妮姆', '「淘气仙星」怪兽2只以上
①：这张卡所连接区有「淘气仙星」怪兽存在的场合，这张卡的攻击宣言时以最多有对方场上的连接怪兽数量的除外的自己的「淘气仙星」卡为对象才能发动。那些卡加入手卡。这张卡的攻击力直到回合结束时上升这个效果加入手卡的卡数量×1000。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90372', '心变', '①：以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90373', '律导之异响鸣', '这个卡名的卡在1回合只能发动1张。
①：自己场上有「异响鸣」怪兽卡存在的场合，从以下效果选1个适用。自己场上有「异响鸣」连接怪兽存在的场合，可以选两方适用。
●自己回复500基本分。那之后，可以把场上1张魔法·陷阱卡破坏。
●自己受到500伤害。那之后，可以让场上1只怪兽回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90374', '异响鸣的选择', '这个卡名的卡在1回合只能发动1张。
①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。
●自己回复500基本分。那之后，可以选自己1张手卡回到卡组最下面。那个场合，自己抽2张。
●自己受到500伤害。那之后，可以从卡组把「异响鸣的选择」以外的1张「异响鸣」魔法·陷阱卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90375', '恐啡肽狂龙无伤', '这个卡名的卡在1回合只能发动1张。
①：自己场上有「恐啡肽狂龙」卡存在，怪兽的效果发动时，把基本分支付一半才能发动。那个发动无效并破坏。这个回合，自己受到的战斗伤害变成那个时候的自己基本分一半的数值。
②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90376', '娱乐伙伴 小独', '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段才能发动1次。从手卡把1只3星以下的「娱乐伙伴」怪兽攻击表示特殊召唤。
②：对方回合，从自己墓地把这张卡和1只「娱乐伙伴 小独」以外的「娱乐伙伴」怪兽除外才能发动。这个回合自己受到的战斗伤害只有1次变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90377', '闪刀姬-飒天', '风属性以外的「闪刀姬」怪兽1只
自己对「闪刀姬-飒天」1回合只能有1次特殊召唤。
①：这张卡可以直接攻击。
②：这张卡进行战斗的伤害计算后才能发动。从卡组把1张「闪刀」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90378', '骑士皇 普莉梅拉·首席百夫长', '调整＋调整以外的怪兽1只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡同调召唤的场合才能发动。从自己的卡组·墓地把1张「徽记」卡加入手卡。那之后，可以把自己以及对方场上的卡各1张破坏。
②：从额外卡组以外特殊召唤的这张卡不会被战斗破坏。
③：自己场上的表侧表示的「百夫长骑士」卡因对方的效果从场上离开的场合才能发动。这张卡从墓地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90379', '魔女术代理师傅', '「魔女术」怪兽＋魔法师族怪兽
①：融合怪兽以外的魔法师族怪兽或者魔法卡的效果发动时，可以从以下效果选择1个发动。「魔女术代理师傅」的以下效果1回合各能选择1次。
●选场上1张卡破坏。
●从手卡·卡组把1只6星以下的「魔女术」怪兽特殊召唤。
●从自己墓地选1张「魔女术」魔法·陷阱卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90380', '闪刀起动-连刀', '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。选这张卡以外的自己场上1张卡送去墓地，从额外卡组把1只「闪刀姬」怪兽在额外怪兽区域特殊召唤。自己的场上·墓地有光属性和暗属性的「闪刀姬」怪兽各1只以上存在的场合，这个效果特殊召唤的怪兽的攻击力上升1000。这张卡的发动后，直到回合结束时自己不是「闪刀姬」怪兽不能从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90381', '眼盯盯☆魔术辣妹', '魔法师族6星怪兽×2
1回合1次，可以把这张卡1个超量素材取除，把1张手卡从游戏中除外从以下效果选择1个发动。
●选择对方场上1只怪兽直到这个回合的结束阶段时得到控制权。
●选择对方墓地1只怪兽在自己场上特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90382', '圣座天嗣 坐天使', '这个卡名的效果1回合只能使用1次。
①：原本的种族·属性是天使族·地属性的怪兽从自己的手卡·场上送去墓地的场合才能发动。这张卡从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90383', '闪刀姬-魁奈', '地属性以外的「闪刀姬」怪兽1只
自己对「闪刀姬-魁奈」1回合只能有1次特殊召唤。
①：这张卡特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽直到对方回合结束时不能攻击。
②：只要这张卡在怪兽区域存在，每次自己把「闪刀」魔法卡的效果发动，自己回复100基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90384', '淘气仙星·蒂瓦丽迪丝', '3星以下的「淘气仙星」怪兽2只
①：「淘气仙星·蒂瓦丽迪丝」在自己场上只能有1只表侧表示存在。
②：这张卡特殊召唤成功的场合才能发动。给与对方200伤害。
③：每次对方对怪兽的召唤·特殊召唤成功发动。给与对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90385', '重骑士 普莉梅拉', '这个卡名的①③的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「重骑士 普莉梅拉」以外的1张「百夫长骑士」卡加入手卡。这个回合，自己不能把「重骑士 普莉梅拉」特殊召唤。
②：这张卡是当作永续陷阱卡使用的场合，自己场上的5星以上的「百夫长骑士」怪兽不会被效果破坏。
③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90386', '水灵媒师 艾莉娅', '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：从手卡把这张卡和1只水属性怪兽丢弃才能发动。把持有这张卡以外的丢弃的怪兽的等级以上的等级的1只水属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把水属性以外的怪兽的效果发动。
②：自己的水属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90387', '合体术式-交闪零式', '光·暗属性怪兽2只
这个卡名在规则上也当作「闪刀姬」卡使用。自己对「合体术式-交闪零式」1回合只能有1次特殊召唤，这张卡不能作为连接素材。
①：这张卡特殊召唤的场合，以场上1只攻击力2500以上的怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。
②：自己墓地有「闪刀姬-零衣」以及「闪刀姬-露世」存在的场合，这张卡攻击的伤害步骤开始时才能发动。对方场上的怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90388', '暗灵使 达克', '①：这张卡反转的场合，以对方场上1只暗属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90389', '聚集的祈愿', '①：自己墓地有龙族同调怪兽5种类以上存在的场合才能发动。从额外卡组把1只「星尘龙」当作同调召唤作特殊召唤，把这张卡装备。这个效果特殊召唤的怪兽在结束阶段除外。
②：装备怪兽的攻击力上升自己墓地的龙族同调怪兽的攻击力的合计数值。
③：每次装备怪兽战斗破坏对方怪兽，把自己墓地1只龙族同调怪兽除外才能发动。装备怪兽向对方怪兽可以继续攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90390', '未来之柱-奇亚诺丝', '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。
①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。
②：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1只「闪刀姬-露世」特殊召唤。这个回合，自己不是机械族怪兽不能从额外卡组特殊召唤。
③：把墓地的这张卡除外才能发动。选自己的墓地·除外状态的1只「闪刀姬-露世」加入手卡或特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90391', '黄金之雫的神碑', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。
●对方从卡组抽1张。那之后，从对方卡组上面把4张卡除外。
●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90392', '淘气仙星的康乃馨转生术', '①：对方手卡全部除外，对方抽出那个数量。
②：把墓地的这张卡除外，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90393', '宇宙耀变龙', '同调怪兽调整＋调整以外的同调怪兽2只以上
这张卡不用同调召唤不能特殊召唤。
①：可以把场上的这张卡直到结束阶段除外，从以下效果选择1个发动。
●对方把魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。
●对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。
●对方怪兽的攻击宣言时才能发动。那次攻击无效，那之后战斗阶段结束。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90394', '带来光明的使者 路西法', '吾乃君临至高玉座统治天地者…要有光！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90395', '末那愚子族·三界歌水仙女', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：这张卡同调召唤的场合，以自己墓地1只2星调整为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。
②：以自己场上的调整任意数量为对象才能发动。那些怪兽的等级变成2星。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90396', '魔女术师傅·玻璃女巫', '这个卡名的①②的效果1回合各能使用1次。
①：自己的魔法师族怪兽和对方怪兽进行战斗的伤害计算时才能发动。卡名不同的手卡的魔法卡任意数量给对方观看，那只自己怪兽的攻击力·守备力直到回合结束时上升给人观看的数量×1000。
②：自己·对方回合，从手卡丢弃1张魔法卡才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90397', '魔女术工匠·锻造女巫', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·锻造女巫」以外的1只「魔女术」怪兽特殊召唤。
②：把墓地的这张卡除外才能发动。从卡组把「魔女术工匠·锻造女巫」以外的1张「魔女术」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90398', '淘气仙星·曼德拉', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡从手卡送去墓地的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。
②：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合，以对方的连接怪兽的所连接区1只怪兽为对象才能发动。那只怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90399', '天魔之声选姬', '这个卡名的①③的效果1回合各能使用1次。
①：这张卡召唤·灵摆召唤的场合才能发动。从卡组把「天魔之声选姬」以外的1张「异响鸣」卡加入手卡。
②：只要自己场上有「天魔之声选姬」以外的怪兽存在，对方怪兽不能选择这张卡作为攻击对象。
③：这张卡被送去墓地的场合，若自己的灵摆区域有2张「异响鸣」卡存在则能发动。这张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90400', '闪刀机关-多任务战刀机', '①：1回合1次，以这张卡以外的自己场上1张卡为对象才能发动。这个回合，对方不能对应自己的魔法卡的发动把魔法·陷阱·怪兽的效果发动。并且，再把作为对象的卡送去墓地。
②：自己·对方的结束阶段才能发动。选最多有这个回合这张卡表侧表示存在期间自己发动的「闪刀」魔法卡数量的自己墓地的「闪刀」魔法卡在自己场上盖放（同名卡最多1张）。这个效果盖放的卡从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90401', '灵魂鸟神-姬孔雀', '「灵魂的降神」降临。这张卡不用仪式召唤不能特殊召唤。
①：这张卡仪式召唤成功的场合才能发动。选对方场上最多3张魔法·陷阱卡回到持有者卡组。那之后，可以从卡组把1只4星以下的灵魂怪兽无视召唤条件特殊召唤。
②：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡，在自己场上把2只「灵魂鸟衍生物」（鸟兽族·风·4星·攻/守1500）特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90402', '恐啡肽狂龙甲壳', '这个卡名的卡在1回合只能发动1张。
①：对方战斗阶段开始时，把基本分支付一半才能发动。在自己场上把1只「恐啡肽狂龙衍生物」（恐龙族·暗·10星·攻0/守3000）特殊召唤。这个回合，只要这个效果特殊召唤的衍生物在自己场上存在，对方不能选择其他怪兽作为攻击对象。
②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90403', '王后骑士', '用优美的动作愚弄敌人，抓住对方的空隙快速发出攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90404', '肃声的祈祷者 理', '这个卡名的①③的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「肃声」永续魔法·永续陷阱卡在自己的魔法与陷阱区域表侧表示放置。
②：战士族·龙族而光属性的仪式怪兽1只仪式召唤的场合，可以由这1张卡作为仪式召唤需要的数值的解放使用。
③：这张卡在墓地存在的状态，自己场上有战士族·龙族而光属性的仪式怪兽特殊召唤的场合才能发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90405', '圣珖神龙 星尘·零', '同调怪兽调整＋调整以外的同调怪兽2只以上
这张卡不用同调召唤不能特殊召唤。
①：自己场上的卡在1回合各有1次不会被战斗·效果破坏。
②：1回合1次，对方把怪兽的效果发动时才能发动。那个效果无效，选场上1张卡破坏。
③：把墓地的这张卡除外，以自己墓地1只8星以下的「星尘」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90406', '恐啡肽狂龙逆转', '这个卡名的卡在1回合只能发动1张。
①：自己场上有「恐啡肽狂龙」融合怪兽存在的场合，把基本分支付一半，从自己墓地把1张反击陷阱卡除外才能发动。这个效果变成和那张反击陷阱卡发动时的效果相同。
②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90407', '暗黑安琪儿', '①：自己的天使族怪兽被选择作为攻击对象时，把那只怪兽解放，把这张卡从手卡送去墓地，以自己场上1只表侧表示怪兽为对象才能发动。攻击对象转移为那只自己怪兽，作为对象的怪兽的攻击力直到回合结束时上升解放的天使族怪兽的原本攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90408', '我我我术士', '①：1回合1次，以「我我我术士」以外的自己墓地1只「我我我」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「我我我」怪兽不能特殊召唤。
②：超量素材的这张卡为让超量怪兽的效果发动而被取除送去墓地的场合，以自己场上1只超量怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90409', '猛吹之薇茵', '可以把自己场上除这张卡以外的1只风属性怪兽做祭品，从手卡特殊召唤1只风属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「猛吹之薇茵」从自己场上离开的场合破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90410', '恶魔之声', '←5 【灵摆】 5→
①：只要另一边的自己的灵摆区域有天使族怪兽卡存在，每次自己受到效果伤害，给这张卡放置1个响鸣指示物。
②：对方场上的怪兽的攻击力下降自己场上的响鸣指示物数量×100。
【怪兽效果】
这个卡名的①②的怪兽效果1回合各能使用1次。
①：这张卡在手卡存在的场合，从手卡丢弃1张其他卡才能发动。从卡组选1只「天使之声」，这张卡和那张卡在自己的灵摆区域放置。
②：这张卡召唤·特殊召唤的回合的自己主要阶段，从自己墓地把1张「异响鸣」通常魔法·通常陷阱卡除外才能发动。那张魔法·陷阱卡发动时的受到伤害的选项的效果适用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90411', '选律之异响鸣', '这个卡名的卡在1回合只能发动1张。
①：自己场上有「异响鸣」怪兽卡存在的场合，从以下效果选1个适用。自己场上有「异响鸣」连接怪兽存在的场合，可以选两方适用。
●自己回复500基本分。这个回合中，对方不能把自己场上的「异响鸣」怪兽卡作为效果的对象。
●自己受到500伤害。那之后，可以把对方场上1只效果怪兽的效果直到回合结束时无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90412', '娱乐伙伴 小角', '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段只有1次，以这张卡以外的自己场上1只攻击力1000以下的「娱乐伙伴」怪兽为对象才能发动。自己场上的同是表侧攻击表示的那只怪兽和这张卡变成守备表示，从卡组把1只「异色眼」怪兽加入手卡。
②：对方回合，从自己墓地把这张卡和1只「娱乐伙伴 小角」以外的「娱乐伙伴」怪兽除外才能发动。自己回复500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90413', '慈爱之贤者-西埃拉', '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。
①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。
②：从自己墓地把1张魔法卡除外才能发动。这张卡的控制权移给对方，从自己墓地选1只「闪刀姬」怪兽特殊召唤。
③：这张卡被战斗·效果破坏送去墓地的场合，以除外的1张自己的「闪刀」魔法卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90414', '神之恩惠', '①：只要这张卡在魔法与陷阱区域存在，每次自己抽卡，自己回复500基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90415', '淘气仙星的灯光舞台', '①：作为这张卡的发动时的效果处理，可以从卡组把1只「淘气仙星」怪兽加入手卡。
②：1回合1次，以对方的魔法与陷阱区域1张里侧表示卡为对象才能发动。只要这张卡在场地区域存在，那张里侧表示卡直到结束阶段不能发动，对方在结束阶段必须把那张卡发动或送去墓地。
③：每次自己场上的「淘气仙星」怪兽用战斗·效果给与对方伤害，给与对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90416', '妖精骑士', '这张卡被战斗破坏送去墓地时，由对方选择自己墓地里的1张魔法卡，放在自己卡组的最上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90417', '女武神', '在神话里出现的战斗天使，用手中的枪处以天罚。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90418', '娱乐伙伴 时事秀舞者', '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。
②：「娱乐伙伴」怪兽上级召唤的场合，这张卡可以作为2只的数量解放。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90419', '青色眼睛的巫女', '「青色眼睛的巫女」的①②的效果1回合只能有1次使用其中任意1个。
①：场上的表侧表示的这张卡成为效果的对象时才能发动。选自己场上1只效果怪兽送去墓地，从卡组把最多2只「青眼」怪兽加入手卡（同名卡最多1张）。
②：这张卡在墓地存在的场合，以自己场上1只「青眼」怪兽为对象才能发动。那只怪兽回到持有者卡组，这张卡从墓地特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90420', '天使魔女', '背负着成为天使的命运，但却成为了向往中的魔女。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90421', '淘气仙星·阿库阿安琪儿', '这个卡名在规则上也当作「海晶少女」卡使用。这个卡名的①③的效果在决斗中各能使用1次。
①：自己场上有「淘气仙星」怪兽或「海晶少女」怪兽存在的场合才能发动。这张卡从手卡·墓地特殊召唤。
②：有这张卡位于所连接区的连接怪兽不会被战斗破坏。
③：这张卡作为连接素材送去墓地的场合才能发动。对方的手卡·场上（里侧表示）的卡全部确认。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90422', '淘气仙星·诺布露安琪儿', '「淘气仙星」怪兽2只
这个卡名的①②③的效果1回合各能使用1次。
①：这张卡连接召唤的场合才能发动。从卡组把1张「蓝泪」卡加入手卡。
②：自己的场上或墓地有融合怪兽存在的场合，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽特殊召唤。
③：自己或对方受到效果伤害的场合，以场上1张表侧表示卡为对象才能发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90423', '异响鸣的邀请', '这个卡名的卡在1回合只能发动1张。
①：从以下效果选1个适用。
●从卡组把1只「异响鸣」怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不能把「异响鸣」怪兽以外的场上的怪兽的效果发动。
●自己场上有灵摆怪兽以外的「异响鸣」怪兽存在的场合，从卡组选2只卡名不同的「异响鸣」灵摆怪兽，那之内的1只加入手卡，另1只表侧加入额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90424', '恐啡肽狂龙·梁龙', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「恐啡肽狂龙」卡送去墓地。自己基本分是2000以下的场合，再给与对方500伤害。
②：这张卡被战斗·效果破坏的场合，从自己墓地把1张陷阱卡除外才能发动。从自己墓地选「恐啡肽狂龙·梁龙」以外的1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90425', '怒怒怒魔女', '①：这张卡召唤·特殊召唤成功时才能发动。从手卡把「怒怒怒魔女」以外的1只「怒怒怒」怪兽表侧攻击表示或者里侧守备表示特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90426', '剑巫之圣像骑士', '包含「圣像骑士」怪兽的效果怪兽2只
①：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。
②：这张卡所连接区的怪兽不能攻击。
③：1回合1次，这张卡所连接区有效果怪兽特殊召唤的场合，以这张卡以外的自己或者对方的主要怪兽区域1只怪兽为对象才能发动。那只怪兽的位置向其他的主要怪兽区域移动（不能向从那只怪兽来看的对方场上移动）。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90427', '凭依装着-莱娜', '①：这张卡可以把自己场上的表侧表示的1只「光灵使 莱娜」和1只光属性怪兽送去墓地，从手卡·卡组特殊召唤。
②：这张卡的①的方法特殊召唤成功时才能发动。从卡组把「凭依装着-莱娜」以外的1只守备力1500的魔法师族怪兽加入手卡。
③：这张卡的①的方法特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90428', '淘气仙星·贝拉麦当娜', '「淘气仙星」怪兽2只以上
这个卡名的②的效果1回合只能使用1次。
①：连接召唤的这张卡所连接区没有怪兽存在的场合，这张卡不受其他卡发动的效果影响。
②：这张卡所连接区没有怪兽存在的场合才能发动。给与对方为自己墓地的「淘气仙星」怪兽种类×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90429', '娱乐伙伴 扑克少女', '←4 【灵摆】 4→
【怪兽效果】
①：1回合1次，自己主要阶段才能发动。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。
②：这张卡在灵摆区域被破坏的场合，以自己墓地1只龙族的融合怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90430', '守护神官 玛娜', '这个卡名的①的效果1回合只能使用1次。
①：这张卡在手卡·墓地存在，只以自己场上的魔法师族怪兽1只为对象的对方的魔法·陷阱·怪兽的效果发动时才能发动。这张卡特殊召唤。
②：只要这张卡在怪兽区域存在，自己场上的7星以上的魔法师族怪兽不会被效果破坏。
③：这张卡被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·墓地选1只「黑魔术少女」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90431', '异响鸣的倒水', '这个卡名的卡在1回合只能发动1张。
①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。
●自己回复500基本分。那之后，可以直到「异响鸣」卡出现为止从自己卡组上面翻卡。那个场合，翻开的「异响鸣」卡加入手卡，剩余回到卡组。
●自己受到500伤害。那之后，可以从卡组把「异响鸣的倒水」以外的1张「异响鸣」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90432', '从骑士 特露迪娅', '这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。自己场上的这张卡和除「从骑士 特露迪娅」以外的手卡·卡组1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。这个回合，自己不能把「从骑士 特露迪娅」特殊召唤。
②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。那之后，可以让这张卡的等级上升4星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90433', '米乐与磷寸之仔', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡在手卡存在的场合才能发动。同名卡在对方墓地存在的3张卡从手卡·卡组给对方观看（同名卡最多1张），这张卡特殊召唤。
②：对方把魔法·陷阱·怪兽的效果发动时，把这张卡的①的效果特殊召唤的这张卡送去墓地才能发动。把1张对方发动的那张卡的同名卡从卡组·额外卡组送去墓地，那个发动无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90434', '我我我书记', '①：自己场上有「我我我书记」以外的「我我我」怪兽存在的场合，这张卡可以从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90435', '失乐之魔女', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤成功时才能发动。从卡组把1张「禁忌的」速攻魔法卡加入手卡。
②：对方主要阶段，把这张卡解放才能发动。从卡组把「失乐之魔女」以外的1只天使族·4星怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90436', '闪刀术式-剪斗交刃', '①：自己的主要怪兽区域没有怪兽存在的场合，以自己墓地1只4星「闪刀姬」怪兽为对象才能发动。那只怪兽加入手卡。自己墓地有魔法卡3张以上存在的场合，也能不加入手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90437', 'EM：P猫型手雷', '这个卡名的作为①的方法的特殊召唤1回合只能有1次，作为②的效果1回合只能使用1次。
①：场上或者自己或对方的墓地有连接怪兽存在的场合，这张卡可以从手卡特殊召唤。
②：这张卡在手卡·墓地存在，自己场上的连接2怪兽被送去墓地的场合或者被表侧除外的场合，把这张卡除外，以对方场上1张卡为对象才能发动。那张卡回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90438', '恐啡肽狂龙·钉状龙女王', '卡名不同的「恐啡肽狂龙」怪兽×2
这个卡名的②③的效果1回合各能使用1次。
①：这张卡的攻击力下降自己基本分数值。
②：自己·对方的主要阶段，把基本分支付一半，从自己墓地把1张「恐啡肽狂龙」通常陷阱卡除外才能发动。这个效果变成和那张陷阱卡发动时的效果相同。
③：这张卡被战斗·效果破坏的场合才能发动。从自己墓地选1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90439', '淘气仙星·布拉蒂玛丽', '「淘气仙星」怪兽2只
这个卡名的②的效果1回合只能使用1次。
①：只要这张卡在怪兽区域存在，每次这张卡所连接区有「淘气仙星」怪兽召唤·特殊召唤，自己回复200基本分。
②：从手卡丢弃1张「淘气仙星」卡才能发动。双方玩家各自从卡组抽1张。这个效果的发动时自己基本分比对方多2000以上的场合，这个效果让自己抽出的数量变成2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90440', '闪刀机-虎鲨加农炮', '①：自己的主要怪兽区域没有怪兽存在的场合，以对方墓地1只怪兽为对象才能发动。那只怪兽除外。自己墓地有魔法卡3张以上存在的场合，可以不除外而把那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽不能攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90441', '肃声的龙贤姬 萨菲拉', '这个卡名的①②的效果1回合各能使用1次。
①：把这张卡从手卡丢弃才能发动。从卡组把1张仪式魔法卡送去墓地。那之后，可以把1只战士族·龙族而光属性的仪式怪兽从自己的卡组·墓地加入手卡。
②：把墓地的这张卡除外才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只战士族·龙族而光属性的仪式怪兽仪式召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90442', '恐啡肽狂龙警报', '这个卡名的卡在1回合只能发动1张。
①：把基本分支付一半才能发动。等级合计最多到8星以下为止，从自己墓地选最多2只「恐啡肽狂龙」怪兽特殊召唤。这个回合，自己不是「恐啡肽狂龙」怪兽不能特殊召唤，不能用由这个效果特殊召唤的怪兽攻击宣言。
②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90443', '闪刀机-大黄蜂浮游单元', '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。在自己场上把1只「闪刀姬衍生物」（战士族·暗·1星·攻/守0）守备表示特殊召唤。这衍生物不能解放。自己墓地有魔法卡3张以上存在的场合，那衍生物的攻击力·守备力变成1500。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90444', '灵魂鸟神-彦孔雀', '「灵魂的降神」降临。这张卡不用仪式召唤不能特殊召唤。
①：这张卡仪式召唤成功的场合才能发动。选对方场上最多3只怪兽回到持有者手卡。那之后，可以从手卡把1只4星以下的灵魂怪兽无视召唤条件特殊召唤。
②：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡，在自己场上把2只「灵魂鸟衍生物」（鸟兽族·风·4星·攻/守1500）特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90445', '原始太阳 赫利俄斯', '这张卡的攻击力·守备力变成从游戏中除外的怪兽数量×100的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90446', '神碑之翼 胡基', '「神碑」怪兽×2
①：这张卡从额外卡组的特殊召唤成功的场合，丢弃1张手卡才能发动。从卡组把1张「神碑」场地魔法卡加入手卡。
②：这张卡以外的自己场上的卡被效果破坏的场合，可以作为代替把场上的这张卡除外。
③：场上的这张卡被战斗·效果破坏的场合发动。这张卡回到持有者的额外卡组。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90447', '逆卷之艾莉娅', '可以把自己场上除这张卡以外的1只水属性怪兽做祭品，从手卡特殊召唤1只水属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「逆卷之艾莉娅」从自己场上离开的场合破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90448', '闪刀姬-阿泽莉娅·节制', '包含连接怪兽的怪兽2只以上
这张卡不用连接召唤不能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。
①：这张卡特殊召唤的场合，从自己的手卡·墓地把1张魔法卡除外，以对方场上1只攻击力2500以下的怪兽为对象才能发动。那只表侧表示怪兽当作装备魔法卡使用给这张卡装备。
②：这张卡被战斗破坏时才能发动。从自己的手卡·墓地把这张卡以外的1只「闪刀」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90449', '木花咲弥', '这张卡不能通常召唤。自己场上有灵魂怪兽存在的场合才能特殊召唤。这个方法的「木花咲弥」的特殊召唤1回合只能有1次。
①：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。
②：自己·对方的结束阶段，把墓地的这张卡除外，以自己场上1只灵魂怪兽为对象才能发动。这个回合，那只表侧表示怪兽不能把场上发动的效果发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90450', '魔女术工匠·宝石女巫', '这个卡名的①②的效果1回合各能使用1次。
①：从手卡丢弃1张魔法卡才能发动。从手卡把「魔女术工匠·宝石女巫」以外的1只「魔女术」怪兽特殊召唤。这个效果在对方回合也能发动。
②：把这张卡解放，以自己墓地1只「魔女术工匠·宝石女巫」以外的魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90451', '凶邪魔玩具·梦魇玛丽', '「锋利小鬼」怪兽＋「毛绒动物」怪兽×2
①：这张卡的攻击力在自己回合内上升自己墓地的天使族·恶魔族怪兽数量×300。
②：融合召唤的这张卡战斗破坏怪兽时才能发动。把那只怪兽的等级数量的「魔玩具」、「毛绒动物」、「锋利小鬼」怪兽从卡组送去墓地。
③：场上的这张卡为对象的对方的效果发动时，从额外卡组把1只「魔玩具」怪兽除外才能发动。那个效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90452', '娱乐伙伴 天使女士', '←1 【灵摆】 1→
①：1回合1次，自己和对方的怪兽之间进行战斗的攻击宣言时，从手卡丢弃1只灵摆怪兽才能发动。那只对方怪兽的攻击力直到回合结束时下降1000。
【怪兽效果】
这个卡名的①②的怪兽效果1回合只能有1次使用其中任意1个。
①：从手卡把「娱乐伙伴 天使女士」以外的1只「娱乐伙伴」怪兽和这张卡丢弃才能发动。自己从卡组抽2张。
②：这张卡在墓地存在，自己场上有「异色眼」卡或者「娱乐伙伴 粗鲁先生」存在的场合才能发动。这张卡在自己的灵摆区域放置。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90453', '淘气仙星·施南', '这个卡名的①的效果1回合只能使用1次。
①：从手卡丢弃1张「淘气仙星」卡，以自己墓地1只「淘气仙星」连接怪兽为对象才能发动。那只怪兽特殊召唤。
②：只要这张卡在怪兽区域存在，每次从对方墓地有卡被除外，给与对方那些除外的卡数量×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90454', '魔女术工匠·陶器女巫', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·陶器女巫」以外的1只「魔女术」怪兽特殊召唤。
②：自己手卡是0张的场合，把墓地的这张卡除外，以自己墓地1张「魔女术」卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90455', '灵魂鸟影-彦孔雀', '「灵魂的降神」降临
这个卡名的②的效果1回合只能使用1次。
①：这张卡的卡名只要在手卡·场上存在当作「灵魂鸟神-彦孔雀」使用。
②：把仪式召唤的这张卡解放才能发动。从卡组把1只灵魂怪兽和1张仪式魔法卡加入手卡。
③：这张卡被除外的下个回合的准备阶段发动。除外状态的这张卡特殊召唤。
④：这张卡特殊召唤的回合的结束阶段发动。这张卡回到手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90456', '淘气仙星·坎迪娜', '①：这张卡召唤时才能发动。从卡组把1张「淘气仙星」卡加入手卡。
②：只要这张卡在怪兽区域存在，每次对方把魔法·陷阱卡发动给与对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90457', '淘气仙星音乐节', '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「淘气仙星」怪兽不能召唤·特殊召唤。
①：在自己场上把2只「淘气仙星衍生物」（天使族·光·1星·攻/守0）特殊召唤。
②：从额外卡组特殊召唤的自己场上的「淘气仙星」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90458', '闪刀姬-卡米丽娅', '效果怪兽2只
这张卡不用连接召唤不能从额外卡组特殊召唤，自己对「闪刀姬-卡米丽娅」1回合只能有1次特殊召唤。
①：1回合1次，自己墓地的魔法卡是3张以下的场合才能发动。从卡组把1张「闪刀」卡送去墓地。
②：这张卡被送去墓地的场合，以对方场上1只怪兽为对象才能发动。这张卡在对方场上特殊召唤，作为对象的怪兽送去墓地。这张卡的控制权在这个回合的结束阶段回归原本持有者。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90459', '闪刀起动-交闪', '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。从卡组把「闪刀起动-交闪」以外的1张「闪刀」卡加入手卡。那之后，自己墓地有魔法卡3张以上存在的场合，自己可以从卡组抽1张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90460', '星尘尾迹', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡在手卡·墓地存在，自己场上的怪兽被解放的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。
②：用这张卡为同调素材把「战士」、「同调士」、「星尘」同调怪兽之内任意种同调召唤的场合才能发动。在自己场上把1只「星尘衍生物」（龙族·光·1星·攻/守0）特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90461', '红龙', '调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把有「红龙」的卡名记述的1张魔法·陷阱卡加入手卡。
②：自己·对方回合，以除「红龙」外的场上1只7星以上的同调怪兽为对象才能发动。这张卡回到额外卡组，和作为对象的怪兽相同等级的1只龙族同调怪兽当作同调召唤从额外卡组特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90462', '创造之代行者 维纳斯', '①：支付500基本分才能发动。从手卡·卡组把1只「神圣球体」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90463', '魔女术熟练工', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术熟练工」以外的1只「魔女术」怪兽特殊召唤。
②：从自己墓地把这张卡和1张「魔女术」魔法卡除外才能发动。这个效果变成和那张魔法卡发动时的效果相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90464', '淘气仙星乐队·德拉玛蒂丝', '「淘气仙星」怪兽×2
这个卡名的①③的效果1回合各能使用1次。
①：这张卡融合召唤的场合才能发动。同名卡不在自己的场上·墓地存在的1张「淘气仙星」卡从卡组加入手卡。
②：有这张卡位于所连接区的自己的「淘气仙星」连接怪兽的攻击力上升1000。
③：自己或对方受到效果伤害的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90465', '异响鸣的不调和', '这个卡名的卡在1回合只能发动1张。
①：给可以放置响鸣指示物的自己的灵摆区域1张卡放置1个响鸣指示物。那之后，从以下效果选1个适用。
●自己回复500基本分。那之后，可以把「异响鸣的不调和」以外的自己的除外状态的1张「异响鸣」卡加入手卡。
●自己受到500伤害。那之后，可以把「异响鸣的不调和」以外的自己墓地1张「异响鸣」卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90466', '灵摆月之魔法师', '←0 【灵摆】 0→
这个卡名的灵摆效果1回合只能使用1次。
①：自己主要阶段才能发动。从自己的额外卡组把1只表侧表示的「灵摆」灵摆怪兽加入手卡。那之后，这张卡破坏。
【怪兽效果】
这个卡名的怪兽效果1回合只能使用1次。
①：自己主要阶段才能发动。从自己的额外卡组把持有用自己的灵摆区域2张卡的灵摆刻度可以灵摆召唤的等级的最多2只表侧表示的灵摆怪兽加入手卡。这个效果的发动后，直到回合结束时自己只要灵摆召唤不成功，不能把怪兽的效果发动，自己的灵摆区域的卡的效果无效化。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90467', '解咒的神碑', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。
●对方在抽卡阶段以外从卡组把卡加入手卡的场合才能发动。对方手卡随机选1张丢弃。那之后，从对方卡组上面把2张卡除外。
●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90468', '微睡的神碑', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。
●以场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽只有1次不会被战斗·效果破坏，不能攻击。那之后，从对方卡组上面把3张卡除外。
●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90469', '守护天使 贞德', '①：这张卡战斗破坏怪兽送去墓地的场合发动。自己基本分回复那只怪兽的原本攻击力的数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90470', '红莲魔龙', '调整＋调整以外的怪兽1只以上
①：这张卡向对方的守备表示怪兽进行攻击的伤害计算后发动。对方场上的守备表示怪兽全部破坏。
②：自己结束阶段发动。这张卡在场上表侧表示存在的场合，这个回合没有攻击宣言的自己场上的其他怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90471', '魔女术人偶·阿鲁鲁女神', '这个卡名的①的效果1回合只能使用1次。
①：这张卡在手卡存在，自己场上的魔法师族怪兽成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时，以对方场上1张卡或者自己墓地1张「魔女术」魔法卡为对象才能发动。这张卡特殊召唤，那张卡回到持有者手卡。
②：对方准备阶段发动。这张卡回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90472', '闭锁天之月', '效果怪兽2只
这个卡名的效果1回合只能使用1次。
①：以这张卡所连接区1只对方的表侧表示怪兽为对象才能发动。这个回合，自己用自己场上的这张卡为素材把连接5怪兽连接召唤的场合，作为对象的对方怪兽也能作为连接素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90473', '阳光妖精', '这张卡被光属性的同调怪兽的同调召唤使用送去墓地的场合，自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90474', '守护者·艾尔玛', '当自己场上存在「蝶之短剑-回音」时才能召唤·反转召唤·特殊召唤。这张卡召唤·特殊召唤成功时，可以从自己的墓地里选择1张装备魔法卡装备在这张卡身上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90475', '闪刀姬-泽克', '包含「闪刀姬」怪兽的怪兽2只
这张卡不用连接召唤不能特殊召唤，自己对「闪刀姬-泽克」1回合只能有1次特殊召唤。
①：这张卡连接召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到下次的对方结束阶段除外。
②：1回合1次，以这张卡以外的自己场上1张卡为对象才能发动。这张卡的攻击力上升1000。那之后，作为对象的卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90476', '月之魔法师', '住在月亮上的魔法师。用月之魔力迷惑对方。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90477', '异响鸣之异神-光耀天使', '效果怪兽1只
这张卡的连接召唤若非自己的灵摆区域的天使族怪兽卡的响鸣指示物是3个以上的场合则不能进行，自己对「异响鸣之异神-光耀天使」1回合只能有1次特殊召唤。
①：这张卡连接召唤的场合，以最多有自己的灵摆区域的响鸣指示物数量的对方场上的怪兽为对象才能发动。那些怪兽破坏。
②：把自己的灵摆区域3个响鸣指示物取除才能发动。这个回合，这张卡在同1次的战斗阶段中可以作3次攻击。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90478', '淘气仙星·布露姆', '2星以下的「淘气仙星」怪兽1只
这个卡名的②的效果1回合只能使用1次。
①：这张卡连接召唤的场合才能发动。对方抽1张。
②：这张卡所连接区的表侧表示的「淘气仙星」怪兽被战斗·效果破坏的场合才能发动。给与对方为对方手卡数量×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90479', '异响鸣的调律', '这个卡名的卡在1回合只能发动1张。
①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。
●自己回复500基本分。可以特殊召唤的怪兽在自己墓地存在的场合，再让那之内的1只由对方选出，那只怪兽在自己场上特殊召唤。
●自己受到500伤害。那之后，可以从自己墓地把1只4星怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90480', '勇气之天使 维多利卡', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合才能发动。从手卡把1只5星以上的光属性怪兽特殊召唤，自己失去那只怪兽的原本攻击力数值的基本分。这个效果特殊召唤的怪兽的攻击力直到回合结束时变成2倍。
②：怪兽区域的这张卡被破坏的场合，从自己墓地把这张卡以外的1只天使族怪兽除外才能发动。和除外的怪兽等级相同的1只天使族怪兽从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90481', '于贝尔幻影', '「于贝尔」怪兽＋攻击力和守备力是0的恶魔族怪兽
让自己的手卡·场上·墓地的上记的卡回到卡组·额外卡组的场合才能特殊召唤。这张卡不能作为融合素材。这个卡名的②的效果1回合只能使用1次。
①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。
②：对方怪兽的效果发动时，把这张卡解放才能发动。那个效果变成「对方把自身的手卡·卡组·场上1只「于贝尔」怪兽破坏」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90482', '五阵魔术师', '魔法师族怪兽×5
这张卡不用融合召唤不能特殊召唤。
①：魔法师族怪兽5种类作为素材让这张卡融合召唤成功的场合才能发动。对方场上的卡全部破坏。
②：这张卡只要在怪兽区域存在，不能解放，不能作为融合素材，不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90483', '魔女术工匠·服装女巫', '这个卡名的②的效果1回合只能使用1次。
①：只要这张卡在怪兽区域存在，自己场上的其他的魔法师族怪兽不会成为对方的效果的对象。
②：从手卡丢弃1张魔法卡，以对方场上1张表侧表示的卡为对象才能发动。那张卡破坏。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90484', '淘气仙星·福克希维琪', '天使族怪兽2只以上
这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合才能发动。给与对方为对方场上的卡数量×200伤害。
②：连接召唤的这张卡被战斗·效果破坏的场合才能发动。从额外卡组把1只连接2以下的「淘气仙星」怪兽特殊召唤。那之后，给与对方为对方场上的卡数量×200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90485', '淘气仙星·菲沃斯', '这个卡名的效果1回合只能使用1次。
①：这张卡作为「淘气仙星」连接怪兽的连接素材送去墓地的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90486', '青色眼睛的少女', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：场上的表侧表示的这张卡成为效果的对象时才能发动。从自己的手卡·卡组·墓地选1只「青眼白龙」特殊召唤。
②：这张卡被选择作为攻击对象时才能发动。那次攻击无效，这张卡的表示形式变更。那之后，可以从自己的手卡·卡组·墓地选1只「青眼白龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90487', '娱乐伙伴 帮助公主', '①：自己对「娱乐伙伴 帮助公主」以外的「娱乐伙伴」怪兽的召唤·特殊召唤成功时才能发动。这张卡从手卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90488', '代行者的近卫 穆恩', '天使族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡连接召唤成功的场合才能发动。从卡组把1张「天空的圣域」或者有那个卡名记述的卡送去墓地。场上或者墓地有「天空的圣域」存在的场合，可以作为代替从自己的卡组·墓地选1只「神秘之代行者 厄斯」加入手卡。
②：把自己场上1只天使族怪兽解放，以对方场上1张卡为对象才能发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90489', '闪刀姬-雫空', '水属性以外的「闪刀姬」怪兽1只
自己对「闪刀姬-雫空」1回合只能有1次特殊召唤。
①：对方场上的怪兽的攻击力·守备力下降自己墓地的魔法卡数量×100。
②：这张卡特殊召唤的回合的结束阶段才能发动。从卡组把同名卡不在自己墓地存在的1张「闪刀」魔法卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90490', '神秘之代行者 厄斯', '①：这张卡召唤成功时才能发动。从卡组把「神秘之代行者 厄斯」以外的1只「代行者」怪兽加入手卡。场上有「天空的圣域」存在的场合，可以把加入手卡的怪兽改成1只「主宰者·许珀里翁」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90491', '淘气仙星·那耳姬丝', '这个卡名的①的效果1回合只能使用1次。
①：对方受到效果伤害的场合才能发动。这张卡从手卡特殊召唤。
②：只要这张卡在怪兽区域存在，每次对方把手卡·墓地的怪兽的效果发动，给与对方200伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90492', '娱乐伙伴 扑克魔女', '←4 【灵摆】 4→
①：1回合1次，自己主要阶段才能发动。从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。
【怪兽效果】
①：把这张卡解放才能发动。从自己的卡组·墓地选1张「融合」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90493', '神碑之泉', '①：只要这张卡在场地区域存在，自己在对方回合可以把「神碑」速攻魔法卡从手卡发动。
②：1回合1次，自己把「神碑」速攻魔法卡发动的场合，以自己墓地最多3张「神碑」速攻魔法卡为对象才能发动。那些卡用喜欢的顺序回到卡组下面。那之后，自己从卡组抽出回去的数量。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90494', '恐啡肽狂龙·镰刀龙', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选1张「恐啡肽狂龙」陷阱卡在自己的魔法与陷阱区域盖放。自己基本分是2000以下的场合，再让这张卡的攻击力上升500。
②：这张卡被战斗·效果破坏的场合，从自己墓地把1张陷阱卡除外才能发动。从自己墓地选「恐啡肽狂龙·镰刀龙」以外的1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90495', '神碑之翼 穆宁', '「神碑」怪兽×2
①：这张卡从额外卡组的特殊召唤成功的场合，丢弃1张手卡才能发动。从卡组把1张「神碑」永续魔法卡加入手卡。
②：以自己场上的「神碑」卡或者盖放的卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把场上的这张卡除外才能发动。那个发动无效并破坏。
③：自己·对方的结束阶段发动。自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90496', '觉醒吧百夫长骑士！', '这个卡名的①②的效果1回合各能使用1次。
①：自己的魔法与陷阱区域有表侧表示怪兽卡存在的场合，宣言4或8的等级才能发动。把持有宣言的等级的1只「百夫长骑士衍生物」（炎族·暗·攻/守0）在自己场上特殊召唤。这衍生物不能作为融合·连接素材。
②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把「觉醒吧百夫长骑士！」以外的1张「百夫长骑士」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90497', '娱乐伙伴 诱导女导演', '这个卡名的③的效果1回合只能使用1次。
①：只要自己场上有「异色眼」怪兽存在，对方不能选择这张卡作为攻击对象。
②：只要这张卡在怪兽区域守备表示存在，自己的「异色眼」怪兽不会被战斗破坏，那次战斗发生的对自己的战斗伤害变成0。
③：以自己墓地1只1星怪兽为对象才能发动。那只怪兽效果无效特殊召唤，只用那只怪兽和这张卡为素材作同调召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90498', '邪恶★双子克星 麻烦·桑妮', '包含「邪恶★双子」怪兽的怪兽2只以上
这个卡名的①②的效果1回合各能使用1次。
①：自己·对方回合，把这张卡解放才能发动。从自己墓地把「姬丝基勒」怪兽和「璃拉」怪兽各最多1只特殊召唤。
②：把墓地的这张卡除外，从自己的手卡·卡组·场上（表侧表示）把1只「邪恶★双子」怪兽送去墓地才能发动。场上1张卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90499', '破坏的神碑', '这个卡名的卡在1回合只能发动1张。
①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。
●以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。那之后，从对方卡组上面把4张卡除外。
●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90500', '淘气仙星·斯威特戴薇儿', '「淘气仙星」怪兽2只
①：只要这张卡在怪兽区域存在，每次这张卡所连接区的怪兽被战斗·效果破坏送去墓地，给与对方200伤害。
②：每次「淘气仙星」怪兽的效果让对方受到伤害发动。对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降这张卡所连接区的怪兽数量×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90501', '魔女术工匠·绘画女巫', '这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·绘画女巫」以外的1只「魔女术」怪兽特殊召唤。
②：把墓地的这张卡除外才能发动。自己从卡组抽1张，那之后从手卡选1张「魔女术」卡送去墓地。手卡没有「魔女术」卡的场合，手卡全部除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90502', '武之贤者-阿卡丝', '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。
①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。
②：自己场上的连接怪兽被战斗·效果破坏的场合，可以作为代替把自己墓地1张魔法卡除外。
③：这张卡被战斗·效果破坏送去墓地的场合，以除外的1张自己的「闪刀」魔法卡为对象才能发动。那张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90503', '龙骑兵 石像怪2', '这个卡名的①②③的效果1回合各能使用1次。
①：把自己场上1张表侧表示的「百夫长骑士」卡送去墓地才能发动。这张卡从手卡特殊召唤。这个回合，自己不能把「龙骑兵 石像怪2」特殊召唤。
②：这张卡作为同调素材送去墓地的场合才能发动。这张卡加入手卡。
③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。那之后，可以让这张卡的等级下降4星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90504', '淘气仙星·卡罗贝恩', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：自己场上的怪兽不存在的场合或者只有「淘气仙星」怪兽的场合才能发动。这张卡从手卡特殊召唤。
②：自己的「淘气仙星」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只自己怪兽的攻击力直到回合结束时上升那自身原本攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90505', '闪刀机-黑寡妇抓锚', '①：自己的主要怪兽区域没有怪兽存在的场合，以场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。那之后，自己墓地有魔法卡3张以上存在的场合，可以把那只怪兽的控制权直到结束阶段得到。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90506', '闪刀姬-阿泽莉娅', '光·暗属性怪兽2只
这张卡不用连接召唤不能特殊召唤，自己对「闪刀姬-阿泽莉娅」1回合只能有1次特殊召唤。
①：这张卡特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，自己墓地的魔法卡是3张以下的场合，这张卡送去墓地。
②：1回合1次，这张卡和对方怪兽进行战斗的伤害步骤开始时，从自己墓地把1张魔法卡除外才能发动。那只对方怪兽破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90507', '淘气仙星·莉莉贝儿', '这个卡名的①的效果1回合只能使用1次。
①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。
②：这张卡可以直接攻击。
③：这张卡给与对方战斗伤害时，以自己墓地1只「淘气仙星」怪兽为对象才能发动。那只怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90508', '守墓的陷阱', '这个卡名的②③的效果1回合各能使用1次。
①：只要自己墓地有「现世与冥界的逆转」存在，对方不能把墓地的卡的效果发动，不能把墓地的怪兽特殊召唤。
②：双方的主要阶段，丢弃1张手卡才能发动。从卡组把1只「守墓」怪兽或者天使族·地属性怪兽加入手卡。
③：这张卡表侧表示存在的场合，对方抽卡阶段的抽卡前，宣言1个卡名发动。把通常抽卡的卡确认，宣言的卡的场合，送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90509', '破坏之代行者 维纳斯', '这个卡名的①②的效果1回合只能有1次使用其中任意1个。
①：从自己墓地把1只「创造之代行者 维纳斯」除外才能发动。这张卡从手卡特殊召唤。
②：支付500的倍数的基本分，从自己墓地的怪兽以及除外的自己怪兽之中以支付的基本分每500为1只的「神圣球体」为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合回到持有者卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90510', '恐啡肽狂龙残虐', '这个卡名的卡在1回合只能发动1张。
①：把基本分支付一半才能发动。选自己场上1只「恐啡肽狂龙」怪兽和对方场上1张卡破坏。
②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90511', '真红莲超新星龙', '调整3只＋调整以外的同调怪兽1只以上
这张卡用同调召唤才能从额外卡组特殊召唤。
①：这张卡的攻击力上升自己墓地的调整数量×500。
②：场上的这张卡不会被对方的效果破坏。
③：1回合1次，对方怪兽的效果发动时或者对方怪兽的攻击宣言时才能发动。这张卡以及对方场上的卡全部除外。
④：这张卡的③的效果除外的场合，下次的自己结束阶段发动。除外状态的这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90512', '淘气仙星的花束', '这个卡名的卡在1回合只能发动1张。
①：以自己场上1只「淘气仙星」怪兽和场上1只表侧表示怪兽为对象才能发动。那只「淘气仙星」怪兽回到持有者手卡，另1只作为对象的怪兽的攻击力直到回合结束时上升回到手卡的怪兽的原本攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90513', '白之少女', '这个卡名的①②③的效果1回合各能使用1次。
①：把手卡·场上的这张卡送去墓地才能发动。从自己的手卡·卡组·墓地把1张「真正之光」在自己的魔法与陷阱区域表侧表示放置。
②：这张卡在墓地存在的状态，自己把「青眼白龙」特殊召唤的场合才能发动。这张卡特殊召唤。
③：场上的这张卡成为攻击·效果的对象时才能发动。从自己墓地把1只「青眼白龙」或者光属性·1星调整特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90514', '噩梦之玉座', '这个卡名的卡在1回合只能发动1张。
①：作为这张卡的发动时的效果处理，以下效果可以适用。
●从卡组选1只攻击力和守备力是0的恶魔族怪兽加入手卡或破坏。
②：1回合1次，自己场上的表侧表示的「于贝尔」怪兽因效果从场上离开的场合才能发动。原本等级比那之内的1只要高1星或低1星的1只「于贝尔」怪兽从自己的卡组·墓地·除外状态加入手卡。那之后，可以把那只怪兽无视召唤条件特殊召唤。', '是否选卡组的恶魔族怪兽？', '加入手卡', '是否把那只怪兽破坏？', '是否特殊召唤？', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90515', '次元的裂缝', '①：只要这张卡在魔法与陷阱区域存在，被送去双方墓地的怪兽不去墓地而除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90516', '治疗之神 迪安·凯特', '①：自己回复1000基本分。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90517', '苦涩的选择', '从卡组选择5张卡给对方看。对方从这些卡中选择1张。对方选择的卡加入自己手卡，其他的卡丢弃去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90518', '神炎皇 乌利亚', '这张卡不能通常召唤。把自己场上3张表侧表示的陷阱卡送去墓地的场合才能特殊召唤。
①：这张卡的攻击力上升自己墓地的永续陷阱卡数量×1000。
②：1回合1次，以对方场上盖放的1张魔法·陷阱卡为对象才能发动。盖放的那张卡破坏。不能对应这个效果的发动让魔法·陷阱卡发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90519', '救世星龙', '「救世龙」＋「星尘龙」＋调整以外的怪兽1只
对方把魔法·陷阱·效果怪兽的效果发动时，可以通过把这张卡解放来让那个发动无效，对方场上的卡全部破坏。1回合1次，可以选择对方场上表侧表示存在的1只怪兽，那个效果直到结束阶段时无效。此外，这个效果无效的怪兽记述的效果在这个回合可以作为这张卡的效果只有1次发动。结束阶段时，这张卡回到额外卡组，选择自己墓地1只「星尘龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90520', '命运英雄 魔性人', '①：把墓地的这张卡除外才能发动。从卡组把1只「命运英雄 魔性人」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90521', '机巧将军 无零', '调整＋调整以外的机械族怪兽1只以上
这张卡同调召唤成功时，可以从自己卡组把1只名字带有「机巧」的怪兽特殊召唤。1回合1次，可以选择场上存在的1只怪兽，把表示形式变更。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90522', '流星龙', '同调怪兽调整＋「星尘龙」
①：1回合1次，可以发动。从自己卡组上面翻开5张并回到卡组。这个回合这张卡可以作出最多有所翻开之中的调整数量的攻击。
②：1回合1次，要让场上的卡破坏的效果的发动时才能发动。那个效果无效并破坏。
③：1回合1次，对方的攻击宣言时以攻击怪兽为对象才能发动。场上的这张卡除外，那次攻击无效。
④：这个③的效果除外的回合的结束阶段发动。这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90523', '命运英雄 绝命人', '「命运英雄」怪兽＋暗属性效果怪兽
这个卡名的效果1回合只能使用1次。
①：自己·对方回合，丢弃1张手卡才能发动。从手卡·卡组把1只「命运英雄」怪兽送去墓地。那之后，自己墓地有「命运英雄」怪兽存在的场合，自己场上的全部「命运英雄」怪兽的攻击力直到回合结束时上升自己墓地的「命运英雄」怪兽数量×200。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90524', '降雷皇 哈蒙', '这张卡不能通常召唤。把自己场上3张表侧表示的永续魔法卡送去墓地的场合才能特殊召唤。
①：只要这张卡在怪兽区域守备表示存在，对方怪兽不能选择这张卡以外的怪兽作为攻击对象。
②：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方1000伤害。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90525', '流天类星龙', '同调怪兽调整＋调整以外的同调怪兽2只以上
这张卡不用同调召唤不能特殊召唤。
①：这张卡在同1次的战斗阶段中可以作出最多有那些作为同调素材的怪兽之内除调整以外的怪兽数量的攻击。
②：1回合1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。
③：表侧表示的这张卡从场上离开时才能发动。从额外卡组把1只「流星龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90526', '罪 星尘龙', '这张卡不能通常召唤。从额外卡组把1只「星尘龙」除外的场合才能特殊召唤。
①：「罪」怪兽在场上只能有1只表侧表示存在。
②：只要这张卡在怪兽区域存在，场地区域的表侧表示的卡不会被效果破坏。
③：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。
④：没有场地魔法卡表侧表示存在的场合这张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90527', '欧尼斯特', '①：自己主要阶段才能发动。场上的表侧表示的这张卡回到手卡。
②：自己的光属性怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只怪兽的攻击力直到回合结束时上升进行战斗的对方怪兽的攻击力数值。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90528', '混沌幻魔 阿米泰尔', '「神炎皇 乌利亚」＋「降雷皇 哈蒙」＋「幻魔皇 拉比艾尔」
把自己场上的上记卡除外的场合才能从额外卡组特殊召唤（不需要「融合」）。
①：这张卡的攻击力在自己回合内上升10000。
②：这张卡不会被战斗破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90529', '科技属 刃枪手', '同调怪兽调整＋调整以外的同调怪兽1只以上
①：场上的这张卡为对象的魔法·陷阱卡由对方发动时，把1张手卡送去墓地才能发动。那个效果无效。
②：对方回合1次，从自己墓地把1只「科技属」怪兽除外才能发动。表侧表示的这张卡除外。
③：这张卡的②的效果除外的场合，下次的准备阶段发动。除外状态的这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90530', 'XX-剑士 加特姆士', '调整＋地属性怪兽1只以上
①：把自己场上1只「X-剑士」怪兽解放才能发动。对方手卡随机选1张丢弃。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90531', '命运英雄 圆盘人', '这个卡名的效果在决斗中只能使用1次。这张卡在送去墓地的回合不能作从墓地的特殊召唤。
①：这张卡从墓地的特殊召唤成功的场合才能发动。自己从卡组抽2张。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90532', '特异英雄 十字人', '战士族怪兽2只
这个卡名的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是「英雄」怪兽不能特殊召唤。
①：这张卡连接召唤的场合，以自己墓地1只「命运英雄」怪兽为对象才能发动。那只怪兽特殊召唤。
②：把自己场上1只「命运英雄」怪兽解放才能发动。和解放的怪兽卡名不同的1只「英雄」怪兽从卡组加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90533', '星尘龙/爆裂体', '这张卡不能通常召唤。「爆裂模式」的效果以及这张卡的效果才能特殊召唤。魔法·陷阱·效果怪兽的效果发动时，可以把这张卡解放让那个发动无效并破坏。这个效果适用的回合的结束阶段时，为这个效果发动而解放在墓地存在的这张卡可以在自己场上特殊召唤。此外，场上存在的这张卡被破坏时，可以把自己墓地存在的1只「星尘龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90534', '命运英雄 神性人', '这个卡名的②的效果1回合只能使用1次。
①：这张卡的攻击宣言时，以对方场上1张表侧表示的魔法卡为对象才能发动。那张卡破坏，给与对方500伤害。
②：自己手卡是0张的场合，从自己墓地把这张卡和1只「命运英雄」怪兽除外才能发动。自己从卡组抽2张。这个效果在这张卡送去墓地的回合不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90535', '救世魔龙', '「救世龙」＋「红莲魔龙」＋调整以外的怪兽1只
这张卡不会被卡的效果破坏。这张卡攻击的场合，伤害计算后把场上守备表示存在的怪兽全部破坏。1回合1次，可以直到结束阶段时把对方1只表侧表示怪兽的效果无效，这张卡的攻击力上升那只怪兽的攻击力数值。结束阶段时这张卡回到额外卡组，把自己墓地存在的1只「红莲魔龙」特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90536', '幻魔皇 拉比艾尔', '这张卡不能通常召唤。把自己场上3只恶魔族怪兽解放的场合才能特殊召唤。
①：1回合1次，把这张卡以外的自己场上1只怪兽解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的原本攻击力数值。
②：对方对怪兽的召唤成功的场合发动。在自己场上把1只「幻魔衍生物」（恶魔族·暗·1星·攻/守1000）特殊召唤。这衍生物不能攻击宣言。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90537', '红莲魔龙', '调整＋调整以外的怪兽1只以上
①：这张卡向对方的守备表示怪兽进行攻击的伤害计算后发动。对方场上的守备表示怪兽全部破坏。
②：自己结束阶段发动。这张卡在场上表侧表示存在的场合，这个回合没有攻击宣言的自己场上的其他怪兽全部破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90538', '闪珖龙 星尘', '调整＋调整以外的怪兽1只以上
1回合1次，选择自己场上表侧表示存在的1张卡才能发动。选择的卡在这个回合只有1次不会被战斗以及卡的效果破坏。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90539', '命运英雄 敌托邦人', '「命运英雄」怪兽×2
「命运英雄 敌托邦人」的①②的效果1回合各能使用1次。
①：这张卡特殊召唤成功的场合，以自己墓地1只4星以下的「命运英雄」怪兽为对象才能发动。给与对方那只怪兽的攻击力数值的伤害。
②：这张卡的攻击力和原本攻击力不同的场合，以场上1张卡为对象才能发动。那张卡破坏，这张卡的攻击力变成原本数值。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90540', '命运英雄 暮托邦人', '「命运英雄」融合怪兽＋「命运英雄」怪兽
①：这张卡融合召唤成功的场合才能发动。从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。
②：1回合1次，以场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏，那只怪兽的战斗发生的双方的战斗伤害变成0。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90541', '真红莲新星龙', '调整2只＋「红莲魔龙」
①：这张卡的攻击力上升自己墓地的调整数量×500。
②：场上的这张卡不会被对方的效果破坏。
③：对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。场上的这张卡除外，那次攻击无效。
④：这张卡的③的效果除外的回合的结束阶段发动。除外状态的这张卡特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90542', '青眼光龙', '这张卡不能通常召唤。把自己场上1只「青眼究极龙」解放的场合才能特殊召唤。
①：这张卡的攻击力上升自己墓地的龙族怪兽数量×300。
②：这张卡为对象的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90543', '雅典娜', '①：1回合1次，把「雅典娜」以外的自己场上1只表侧表示的天使族怪兽送去墓地，以「雅典娜」以外的自己墓地1只天使族怪兽为对象才能发动。那只天使族怪兽特殊召唤。
②：这张卡已在怪兽区域存在的状态，这张卡以外的天使族怪兽召唤·反转召唤·特殊召唤的场合发动。给与对方600伤害。', '特殊召唤', '伤害', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90544', '恶魔驯服者', '反转：在回合结束前得到对方场上的1只表侧表示存在的恶魔族怪兽。', '控制权转移', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90545', '码丽丝<兵卒>睡鼠', '这个卡名的①③的效果1回合各能使用1次。
①：自己主要阶段才能发动。从卡组把1只「码丽丝」怪兽除外。这个回合中自己场上的「码丽丝」怪兽的攻击力上升600。
②：有这张卡位于所连接区的「码丽丝」连接怪兽不会被效果破坏。
③：这张卡被除外的场合，支付300基本分才能发动。这张卡特殊召唤。这个回合，自己不是连接怪兽不能从额外卡组特殊召唤。', '除外', '', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90546', '能朋克 世阿弥', '这个卡名的①②的效果1回合各能使用1次。
①：支付600基本分才能发动。从卡组把「能朋克 世阿弥」以外的1只「朋克」怪兽加入手卡。
②：这张卡被送去墓地的场合，以自己场上1只「朋克」怪兽为对象才能发动。那只怪兽的攻击力上升600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90547', '治安战警队 铂金女', '这个卡名的①的效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功的场合，以「治安战警队 铂金女」以外的除外的1只自己的「治安战警队」怪兽为对象才能发动。那只怪兽特殊召唤。
②：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽的攻击力下降600。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90548', '阿洛美勒丝之虫惑魔', '4星怪兽×2只以上
这个卡名的②③的效果1回合各能使用1次。
①：持有超量素材的这张卡不受陷阱卡的效果影响。
②：把这张卡2个超量素材取除才能发动。从自己墓地选1只昆虫族·植物族的4星怪兽特殊召唤。
③：自己的卡的效果让对方怪兽从场上离开，被送去墓地的场合或者被除外的场合，把这张卡1个超量素材取除，以那之内的1只为对象才能发动。那只怪兽在自己场上特殊召唤。', '', '特殊召唤对方怪兽', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90549', '救祓少女·索菲娅', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有其他的「救祓少女」怪兽存在的场合才能发动。自己从卡组抽1张。自己场上有「救祓少女·伊雷娜」存在的场合，再让自己回复800基本分。
②：自己·对方的墓地的卡因对方从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。', '', '超量召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90550', '救祓少女·米迦埃莉丝', '4星怪兽×2
这个卡名的①③的效果1回合各能使用1次。
①：用「救祓少女」怪兽为素材对这张卡的超量召唤成功的自己·对方回合，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。
②：这张卡不会被和从墓地特殊召唤的怪兽的战斗破坏。
③：把这张卡1个超量素材取除才能发动。从卡组把1张「救祓少女」魔法·陷阱卡加入手卡。', '对方卡除外', '卡组检索', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90551', '救祓少女·卡斯皮特尔', '4星怪兽×2
这个卡名的①③的效果1回合各能使用1次。
①：这张卡用「救祓少女」怪兽为素材作超量召唤成功的场合才能发动。这个回合，双方不能从墓地把怪兽特殊召唤。
②：这张卡不会被和从墓地特殊召唤的怪兽的战斗破坏。
③：把这张卡1个超量素材取除才能发动。从卡组把1只「救祓少女」怪兽加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90552', '救祓少女·吉卜利娜', '4星怪兽×2
这个卡名的①③的效果1回合各能使用1次。
①：用「救祓少女」怪兽为素材对这张卡的超量召唤成功的自己·对方回合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。
②：这张卡不会被从墓地特殊召唤的怪兽发动的效果破坏。
③：把这张卡1个超量素材取除才能发动。这个回合中自己场上的超量怪兽的攻击力上升800。', '对方怪兽效果无效', '攻击力上升', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90553', '救祓少女·阿索菲勒', '4星怪兽×2
这个卡名的①③的效果1回合各能使用1次。
①：这张卡用「救祓少女」怪兽为素材作超量召唤成功的场合才能发动。这个回合，双方不能把墓地的卡的效果发动。
②：这张卡不会被从墓地特殊召唤的怪兽发动的效果破坏。
③：把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90554', '机关傀儡-素瓷人偶', '①：这张卡可以把手卡1只「机关傀儡」怪兽丢弃，从手卡特殊召唤。
②：把墓地的这张卡除外才能发动。这个回合中，对方不能把自己场上的「机关傀儡」怪兽作为效果的对象。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90555', '机关傀儡-血腥人偶', '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是「机关傀儡」怪兽不能从额外卡组特殊召唤。
①：这张卡在手卡存在的场合，把额外卡组1只「机关傀儡」超量怪兽给对方观看才能发动。把持有和给人观看的怪兽的阶级相同数值的等级的卡组1只「机关傀儡」怪兽和这张卡特殊召唤。
②：这张卡从手卡以外送去墓地的场合才能发动。这张卡加入手卡。', '特殊召唤', '回到手卡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90556', '艺妓之影', '这张卡战斗破坏对方怪兽的场合，给这张卡放置1个魔力指示物。这张卡的攻击力上升这张卡放置的魔力指示物数量×200的数值。', '放置指示物', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90557', '西托莉丝之虫惑魔', '4星怪兽×2
这个卡名的②③的效果1回合各能使用1次。
①：持有超量素材的这张卡不受和给这张卡作为超量素材中的怪兽相同种族的怪兽（除这张卡外）发动的效果以及陷阱卡的效果影响。
②：把这张卡1个超量素材取除才能发动。从卡组把1只「虫惑魔」怪兽加入手卡。
③：原本持有者是对方的怪兽被效果所送去墓地的场合或者所除外的场合才能发动。选那之内的1只作为这张卡的超量素材。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90558', '半龙女仆·贴身龙女', '相同属性而等级不同的「半龙女仆」怪兽×2
从自己的场上以及墓地各把1只上记的卡除外的场合才能从额外卡组特殊召唤。这个卡名的①②的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把1只4星以下的「半龙女仆」怪兽特殊召唤。
②：自己·对方的准备阶段才能发动。自己的场上·除外状态的怪兽作为融合素材回到卡组，把1只龙族融合怪兽融合召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90559', '魔偶甜点·果冻天使', '这个卡名的①的效果1回合只能使用1次。
①：把这张卡解放才能发动。从卡组把1只「魔偶甜点」怪兽特殊召唤。这个效果特殊召唤的怪兽不会被战斗破坏，下次的自己回合的结束阶段回到卡组。
②：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。', '返回卡组', '特殊召唤', '「魔偶甜点·果冻天使」效果适用中', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90560', '魔偶甜点·布丁公主', '①：自己墓地没有怪兽存在的场合，这张卡的攻击力·守备力上升800。
②：这张卡和对方怪兽进行战斗的伤害计算后，以对方场上1张卡为对象才能发动。那张对方的卡破坏。
③：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。', '返回卡组', '破坏', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90561', '米之七音服·埃莉蒂娅', '←6 【灵摆】 6→
①：自己的「七音服」灵摆怪兽的灵摆召唤不会被无效化。
【怪兽效果】
这个卡名的①的怪兽效果1回合只能使用1次。
①：这张卡召唤·特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡。
②：只要自己的灵摆区域有偶数的灵摆刻度存在，自己的「七音服」灵摆怪兽的战斗发生的对自己的战斗伤害变成0。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90562', '光道弓手 费莉丝', '这张卡不能通常召唤，用卡的效果才能特殊召唤。
①：这张卡被怪兽的效果从卡组送去墓地的场合发动。这张卡特殊召唤。
②：把这张卡解放，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。那之后，从自己卡组上面把3张卡送去墓地。', '特殊召唤', '破坏', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90563', '光道圣灵 夏尔', '墓地中每有1种名字带有「光道」的怪兽卡，这张卡的攻击力就上升300。每次自己的结束阶段时，将自己卡组最上方的2张卡送去墓地。', '从卡组送2张卡去墓地', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90564', '光道圣女 密涅瓦', '4星怪兽×2
这个卡名的①②的效果1回合各能使用1次。
①：把这张卡1个超量素材取除才能发动。从自己卡组上面把3张卡送去墓地。那之中有「光道」卡的场合，再让自己抽出那个数量。
②：这张卡被战斗或者对方的效果破坏的场合才能发动。从自己卡组上面把3张卡送去墓地。那之中有「光道」卡的场合，可以再把最多有那个数量的场上的卡破坏。', '是否选场上的卡破坏？', '送去墓地并抽卡', '送去墓地并破坏', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90565', '遗式术师·艾米莉娅', '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，自己场上有这张卡以外的名字带有「遗式」的怪兽存在的场合，直到结束阶段时场上的陷阱卡的效果无效。', '返回手牌', '陷阱的效果无效', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90566', '白森林的魔性 血蝠', '调整＋调整以外的怪兽1只以上
这个卡名的①的效果1回合只能使用1次。
①：这张卡特殊召唤的场合，从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。从卡组把1张「白森林」卡或1只魔法师族·光属性怪兽加入手卡。
②：只要这张卡在怪兽区域存在，自己场上的幻想魔族·魔法师族的同调怪兽攻击力上升500，不会被对方的效果破坏。', '卡组检索', '攻击力上升并破坏耐性', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90567', '白之圣女 艾克莉西娅', '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。
①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。
②：自己·对方的主要阶段，把这张卡解放才能发动。从手卡·卡组把1只「相剑」怪兽或「阿不思的落胤」特殊召唤。
③：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90568', '表里之女神', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「表里之女神」以外的1只持有进行投掷硬币效果的怪兽加入手卡。
②：自己主要阶段才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，自己场上的全部怪兽的攻击力直到回合结束时变成2倍。猜错的场合，自己场上的怪兽全部送去墓地，自己抽1张。', '检索', '猜硬币', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90569', '冰水啼 霓石精·海神', '水属性调整＋调整以外的怪兽1只以上
这个卡名的①②的效果1回合各能使用1次。
①：自己·对方回合可以发动。这个回合，自己场上的表侧表示怪兽不会被对方的效果破坏，不能用对方的效果除外。连锁对方的效果的发动把这个效果发动，那些同名卡在对方的场上·墓地存在的场合，可以再把那些同名卡全部除外。
②：这张卡在墓地存在，对方的效果让卡被除外的场合才能发动。这张卡特殊召唤。', '', '是否把对方发动的效果的同名卡除外？', '这张卡特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90570', '冰水帝 霓石精·海女神', '这个卡名的①的效果1回合只能使用1次。
①：从手卡把这张卡以外的1张「冰水」卡或者1只水属性怪兽丢弃才能发动。这张卡从手卡特殊召唤。那之后，可以在自己场上把1只「冰水衍生物」（水族·水·3星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是水属性怪兽不能从额外卡组特殊召唤。
②：这张卡只要有装备卡装备，卡名当作「冰水底 铬离子少女摇篮」使用。', '', '是否特殊召唤衍生物？', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90571', '冰水之霓石精', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「冰水」魔法·陷阱卡加入手卡。
②：这张卡成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。从自己的手卡·墓地选「冰水之霓石精」以外的1只水属性怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。这个回合，这张卡只有1次不会被战斗·效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90572', '虫之忍者-蜜', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上有「忍者」卡或者里侧守备表示怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：对方把怪兽的效果发动时，以自己场上1只里侧守备表示怪兽为对象才能发动。那只怪兽变成表侧守备表示，这张卡变成里侧守备表示。作为对象的怪兽是「虫之忍者-蜜」以外的「忍者」怪兽的场合，再把那个对方的所发动的效果无效。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90573', '无光之影 阿-宝·阿·库', '包含恶魔族怪兽的怪兽2只以上
这个卡名的①②的效果1回合各能使用1次。
①：自己·对方的主要阶段，可以丢弃1张手卡，从以下效果选择1个发动。
●场上1张卡破坏。
●这张卡直到结束阶段除外，从自己墓地把1只光·暗属性怪兽特殊召唤。
②：自己准备阶段才能发动。自己抽出自己墓地的怪兽的种族种类的数量。那之后，选抽出数量的自己手卡用喜欢的顺序回到卡组下面。', '发动效果', '抽卡', '破坏', '除外并特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90574', '海皇精 深渊莱茵', '这个卡名在规则上也当作「水精鳞」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：把手卡的这张卡和自己的手卡·场上1只「海皇」怪兽或「水精鳞」怪兽解放才能发动。从卡组选1只7星的鱼族·海龙族·水族怪兽加入手卡或特殊召唤。这个回合，自己不是水属性怪兽不能从额外卡组特殊召唤。
②：对方回合，把墓地的这张卡除外，把1张手卡丢弃去墓地才能发动。自己抽1张。', '特殊召唤', '抽卡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90575', '红泪之魔 落泪之日', '这个卡名在规则上也当作「刻魔」卡使用。这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「红泪之魔 落泪之日」以外的1张「刻魔」卡送去墓地。
②：对方回合，这张卡在墓地存在的场合，以自己墓地1只「刻魔」连接怪兽为对象才能发动。这张卡回到卡组，作为对象的怪兽特殊召唤。', '送去墓地', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90576', '结晶之大贤者 桑德里永', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤成功的场合，可以从以下效果选择1个发动。
●从卡组把1张「大贤者」魔法·陷阱卡加入手卡。
●选除外的1只自己的4星以下的魔法师族怪兽回到墓地。
②：把墓地的这张卡除外，以自己场上1只「大贤者」怪兽为对象才能发动。从自己墓地选1只4星以外的「大贤者」怪兽当作装备卡使用给作为对象的怪兽装备。', '从卡组把1张「大贤者」魔法·陷阱卡加入手卡', '选除外的1只自己的4星以下的魔法师族怪兽回到墓地', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90577', '六花精 叶牡丹', '这个卡名的①②的效果1回合各能使用1次。
①：把自己场上1只植物族怪兽解放才能发动。这张卡从手卡特殊召唤。
②：这张卡召唤或者用植物族怪兽的效果特殊召唤成功的场合才能发动。从卡组把1张「六花」魔法·陷阱卡加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90578', '圣骑士的追想 伊索德', '战士族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：这张卡连接召唤成功的场合才能发动。从卡组把1只战士族怪兽加入手卡。这个回合自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤，那些怪兽效果也不能发动。
②：从卡组把装备魔法卡任意数量送去墓地才能发动（同名卡最多1张）。和送去墓地的卡数量相同等级的1只战士族怪兽从卡组特殊召唤。', '卡组检索', '特殊召唤', '请选择要特殊召唤的怪兽的等级', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90579', '十二兽 兔铳', '①：这张卡被战斗·效果破坏的场合，以「十二兽 兔铳」以外的自己墓地1张「十二兽」卡为对象才能发动。那张卡加入手卡。
②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。
●这张卡为对象的对方的魔法卡的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。', '墓地「十二兽」卡加入手卡', '魔法卡的效果发动无效（十二兽 兔铳）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90580', '铁兽战线 姬特', '这个卡名的①②的效果1回合各能使用1次。
①：从自己墓地把兽族·兽战士族·鸟兽族怪兽任意数量除外才能发动。把持有和除外数量相同数量的连接标记的1只兽族·兽战士族·鸟兽族连接怪兽从额外卡组特殊召唤。这个回合，自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。
②：这张卡被送去墓地的场合才能发动。从卡组把「铁兽战线 姬特」以外的1张「铁兽」卡送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90581', '铁兽战线 徒花之费莉吉特', '兽族·兽战士族·鸟兽族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从手卡把1只4星以下的兽族·兽战士族·鸟兽族怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是兽族·兽战士族·鸟兽族怪兽不能作为连接素材。
②：这张卡被送去墓地的场合才能发动。自己从卡组抽1张，那之后选1张手卡回到卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90582', '对未来的沉默', '这个卡名的卡在1回合只能发动1张。
①：从卡组把有「光之黄金柜」的卡名记述的1只怪兽加入手卡。自己场上有着「光之黄金柜」以及有那个卡名记述的怪兽存在的状态，把这张卡在自己·对方的战斗阶段发动的场合，再让双方各自直到手卡变成6张为止抽卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90583', '真龙导士 威风凛·少女', '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。
①：1回合1次，上级召唤的这张卡存在，对方把魔法·陷阱·怪兽的效果发动时才能发动。从卡组把1只「真龙」怪兽加入手卡。', '解放魔法·陷阱卡上级召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90584', '洗脑', '①：支付800基本分，以对方场上1只可以通常召唤的表侧表示怪兽为对象才能发动。那只表侧表示怪兽的控制权直到结束阶段得到。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90585', '码丽丝<王后>红棋勒索', '包含「码丽丝」怪兽的怪兽2只以上
这个卡名的①③的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把1张「码丽丝」魔法卡加入手卡。
②：只要这张卡所连接区有怪兽存在，对方场上的效果怪兽的原本攻击力和原本守备力交换。
③：这张卡被除外的场合，支付900基本分才能发动。这张卡特殊召唤。那之后，可以从卡组把1只电子界族怪兽除外。', '检索', '', '特殊召唤', '是否把怪兽除外？', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90586', '码丽丝<兵卒>白兔', '这个卡名的①③的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。同名卡不在自己墓地存在的1张「码丽丝」陷阱卡从卡组到自己场上盖放。
②：有这张卡位于所连接区的「码丽丝」连接怪兽的战斗发生的对自己的战斗伤害变成0。
③：这张卡被除外的场合，支付300基本分才能发动。这张卡特殊召唤。这个回合，自己不是连接怪兽不能从额外卡组特殊召唤。', '盖放', '', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90587', '索菲娅之影灵衣', '「影灵衣」仪式魔法卡降临
这张卡若非以使用各自种族不同的自己场上3只怪兽来作的从手卡的仪式召唤则不能特殊召唤。
①：自己·对方的主要阶段1，从手卡把这张卡和1张「影灵衣」魔法卡丢弃才能发动。那次阶段内，对方不能从额外卡组把怪兽特殊召唤。
②：这张卡仪式召唤时才能发动（这个效果发动的回合，自己不能把其他怪兽通常召唤·特殊召唤）。这张卡以外的双方的场上·墓地的卡全部除外。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90588', '阿特拉之虫惑魔', '①：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。
②：只要这张卡在怪兽区域存在，自己可以把「洞」通常陷阱卡以及「落穴」通常陷阱卡从手卡发动。
③：只要这张卡在怪兽区域存在，自己的通常陷阱卡的发动以及那些发动的效果不会被无效化。', '适用「阿特拉之虫惑魔」的效果来发动', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90589', '芳香莉莉丝-迷迭香', '植物族怪兽2只以上
这个卡名的①②③的效果1回合各能使用1次。
①：这张卡特殊召唤的场合才能发动。从卡组把1张「芳香」卡加入手卡。
②：自己基本分回复的场合才能发动（伤害步骤也能发动）。从手卡把最多3只「芳香」怪兽在作为这张卡所连接区的自己场上特殊召唤。
③：把这张卡所连接区1只怪兽解放，以场上1张卡为对象才能发动。那张卡除外，自己回复1000基本分。', '检索', '从手卡特殊召唤', '卡片除外', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90590', '吸血鬼妖女', '①：这张卡召唤成功时或者自己场上有「吸血鬼」怪兽召唤时，以比这张卡攻击力高的对方场上1只怪兽为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。这个效果1回合只能使用1次。
②：这张卡的攻击力上升这张卡的效果装备的怪兽的原本攻击力数值。
③：用这张卡的效果把装备卡装备的这张卡被送去墓地的场合发动。这张卡从墓地特殊召唤。', '装备', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90591', '基诺之虫惑魔', '这个卡名的①的效果1回合只能使用1次。
①：自己场上有「虫惑魔」怪兽存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是昆虫族·植物族怪兽不能从额外卡组特殊召唤。
②：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。
③：自己的魔法与陷阱区域盖放的卡在1回合各有1次不会被效果破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90592', '天枪龙之影灵衣', '「影灵衣」仪式魔法卡降临
这张卡若非以只使用除7星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。
①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「影灵衣」怪兽为对象才能发动。那只怪兽在这个回合不会被战斗·效果破坏。
②：自己·对方回合，从手卡丢弃1张「影灵衣」卡，以场上1张卡为对象才能发动。那张卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90593', '暗黑树精', '←5 【灵摆】 5→
①：自己场上的地·水·炎·风属性怪兽的攻击力·守备力上升自己场上的怪兽的属性种类×200。
【怪兽效果】
①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选地·水·炎·风属性怪兽各1只用喜欢的顺序回到卡组上面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90594', '芙莉西亚之虫惑魔', '4星怪兽×2
①：持有超量素材的这张卡不受陷阱卡的效果影响。
②：只要这张卡在怪兽区域存在，「芙莉西亚之虫惑魔」以外的自己场上的「虫惑魔」怪兽不会被战斗·效果破坏，不会成为对方的效果的对象。
③：自己·对方回合1次，把这张卡1个超量素材取除，从卡组把1张「洞」通常陷阱卡或者「落穴」通常陷阱卡送去墓地才能发动。这个效果变成和那张陷阱卡发动时的效果相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90595', '炼机圣之影灵衣', '←5 【灵摆】 5→
这个卡名的灵摆效果1回合只能使用1次。
①：自己的「影灵衣」卡被表侧除外的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡除外。
【怪兽效果】
「影灵衣」仪式魔法卡降临
这张卡若非以只使用除9星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①的怪兽效果1回合只能使用1次。
①：自己·对方的主要阶段，以对方场上1只表侧表示怪兽为对象才能发动。这张卡直到结束阶段除外，作为对象的怪兽除外。
②：自己的「影灵衣」怪兽战斗破坏的怪兽不去墓地而除外。', '魔法·陷阱卡除外', '怪兽除外', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90596', '兰卡之虫惑魔', '①：这张卡召唤成功时才能发动。从卡组把1只「虫惑魔」怪兽加入手卡。
②：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。
③：1回合1次，以自己场上盖放的1张魔法·陷阱卡为对象才能发动。盖放的那张卡回到持有者手卡。那之后，可以从手卡把1张魔法·陷阱卡盖放。这个效果在对方回合也能发动。', '卡组检索', '回到手卡', '是否把魔法·陷阱卡盖放？', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90597', '小道里的牲祭', '自己场上的怪兽被战斗破坏的场合才能发动。从手卡特殊召唤1只「电子食人魔」。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90598', '白森林的阿斯忒瑞亚', '这个卡名的①②的效果1回合各能使用1次。
①：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。从卡组把1只魔法师族·光属性调整特殊召唤。
②：这张卡在墓地存在的状态，魔法·陷阱卡为让怪兽的效果发动而被送去自己墓地的场合才能发动。这张卡特殊召唤。', '从卡组特殊召唤', '从墓地特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90599', '白森林的森儿', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「白森林」魔法·陷阱卡加入手卡。
②：自己·对方回合，这张卡在墓地存在的场合，以自己的场上·墓地1只「白森林」同调怪兽为对象才能发动。那只怪兽回到额外卡组，这张卡效果无效特殊召唤。', '加入手卡', '墓地特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90600', '白森林的莉泽特', '这个卡名的①②的效果1回合各能使用1次。
①：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。这张卡从手卡特殊召唤。那之后，从卡组把「白森林的莉泽特」以外的1只「白森林」怪兽加入手卡。
②：这张卡在墓地存在的状态，对方回合自己场上有魔法师族·光属性调整特殊召唤的场合才能发动。这张卡加入手卡。', '手卡特殊召唤', '墓地加入手卡', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90601', '白森林的蝠儿', '这个卡名的①②③的效果1回合各能使用1次。
①：自己场上有「白森林」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。自己抽1张。
③：自己·对方回合，这张卡在墓地存在的场合，以自己的场上·墓地1只「白森林」同调怪兽为对象才能发动。那只怪兽回到额外卡组，这张卡效果无效特殊召唤。', '特殊召唤', '抽卡', '墓地特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90602', '白色少女', '这个卡名的①②③的效果1回合各能使用1次。
①：把手卡·场上的这张卡送去墓地才能发动。从自己的手卡·卡组·墓地把1张「真正之光」在自己的魔法与陷阱区域表侧表示放置。
②：这张卡在墓地存在的状态，自己把「青眼白龙」特殊召唤的场合才能发动。这张卡特殊召唤。
③：场上的这张卡成为攻击·效果的对象时才能发动。从自己墓地把1只「青眼白龙」或光属性·1星调整特殊召唤。', '表侧放置', '这张卡特殊召唤', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90603', '冰之魔妖-雪女', '「魔妖」怪兽2只
这个卡名的③的效果1回合只能使用1次。
①：「冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。
②：只要这张卡所连接区有同调怪兽存在，对方不能选择这张卡作为攻击对象。
③：这张卡在怪兽区域存在，自己的同调怪兽被战斗或者对方的效果破坏的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成一半。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90604', '垂冰之魔妖-雪女', '不死族怪兽2只以上
这个卡名的②③的效果1回合各能使用1次。
①：「垂冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。
②：这张卡特殊召唤成功的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效。
③：把墓地的这张卡除外才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只不死族同调怪兽特殊召唤。这个效果在对方回合也能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90605', '幻奏的华乐圣 花之哈摩妮丝特', '天使族怪兽2只
这个卡名的①的效果1回合只能使用1次。
①：这张卡连接召唤成功的场合，丢弃1张手卡才能发动。从卡组把2只等级不同的「幻奏」怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。这个效果发动的回合，自己不是「幻奏」怪兽不能特殊召唤。
②：这张卡所连接区的「幻奏」怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90606', '零冰之魔妖-雪女', '不死族怪兽2只以上
这个卡名的③的效果1回合可以使用最多2次。
①：「零冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。
②：只要这张卡在怪兽区域存在，除外的状态发动的对方怪兽的效果无效化。
③：从墓地有怪兽特殊召唤的场合或者墓地的怪兽的效果发动的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，那个效果无效。', '攻击力变成0', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90607', '灵道士 僵尸', '这个卡名的①②的效果1回合各能使用1次。
①：自己主要阶段才能发动。从手卡·卡组把1只不死族怪兽送去墓地。
②：这张卡被除外的场合，从自己墓地把1只不死族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到持有者卡组最下面。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90608', '灵王的波动', '这个卡名的卡在1回合只能发动1张。对方场上有卡存在的场合，这张卡的发动从手卡也能用。
①：包含把怪兽特殊召唤效果的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。自己墓地有陷阱卡存在的场合，再把那张无效的卡破坏。这张卡从手卡发动的场合，发动后，这次决斗中自己不能把光·地·风属性怪兽的效果发动。', '效果无效', '适用「灵王的波动」的效果来发动', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90609', '六花精 雪花莲', '这个卡名的①②的效果1回合各能使用1次。
①：把自己场上1只植物族怪兽解放才能发动。这张卡和1只植物族怪兽从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。
②：以自己场上1只植物族怪兽为对象才能发动。自己场上的全部植物族怪兽的等级直到回合结束时变成和作为对象的怪兽的等级相同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90610', '六花精 樱草', '这个卡名的①②的效果1回合各能使用1次。
①：自己场上的怪兽被解放的场合才能发动。这张卡从手卡守备表示特殊召唤。
②：以自己场上最多2只植物族怪兽为对象才能发动。那些怪兽的等级直到回合结束时上升2星。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90611', '来自墓场的引诱', '对方卡组最上面1张卡表面向上放回卡组洗切。对方抽到那张卡时，那张卡直接送去墓地。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90612', '尸界的班西', '这个卡名的②的效果1回合只能使用1次。
①：只要这张卡在怪兽区域存在，场地区域的「不死世界」不会被效果破坏，双方不能把那些卡作为效果的对象。
②：自己·对方回合，把场上·墓地的这张卡除外才能发动。从手卡·卡组把1张「不死世界」发动。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90613', '天威之龙仙女', '幻龙族怪兽2只
这个卡名的①②的效果1回合各能使用1次。
①：丢弃1张手卡，以自己墓地1只幻龙族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不能把「天威」怪兽以外的从额外卡组特殊召唤的场上的怪兽的效果发动。
②：效果怪兽以外的自己的表侧表示怪兽进行战斗的攻击宣言时，以对方场上1张卡为对象才能发动。那张卡破坏。', '特殊召唤', '卡片破坏', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90614', '炎王妃 火神不死鸟', '这个卡名的①②的效果1回合各能使用1次。
①：这张卡召唤·特殊召唤的场合才能发动。这张卡以外的自己的手卡·场上（表侧表示）1只炎属性怪兽破坏，「炎王妃 火神不死鸟」以外的1只兽族·兽战士族·鸟兽族的炎属性怪兽从卡组加入手卡。那之后，可以把这张卡的等级变成和这个效果加入手卡的怪兽相同。
②：这张卡被破坏送去墓地的场合才能发动。从卡组把1只「炎王神兽 大鹏不死鸟」守备表示特殊召唤。', '是否变成相同等级？', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90615', '影灵衣舞巫女 艾米莉娅', '这个卡名的①②的效果1回合各能使用1次。
①：自己的场上或墓地有战士族「影灵衣」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。
②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「影灵衣」仪式怪兽或1张「影灵衣」魔法卡加入手卡。
③：「影灵衣」仪式怪兽1只仪式召唤的场合，可以由自己场上的这1张卡作为仪式召唤需要的数值的解放使用。', '特殊召唤', '检索', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90616', '原罪之迪亚贝尔泽', '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。
①：自己或对方的墓地有「罪宝」卡存在的场合，这张卡可以从手卡特殊召唤。
②：只要这张卡在怪兽区域存在，对方不能把没有盖放的魔法·陷阱卡发动。
③：这张卡在怪兽区域存在的状态，场上有魔法·陷阱卡被盖放的场合，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90617', '花牙绚烂 名花异邦兰', '「花牙女忍 异邦兰」+「花牙女忍 异邦兰」
【条件】无
【效果】选自己手牌或者自己墓地的1只怪兽（等级8以下/植物族）以表侧表示特殊召唤到自己的场上。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90618', '青眼白龙·三体连结 ', '
青眼白龙装备「邪恶的暗锁」之后，变得更加强大。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90619', '鹰身女郎1', '这张卡的卡名当作「鹰身女郎」使用。只要这张卡在场上存在，场上的风属性怪兽攻击力上升300。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90620', '鹰身女郎 电子紧身装束', '这个卡名在规则上当作「鹰身女郎」使用。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90621', '古代的机械究极巨人', '「古代的机械巨人」＋「古代的机械」怪兽×2
这张卡不用融合召唤不能特殊召唤。
①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。
②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。
③：这张卡被破坏的场合，以自己墓地1只「古代的机械巨人」为对象才能发动。那只怪兽无视召唤条件特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90622', '歌冰丽月', '这个卡名的①②的效果1回合各能使用1次。
①：从手卡把1只4星以下的天使族·魔法师族·鸟兽族·兽战士族怪兽特殊召唤，把这张卡装备。那之后，可以让场上的龙族怪兽全部回到持有者手卡。
②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1张「融合」魔法卡或者1只「寄生融合虫」加入手卡。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90623', '真崎杏子', '在自己回合中，每付出300点生命值。就可查看对方场地上的牌，或者可以增加自己场地上的机械族怪兽的攻击力与守备力500点，此效果每回合只能使用一次。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90624', '洗脑', '①：支付800基本分，以对方场上1只可以通常召唤的表侧表示怪兽为对象才能发动。那只表侧表示怪兽的控制权直到结束阶段得到。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90625', '复烙印', '这个卡名的①的效果1回合只能使用1次，②的效果在同一连锁上只能发动1次。
①：光·暗属性怪兽被除外的场合，以那1只怪兽为对象才能发动。那只怪兽回到卡组最下面，自己抽1张。
②：1回合1次，对方把怪兽召唤·特殊召唤的场合，以自己墓地1只「深渊之兽」怪兽为对象才能发动。那只怪兽特殊召唤。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90626', '码丽丝<王后>白棋捆绑', '包含「码丽丝」怪兽的怪兽2只以上
这个卡名的①②③的效果1回合各能使用1次。
①：这张卡特殊召唤的场合，以自己·对方的墓地的卡合计最多3张为对象才能发动。那些卡除外。
②：自己主要阶段才能发动。从自己的卡组·墓地把1张「码丽丝」陷阱卡在自己场上盖放。
③：这张卡被除外的场合，支付900基本分才能发动。这张卡特殊召唤。那之后，自己可以抽1张。', '除外效果', '盖放陷阱', '特殊召唤', '是否抽卡？', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90627', '码丽丝<王后>红心加密', '包含「码丽丝」怪兽的怪兽3只
这个卡名的①②的效果1回合各能使用1次。
①：自己·对方回合，以自己的除外状态的1张「码丽丝」卡为对象才能发动（这张卡所连接区有怪兽存在的场合，这个效果的发动和效果不会被无效化）。那张卡回到卡组，场上1张卡除外。
②：这张卡被除外的场合，支付900基本分才能发动。这张卡的攻击力变成2倍特殊召唤。', '回收并除外', '特殊召唤', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90628', '超魔导剑士-黑魔导剑士', '「黑魔术师」＋「破坏之剑士」
这张卡不用融合召唤不能特殊召唤。
①：这张卡的攻击力上升双方的场上·墓地的龙族怪兽数量×500。
②：魔法卡发动时，丢弃1张手卡才能发动。这张卡在怪兽区域表侧表示存在的场合，那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);
INSERT INTO "texts" VALUES ('HCG90629', '黑魔法神官', '这张卡不能通常召唤。把自己场上2只6星以上的魔法师族怪兽解放的场合才能特殊召唤。
①：陷阱卡发动时才能发动。这张卡在场上表侧表示存在的场合，那个发动无效并破坏。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL);

